[300000] = {300000, "Hundred\u{0020}Refinements\u{0020}-\u{0020}Thousand\u{0020}Hammers", "Made\u{0020}by\u{0020}melting\u{0020}thousands\u{0020}of\u{0020}warhammers\u{0020}once\u{0020}used\u{0020}by\u{0020}Lulula.\nIn\u{0020}a\u{0020}way\u{0020}that\u{0020}cannot\u{0020}be\u{0020}analyzed\u{0020}by\u{0020}existing\u{0020}science\u{0020}and\u{0020}technology,\u{0020}it\u{0020}increases\u{0020}Lulula's\u{0020}power.\u{0020}Only\u{0020}she\u{0020}herself\u{0020}knows\u{0020}the\u{0020}weight\u{0020}of\u{0020}this.", "icon_lulula_zs1", "0", 4, 1, "3_{lv}*100", "Lulula", "1_110021_20", 10, "3_100", "300000,300001,300002", "0", "0", "0", "0", "0", "百炼·千锤", "由露露啦所使用过的数千把战锤熔炼而成。\n以一种无法用现有科学技术解析的方式增加着露露啦的力量，这其中的份量只有她自己知道吧。", "露露啦"},
[300001] = {300001, "Arm\u{0020}Guard\u{0020}-\u{0020}Hooked\u{0020}Curve", "A\u{0020}special\u{0020}metal\u{0020}arm\u{0020}guard\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}Compared\u{0020}to\u{0020}simply\u{0020}defending,\u{0020}this\u{0020}arm\u{0020}guard\u{0020}is\u{0020}more\u{0020}inclined\u{0020}to\u{0020}eliminate\u{0020}the\u{0020}enemy\u{0020}to\u{0020}achieve\u{0020}the\u{0020}purpose\u{0020}of\u{0020}defense.\nSaving\u{0020}the\u{0020}world\u{0020}is\u{0020}the\u{0020}true\u{0020}meaning\u{0020}of\u{0020}this\u{0020}arm\u{0020}guard.", "icon_lulula_zs2", "0", 4, 2, "3_{lv}*100", "Lulula", "1_110021_20", 10, "3_100", "300000,300001,300002", "0", "0", "0", "0", "0", "护臂·尖形钩曲", "艾吉斯设计并制造的特制金属护臂，相较于一味防守，这个护臂更倾向于消灭敌人以达成防御的目的。\n把受到原罪感染的人、把世界救济，这就是这个护臂真正的含义。", "露露啦"},
[300002] = {300002, "Sky\u{0020}Falcon", "A\u{0020}power\u{0020}device\u{0020}specially\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS\u{0020}for\u{0020}Lulula.\u{0020}Features\u{0020}a\u{0020}small\u{0020}Nimbus\u{0020}reactor\u{0020}and\u{0020}can\u{0020}provide\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}power\u{0020}for\u{0020}the\u{0020}user.\nAfter\u{0020}all,\u{0020}as\u{0020}the\u{0020}user\u{0020}wields\u{0020}a\u{0020}heavy\u{0020}weapon,\u{0020}its\u{0020}weight\u{0020}will\u{0020}increase\u{0020}as\u{0020}Lulula\u{0020}continuously\u{0020}uses,\u{0020}damages,\u{0020}and\u{0020}recasts\u{0020}it.\u{0020}How\u{0020}to\u{0020}carry\u{0020}this\u{0020}weight\u{0020}is\u{0020}one\u{0020}of\u{0020}the\u{0020}most\u{0020}difficult\u{0020}problems\u{0020}for\u{0020}the\u{0020}science\u{0020}department.", "icon_lulula_zs3", "0", 4, 3, "3_{lv}*100", "Lulula", "1_110021_20", 10, "3_100", "300000,300001,300002", "0", "0", "0", "0", "0", "天隼", "艾吉斯为露露啦专门设计并制造的动力装置，其内部整合了小型尼姆比斯反应堆，能够为使用者提供大量动力。\n毕竟使用者挥舞一把沉重的武器，它的重量会随着露露啦不断地使用、损毁、再熔铸而增加，而如何承载这份重量，是科学部最棘手的几个问题之一。", "露露啦"},
[300010] = {300010, "Tiny\u{0020}Ripple\u{0020}Dawn", "Installed\u{0020}a\u{0020}small\u{0020}Nimbus\u{0020}reactor\u{0020}on\u{0020}the\u{0020}heavy\u{0020}sword\u{0020}at\u{0020}Julius'\u{0020}personal\u{0020}request.\nAt\u{0020}the\u{0020}moment\u{0020}of\u{0020}lifting\u{0020}the\u{0020}restriction,\u{0020}the\u{0020}plasma\u{0020}it\u{0020}sprays\u{0020}is\u{0020}enough\u{0020}to\u{0020}melt\u{0020}anything\u{0020}blocking\u{0020}in\u{0020}front\u{0020}of\u{0020}it.", "icon_zlws_zs1", "0", 4, 1, "3_{lv}*100", "Julius", "1_110021_20", 10, "3_100", "300010,300011,300012", "0", "0", "0", "0", "0", "微澜晨光", "应朱利乌斯的个人要求，在重剑上安装了小型尼姆比斯反应堆。\n在解除限制的那一刻，其喷射的等离子体足以融化阻挡在它身前的任何事物。", "朱利乌斯"},
[300011] = {300011, "Pure\u{0020}White\u{0020}Guard", "A\u{0020}special\u{0020}shield\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}Its\u{0020}defense\u{0020}power\u{0020}is\u{0020}sufficient\u{0020}to\u{0020}take\u{0020}a\u{0020}frontal\u{0020}bombardment\u{0020}of\u{0020}an\u{0020}axe-type\u{0020}missile.\nIf\u{0020}the\u{0020}shield\u{0020}on\u{0020}the\u{0020}arm\u{0020}guard\u{0020}is\u{0020}not\u{0020}enough\u{0020}to\u{0020}block\u{0020}the\u{0020}enemy's\u{0020}attack,\u{0020}Julius\u{0020}will\u{0020}definitely\u{0020}use\u{0020}his\u{0020}body\u{0020}to\u{0020}block\u{0020}it,\u{0020}right?\u{0020}So\u{0020}when\u{0020}I\u{0020}made\u{0020}the\u{0020}arm\u{0020}guard,\u{0020}I\u{0020}specifically\u{0020}strengthened\u{0020}this\u{0020}function.\u{0020}I\u{0020}feel\u{0020}a\u{0020}lot\u{0020}of\u{0020}pressure.\u{0020}-\u{0020}Said\u{0020}a\u{0020}scientific\u{0020}researcher\u{0020}who\u{0020}has\u{0020}contacted\u{0020}Julius.", "icon_zlws_zs2", "0", 4, 2, "3_{lv}*100", "Julius", "1_110021_20", 10, "3_100", "300010,300011,300012", "0", "0", "0", "0", "0", "纯白护胄", "艾吉斯设计并制造的特制盾牌，其防御力足以抵挡战斧式导弹的正面轰击。\n如果护臂上的盾牌不足以抗下敌人的攻击，朱利乌斯一定会用身躯来阻挡攻击的吧？所以我制造护臂的时候特意强化了这方面的功能，感觉压力很大。——接触过朱利乌斯的科研人员如此表示。", "朱利乌斯"},
[300012] = {300012, "White\u{0020}Kite", "A\u{0020}power\u{0020}device\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}Features\u{0020}a\u{0020}small\u{0020}Nimbus\u{0020}reactor\u{0020}and\u{0020}provides\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}power\u{0020}for\u{0020}the\u{0020}user.\nWith\u{0020}the\u{0020}special\u{0020}function\u{0020}of\u{0020}Julius'\u{0020}guard,\u{0020}the\u{0020}production\u{0020}demand\u{0020}for\u{0020}power\u{0020}devices\u{0020}has\u{0020}also\u{0020}been\u{0020}put\u{0020}on\u{0020}the\u{0020}agenda.\u{0020}It's\u{0020}really\u{0020}adding\u{0020}to\u{0020}one's\u{0020}own\u{0020}workload.\u{0020}-\u{0020}Commented\u{0020}by\u{0020}a\u{0020}colleague\u{0020}in\u{0020}the\u{0020}research\u{0020}department.", "icon_zlws_zs3", "0", 4, 3, "3_{lv}*100", "Julius", "1_110021_20", 10, "3_100", "300010,300011,300012", "0", "0", "0", "0", "0", "白鸢", "艾吉斯设计并制造的动力装置，其内部整合了小型尼姆比斯反应堆，能够为使用者提供大量动力。\n伴随着朱利乌斯护胄的特殊功能，动力装置的制作需求也被提上日程，简直是给自己增加工作量。——一位科研部的同事如此评论道。", "朱利乌斯"},
[300020] = {300020, "Beggar", "Made\u{0020}of\u{0020}high-density\u{0020}alloy\u{0020}and\u{0020}a\u{0020}large\u{0020}number\u{0020}of\u{0020}Nimbus\u{0020}crystals,\u{0020}it\u{0020}has\u{0020}the\u{0020}functions\u{0020}of\u{0020}adjusting\u{0020}its\u{0020}weight\u{0020}and\u{0020}shape.\n\"Although\u{0020}the\u{0020}name\u{0020}of\u{0020}the\u{0020}weapon\u{0020}is\u{0020}Beggar,\u{0020}in\u{0020}fact,\u{0020}I\u{0020}only\u{0020}have\u{0020}food\u{0020}to\u{0020}eat\u{0020}because\u{0020}of\u{0020}this\u{0020}weapon...\u{0020}I\u{0020}am\u{0020}the\u{0020}one\u{0020}who\u{0020}begs\u{0020}for\u{0020}food.\"", "icon_hanke_zs1", "0", 2, 1, "3_{lv}*100", "Hank", "1_110021_5", 10, "3_100", "300020,300021,300022", "0", "0", "0", "0", "0", "乞食者", "由高密度的合金和大量的尼姆比斯结晶打造而成，拥有调节其自身重力、改变自身形状的功能。\n“虽然说，武器的名字叫乞食者，但其实我是靠着这件武器才有饭吃的嘛……我才是那个乞食的人才对。”", "汉克"},
[300021] = {300021, "Deflection\u{0020}Field", "Equipped\u{0020}with\u{0020}a\u{0020}small\u{0020}propulsion\u{0020}device\u{0020}and\u{0020}leg\u{0020}blades,\u{0020}it\u{0020}is\u{0020}an\u{0020}armor\u{0020}with\u{0020}both\u{0020}output\u{0020}and\u{0020}defense.\nJust\u{0020}need\u{0020}to\u{0020}slightly\u{0020}deflect\u{0020}the\u{0020}opponent's\u{0020}trajectory.\u{0020}This\u{0020}subtle\u{0020}deflection\u{0020}angle\u{0020}is\u{0020}enough\u{0020}to\u{0020}vanquish\u{0020}the\u{0020}opponent.", "icon_hanke_zs2", "0", 2, 2, "1_{lv}*100", "Hank", "1_110021_5", 10, "1_100", "300020,300021,300022", "0", "0", "0", "0", "0", "偏移力场", "装有小型推进装置和腿刃，是一款输出与防御齐备的装甲。\n只需要稍微偏移对方的弹道即可，这微妙的偏移角度足以夺去对面的生命。", "汉克"},
[300022] = {300022, "Balanced\u{0020}Scale", "A\u{0020}flight\u{0020}equipment\u{0020}known\u{0020}for\u{0020}its\u{0020}strong\u{0020}balance\u{0020}performance\u{0020}and\u{0020}mobility.\nHank\u{0020}has\u{0020}very\u{0020}distorted\u{0020}demands\u{0020}for\u{0020}the\u{0020}stability\u{0020}and\u{0020}mobility\u{0020}of\u{0020}flight\u{0020}equipment...\u{0020}For\u{0020}the\u{0020}time\u{0020}being,\u{0020}it\u{0020}is\u{0020}considered\u{0020}as\u{0020}the\u{0020}keen\u{0020}sense\u{0020}of\u{0020}equipment\u{0020}of\u{0020}a\u{0020}battle-tested\u{0020}person.", "icon_hanke_zs3", "0", 2, 3, "1_{lv}*100", "Hank", "1_110021_5", 10, "1_100", "300020,300021,300022", "0", "0", "0", "0", "0", "均衡天平", "以超强的平衡性能和机动能力著称的飞行装备。\n汉克对飞行装备的稳定、机动有着非常扭曲的诉求……姑且认为这是久进沙场之人对装备的敏锐嗅觉。", "汉克"},
[300030] = {300030, "Ghost's\u{0020}Fang", "A\u{0020}close\u{0020}combat\u{0020}weapon\u{0020}made\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}This\u{0020}weapon\u{0020}has\u{0020}two\u{0020}forms:\u{0020}long\u{0020}spear\u{0020}and\u{0020}trident.\n[Fang]\u{0020}has\u{0020}high\u{0020}requirements\u{0020}for\u{0020}the\u{0020}user.\u{0020}It\u{0020}was\u{0020}made\u{0020}by\u{0020}a\u{0020}certain\u{0020}scientific\u{0020}researcher\u{0020}on\u{0020}a\u{0020}whim\u{0020}without\u{0020}considering\u{0020}the\u{0020}user\u{0020}at\u{0020}all.\u{0020}If\u{0020}it\u{0020}weren't\u{0020}for\u{0020}Kinosuke,\u{0020}maybe\u{0020}it\u{0020}would\u{0020}stay\u{0020}in\u{0020}the\u{0020}equipment\u{0020}warehouse\u{0020}forever.", "icon_sencunguizhijie_zs1", "0", 2, 1, "3_{lv}*100", "Morimura\u{0020}Kinosuke", "1_110021_5", 10, "3_100", "300030,300031,300032", "0", "0", "0", "0", "0", "鬼之牙", "由九州总部制作的近战兵器，该武器拥有长枪和三叉俩种形态。\n【牙】对使用者的要求极高，它是某位科研人员脑袋一热完全不考虑使用者而制作的，如果不是鬼之介，也许它会一直躺在装备库里吧。", "森村鬼之介"},
[300031] = {300031, "Ghost's\u{0020}Horn", "A\u{0020}psychokinesis\u{0020}control\u{0020}device\u{0020}made\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}This\u{0020}device\u{0020}is\u{0020}integrated\u{0020}with\u{0020}high-density\u{0020}Nimbus\u{0020}crystals\u{0020}and\u{0020}will\u{0020}greatly\u{0020}enhance\u{0020}the\u{0020}resonance\u{0020}data\u{0020}of\u{0020}AVG\u{0020}in\u{0020}battle,\u{0020}but\u{0020}the\u{0020}side\u{0020}effects\u{0020}are\u{0020}extremely\u{0020}great.\n\"Those\u{0020}who\u{0020}can\u{0020}withstand\u{0020}this\u{0020}are\u{0020}truly\u{0020}ghosts\u{0020}and\u{0020}gods,\u{0020}right?!\"\u{0020}Early\u{0020}work\u{0020}of\u{0020}a\u{0020}certain\u{0020}scientific\u{0020}researcher.", "icon_sencunguizhijie_zs2", "0", 2, 2, "1_{lv}*100", "Morimura\u{0020}Kinosuke", "1_110021_5", 10, "1_100", "300030,300031,300032", "0", "0", "0", "0", "0", "鬼之角", "由九州总部制作的精神力控制装置，该装置上融入了高密度的尼姆比斯结晶体，在战斗中会大幅度的提高AVG的共鸣数据，但副作用极大。\n“能承受住这个的，是真正的鬼神吧？！”某位科研人员的早期作品。", "森村鬼之介"},
[300032] = {300032, "Ghost's\u{0020}Blood\u{0020}Armor", "Armor\u{0020}specially\u{0020}made\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}the\u{0020}Fuurinkazan\u{0020}squad.\u{0020}This\u{0020}armor\u{0020}has\u{0020}extremely\u{0020}high\u{0020}protection\u{0020}and\u{0020}is\u{0020}light\u{0020}in\u{0020}weight.\nArmor\u{0020}customized\u{0020}for\u{0020}those\u{0020}who\u{0020}hold\u{0020}[Fang]\u{0020}and\u{0020}[Horn].\u{0020}\"Since\u{0020}she\u{0020}bears\u{0020}our\u{0020}bad\u{0020}design\u{0020}ideas,\u{0020}then\u{0020}take\u{0020}this\u{0020}equipment\u{0020}as\u{0020}a\u{0020}cursed\u{0020}gift.\u{0020}If\u{0020}[Fang]\u{0020}and\u{0020}[Horn]\u{0020}represent\u{0020}ignorance\u{0020}and\u{0020}beginning,\u{0020}then\u{0020}this\u{0020}equipment\u{0020}is\u{0020}the\u{0020}accumulation\u{0020}of\u{0020}our\u{0020}dreams.\"", "icon_sencunguizhijie_zs3", "0", 2, 3, "3_{lv}*100", "Morimura\u{0020}Kinosuke", "1_110021_5", 10, "3_100", "300030,300031,300032", "0", "0", "0", "0", "0", "鬼之血铠", "由九州总部制作的风林火山小队专用装甲，该装甲拥有极高的防护且但重量极轻。\n为持【牙】配【角】者而定制的装甲，“既然她承载了我们糟糕的设计想法，那就把这件装备作为诅咒的赠礼吧，如果说【牙】和【角】代表着懵懂、开端，那这件装备就是我们梦想的积淀。”", "森村鬼之介"},
[300040] = {300040, "Adjudication", "This\u{0020}is\u{0020}a\u{0020}general-purpose\u{0020}close\u{0020}combat\u{0020}equipment\u{0020}equipped\u{0020}for\u{0020}the\u{0020}mass-produced\u{0020}type\u{0020}B2\u{0020}robots\u{0020}made\u{0020}by\u{0020}the\u{0020}Maya\u{0020}branch.\u{0020}There\u{0020}is\u{0020}a\u{0020}power\u{0020}engine\u{0020}inside\u{0020}the\u{0020}weapon.\u{0020}Through\u{0020}rotation,\u{0020}the\u{0020}piercing\u{0020}ability\u{0020}is\u{0020}improved.\nType\u{0020}D\u{0020}will\u{0020}defeat\u{0020}all\u{0020}enemies\u{0020}for\u{0020}the\u{0020}god\u{0020}who\u{0020}created\u{0020}them.", "icon_b2_zs1", "0", 4, 1, "3_{lv}*100", "D-b2", "1_110021_20", 10, "3_100", "300040,300041,300042", "0", "0", "0", "0", "0", "0", "0", "0"},
[300041] = {300041, "Black\u{0020}Angel", "This\u{0020}is\u{0020}a\u{0020}general-purpose\u{0020}close\u{0020}combat\u{0020}equipment\u{0020}equipped\u{0020}for\u{0020}the\u{0020}mass-produced\u{0020}type\u{0020}B2\u{0020}robots\u{0020}made\u{0020}by\u{0020}the\u{0020}Maya\u{0020}branch.\u{0020}It\u{0020}has\u{0020}the\u{0020}ability\u{0020}to\u{0020}set\u{0020}up\u{0020}an\u{0020}energy\u{0020}shield,\u{0020}but\u{0020}it\u{0020}consumes\u{0020}extremely\u{0020}large\u{0020}energy\u{0020}of\u{0020}the\u{0020}transformation\u{0020}core.\nWe\u{0020}are\u{0020}[Specter],\u{0020}the\u{0020}specters\u{0020}that\u{0020}guard\u{0020}people's\u{0020}safety.", "icon_b2_zs2", "0", 4, 2, "3_{lv}*100", "D-b2", "1_110021_20", 10, "3_100", "300040,300041,300042", "0", "0", "0", "0", "0", "0", "0", "0"},
[300042] = {300042, "Judgment\u{0020}Day", "This\u{0020}is\u{0020}a\u{0020}general-purpose\u{0020}close\u{0020}combat\u{0020}equipment\u{0020}equipped\u{0020}for\u{0020}the\u{0020}mass-produced\u{0020}type\u{0020}B2\u{0020}robots\u{0020}made\u{0020}by\u{0020}the\u{0020}Maya\u{0020}branch.\u{0020}By\u{0020}consuming\u{0020}the\u{0020}energy\u{0020}of\u{0020}the\u{0020}transformation\u{0020}core,\u{0020}it\u{0020}increases\u{0020}the\u{0020}movement\u{0020}speed\u{0020}and\u{0020}has\u{0020}extremely\u{0020}high\u{0020}power.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}it\u{0020}can\u{0020}reach\u{0020}supersonic\u{0020}speed\u{0020}in\u{0020}full\u{0020}power\u{0020}state.\nWhat\u{0020}kind\u{0020}of\u{0020}ending\u{0020}will\u{0020}we\u{0020}embrace\u{0020}on\u{0020}the\u{0020}final\u{0020}judgment\u{0020}day?", "icon_b2_zs3", "0", 4, 3, "3_{lv}*100", "D-b2", "1_110021_20", 10, "3_100", "300040,300041,300042", "0", "0", "0", "0", "0", "0", "0", "0"},
[300050] = {300050, "Taihao\u{0020}Fine\u{0020}Gold\u{0020}Weevil", "A\u{0020}protective\u{0020}robot\u{0020}specially\u{0020}developed\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}Although\u{0020}this\u{0020}device\u{0020}is\u{0020}not\u{0020}equipped\u{0020}with\u{0020}particularly\u{0020}powerful\u{0020}firepower\u{0020}equipment,\u{0020}it\u{0020}has\u{0020}an\u{0020}ultra-computing\u{0020}automatic\u{0020}defense\u{0020}system.\n\"This\u{0020}is\u{0020}the\u{0020}weevil...?\u{0020}I\u{0020}thought\u{0020}it\u{0020}was\u{0020}really\u{0020}some\u{0020}kind\u{0020}of\u{0020}bug...\"", "icon_hualian_zs1", "0", 3, 1, "3_{lv}*100", "Hualian", "1_110021_10", 10, "3_100", "300050,300051,300052", "0", "0", "0", "0", "0", "太昊精金象鼻虫", "由九州总部特研制的一种防护型机器人，虽然该装置上没有装载特别厉害的火力装备，但是拥有超运算的自动防卫系统。\n“这就是象鼻虫……？小生还以为是真的什么虫子呢……”", "华恋"},
[300051] = {300051, "Manifestation\u{0020}and\u{0020}Unification\u{0020}-\u{0020}Wind\u{0020}Listener", "A\u{0020}communication\u{0020}device\u{0020}specially\u{0020}developed\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}Although\u{0020}the\u{0020}shape\u{0020}seems\u{0020}simple,\u{0020}it\u{0020}has\u{0020}extremely\u{0020}strong\u{0020}signal\u{0020}penetration\u{0020}ability.\n\"By\u{0020}the\u{0020}way,\u{0020}why\u{0020}are\u{0020}the\u{0020}names\u{0020}of\u{0020}our\u{0020}Tian\u{0020}Hua\u{0020}Pavilion's\u{0020}equipment\u{0020}all\u{0020}so\u{0020}wordy...\"", "icon_hualian_zs2", "0", 3, 2, "3_{lv}*100", "Hualian", "1_110021_10", 10, "3_100", "300050,300051,300052", "0", "0", "0", "0", "0", "显圣归一顺风耳", "由九州总部特研制的一种通信装置，造型看似简单，却拥有超强的信号穿透能力。\n“话说，咱们天华阁的装备名字怎么都这么文绉绉的……”", "华恋"},
[300052] = {300052, "Primordial\u{0020}Thousand\u{0020}Miles\u{0020}Escape\u{0020}Boots", "A\u{0020}power\u{0020}equipment\u{0020}specially\u{0020}developed\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}The\u{0020}appearance\u{0020}is\u{0020}similar\u{0020}to\u{0020}a\u{0020}pair\u{0020}of\u{0020}cloth\u{0020}shoes,\u{0020}but\u{0020}it\u{0020}has\u{0020}a\u{0020}dual\u{0020}system\u{0020}of\u{0020}gravity\u{0020}and\u{0020}power.\n\"I\u{0020}just\u{0020}need\u{0020}this\u{0020}kind\u{0020}of\u{0020}equipment\u{0020}that\u{0020}runs\u{0020}fast!\u{0020}Can\u{0020}easily\u{0020}catch\u{0020}up\u{0020}with\u{0020}the\u{0020}enemy!\"", "icon_hualian_zs3", "0", 3, 3, "1_{lv}*100", "Hualian", "1_110021_10", 10, "1_100", "300050,300051,300052", "0", "0", "0", "0", "0", "混元万里遁行靴", "由九州总部特研制的一种动力装备，外表酷似一双布鞋，但是拥有重力和动力双重系统。\n“小生就需要这种跑得快的装备！能轻松追上敌人！”", "华恋"},
[300060] = {300060, "Light\u{0020}Chasing", "This\u{0020}equipment\u{0020}is\u{0020}processed\u{0020}from\u{0020}the\u{0020}body\u{0020}of\u{0020}a\u{0020}superior\u{0020}sin\u{0020}as\u{0020}raw\u{0020}material.\u{0020}Under\u{0020}the\u{0020}catalysis\u{0020}of\u{0020}the\u{0020}transformation\u{0020}core,\u{0020}a\u{0020}plasma\u{0020}light\u{0020}blade\u{0020}is\u{0020}generated.\u{0020}It\u{0020}can\u{0020}easily\u{0020}cut\u{0020}through\u{0020}any\u{0020}hard\u{0020}substance\u{0020}and\u{0020}has\u{0020}extremely\u{0020}low\u{0020}energy\u{0020}consumption.\nJust\u{0020}like\u{0020}its\u{0020}name,\u{0020}when\u{0020}wielding\u{0020}it,\u{0020}the\u{0020}remaining\u{0020}light\u{0020}will\u{0020}leave\u{0020}a\u{0020}light\u{0020}band\u{0020}where\u{0020}it\u{0020}passes,\u{0020}as\u{0020}if\u{0020}light\u{0020}is\u{0020}chasing\u{0020}the\u{0020}blade.", "icon_xiliwaerte_zs1", "0", 3, 1, "1_{lv}*100", "Celine\u{0020}Walter", "1_110021_10", 10, "1_100", "300060,300061,300062", "0", "0", "0", "0", "0", "光追", "该装备是以上位原罪身体作为素材加工而成，在幻化核心的催化下生成的等离子光刃。可以轻易的切开任何坚硬的物质，且对能量消耗极低。\n如同它的名字一样，挥舞它的时候，残留的光会在划过的地方留下光带，仿佛光能在追逐着斧刃一般。", "栖林·瓦尔特"},
[300061] = {300061, "Bobcat", "Ms.\u{0020}Celine\u{0020}deleted\u{0020}this\u{0020}description.\nCute\u{0020}in\u{0020}appearance\u{0020}and\u{0020}designed\u{0020}with\u{0020}luxury\u{0020}fashion.\u{0020}Although\u{0020}it\u{0020}may\u{0020}not\u{0020}be\u{0020}powerful\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}Celine\u{0020}thinks\u{0020}that\u{0020}dressing\u{0020}appropriately\u{0020}is\u{0020}also\u{0020}very\u{0020}important.\u{0020}You\u{0020}can\u{0020}only\u{0020}fight\u{0020}in\u{0020}a\u{0020}good\u{0020}mood.", "icon_xiliwaerte_zs2", "0", 3, 2, "3_{lv}*100", "Celine\u{0020}Walter", "1_110021_10", 10, "3_100", "300060,300061,300062", "0", "0", "0", "0", "0", "山猫", "栖琳女士删除了这段描述。\n外观可爱且设计高端时尚，虽然在战场上不一定能派上用场，但是栖林觉得穿着得体非常重要，心情好！才能更好的战斗。", "栖林·瓦尔特"},
[300062] = {300062, "Auto\u{0020}Arm\u{0020}Shield\u{0020}I", "This\u{0020}armor\u{0020}is\u{0020}equipped\u{0020}with\u{0020}an\u{0020}AI.\u{0020}When\u{0020}attacked,\u{0020}it\u{0020}will\u{0020}automatically\u{0020}block\u{0020}the\u{0020}vital\u{0020}parts.\nBecause\u{0020}of\u{0020}Celine's\u{0020}activity\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}ordinary\u{0020}arm\u{0020}shields\u{0020}have\u{0020}lost\u{0020}their\u{0020}functions.\u{0020}This\u{0020}is\u{0020}a\u{0020}new\u{0020}product\u{0020}with\u{0020}AI\u{0020}protection\u{0020}function.\u{0020}By\u{0020}the\u{0020}way...\u{0020}Can\u{0020}it\u{0020}really\u{0020}be\u{0020}called\u{0020}an\u{0020}arm\u{0020}shield?", "icon_xiliwaerte_zs3", "0", 3, 3, "3_{lv}*100", "Celine\u{0020}Walter", "1_110021_10", 10, "3_100", "300060,300061,300062", "0", "0", "0", "0", "0", "自律臂盾Ⅰ", "该装甲上装载自律AI，在受到攻击时，会自动挡住要害的部位。\n因为栖琳在战场上的活跃性，普通的臂盾已经失去了它的作用，这是添加了AI防护功能的新产品，话说……它真的能被称之为臂盾吗。", "栖林·瓦尔特"},
[300070] = {300070, "Voyager", "A\u{0020}water-based\u{0020}weapon\u{0020}made\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}naval\u{0020}weapons\u{0020}research\u{0020}department.\u{0020}Equipped\u{0020}with\u{0020}an\u{0020}electric\u{0020}energy\u{0020}conversion\u{0020}system,\u{0020}injecting\u{0020}liquid\u{0020}can\u{0020}generate\u{0020}lightning\u{0020}and\u{0020}has\u{0020}a\u{0020}launching\u{0020}function.\u{0020}It\u{0020}is\u{0020}a\u{0020}weapon\u{0020}with\u{0020}both\u{0020}long-range\u{0020}and\u{0020}short-range\u{0020}capabilities.\nIt\u{0020}is\u{0020}said\u{0020}that\u{0020}when\u{0020}scientists\u{0020}received\u{0020}the\u{0020}production\u{0020}requirements,\u{0020}they\u{0020}were\u{0020}anxious\u{0020}for\u{0020}a\u{0020}long\u{0020}time,\u{0020}because\u{0020}when\u{0020}Uki\u{0020}described\u{0020}the\u{0020}requirements,\u{0020}she\u{0020}only\u{0020}said,\u{0020}\"Something\u{0020}like\u{0020}the\u{0020}harpoon\u{0020}I\u{0020}used\u{0020}in\u{0020}my\u{0020}hometown\u{0020}is\u{0020}fine.\"", "icon_haiji_zs1", "0", 2, 1, "1_{lv}*100", "Uki", "1_110021_5", 10, "1_100", "300070,300071,300072", "0", "0", "0", "0", "0", "远航者", "由九州海军兵器研究部制作的水上武器，装有电能转化系统，注入液体就能产生雷电，并能拥有发射功能，是一种远近兼备的武器。\n据说科研人员拿到装备制作需求的时候焦头烂额了好久，因为海姬本人对装备的需求只说了“像我在老家时用的鱼叉那样的就可以了”。", "海姬"},
[300071] = {300071, "Lady's\u{0020}Communicator\u{0020}Generation\u{0020}II", "A\u{0020}communicator\u{0020}made\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}naval\u{0020}weapons\u{0020}research\u{0020}department.\u{0020}In\u{0020}addition\u{0020}to\u{0020}having\u{0020}basic\u{0020}communication\u{0020}functions,\u{0020}it\u{0020}is\u{0020}also\u{0020}equipped\u{0020}with\u{0020}a\u{0020}detection\u{0020}radar\u{0020}that\u{0020}can\u{0020}detect\u{0020}the\u{0020}biological\u{0020}coordinates\u{0020}within\u{0020}a\u{0020}range\u{0020}of\u{0020}2\u{0020}nautical\u{0020}miles.\nThe\u{0020}first-generation\u{0020}version\u{0020}of\u{0020}this\u{0020}equipment\u{0020}is\u{0020}not\u{0020}waterproof...\u{0020}not\u{0020}waterproof...", "icon_haiji_zs2", "0", 2, 2, "3_{lv}*100", "Uki", "1_110021_5", 10, "3_100", "300070,300071,300072", "0", "0", "0", "0", "0", "淑女型通信器二代", "由九州海军兵器研究部制作的通信器，除了具备基本的通信功能外面，还装备了探测雷达，可以检索范围2海里内的所有生物坐标。\n这件装备的初代版本，不防水……不防水……", "海姬"},
[300072] = {300072, "Fish\u{0020}Scale", "A\u{0020}general-purpose\u{0020}protective\u{0020}gear\u{0020}made\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}naval\u{0020}weapons\u{0020}research\u{0020}department.\u{0020}Equipped\u{0020}with\u{0020}an\u{0020}auto\u{0020}defense\u{0020}system,\u{0020}it\u{0020}can\u{0020}automatically\u{0020}resist\u{0020}attacks\u{0020}from\u{0020}the\u{0020}front.\nUki\u{0020}herself\u{0020}doesn't\u{0020}care\u{0020}much\u{0020}about\u{0020}this\u{0020}equipment.\u{0020}Because\u{0020}getting\u{0020}in\u{0020}the\u{0020}water\u{0020}is\u{0020}like\u{0020}returning\u{0020}to\u{0020}home.\u{0020}Like\u{0020}a\u{0020}swimming\u{0020}fish,\u{0020}it\u{0020}is\u{0020}rare\u{0020}for\u{0020}her\u{0020}to\u{0020}be\u{0020}attacked\u{0020}from\u{0020}the\u{0020}front.", "icon_haiji_zs3", "0", 2, 3, "3_{lv}*100", "Uki", "1_110021_5", 10, "3_100", "300070,300071,300072", "0", "0", "0", "0", "0", "鱼鳞", "由九州海军兵器研究部制作的通用型防具，装有自律防卫系统，可以自动抵挡来自正面的攻击。\n海姬本人对这件装备不太感冒，因为在水中的她犹如回到了自己家，像游鱼一般的她，很难受到从正面发动的攻击。", "海姬"},
[300080] = {300080, "Knight's\u{0020}Glimmer", "Equipment\u{0020}developed\u{0020}by\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}for\u{0020}Dolores.\u{0020}It\u{0020}is\u{0020}composed\u{0020}of\u{0020}a\u{0020}light\u{0020}defensive\u{0020}shield\u{0020}made\u{0020}of\u{0020}three\u{0020}units\u{0020}of\u{0020}titanium.\u{0020}In\u{0020}battle,\u{0020}it\u{0020}can\u{0020}be\u{0020}freely\u{0020}disassembled\u{0020}to\u{0020}achieve\u{0020}tactical\u{0020}purposes.\nThis\u{0020}is\u{0020}the\u{0020}beginning\u{0020}of\u{0020}the\u{0020}little\u{0020}knight's\u{0020}biography.\u{0020}The\u{0020}young\u{0020}knight\u{0020}Dolores\u{0020}sets\u{0020}off\u{0020}on\u{0020}a\u{0020}journey.", "icon_duoluolisi_zs1", "0", 2, 1, "3_{lv}*100", "Dolores", "1_110021_5", 10, "3_100", "300080,300081,300082", "0", "0", "0", "0", "0", "骑士微光", "由多瑙支部为多洛莉丝研发的装备，由三个单位的足钛打造的轻型防卫盾牌组合而成，在战斗中可以自由拆解，以达到战术目的。\n这是小小骑士传记的开始，年轻的骑士多洛莉丝踏上了征途。", "多洛莉丝"},
[300081] = {300081, "Listen\u{0020}to\u{0020}Prayers", "Equipment\u{0020}developed\u{0020}by\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}for\u{0020}Dolores.\u{0020}In\u{0020}addition\u{0020}to\u{0020}being\u{0020}equipped\u{0020}with\u{0020}a\u{0020}basic\u{0020}defense\u{0020}system\u{0020}and\u{0020}communication\u{0020}system,\u{0020}this\u{0020}armament\u{0020}features\u{0020}a\u{0020}gravity\u{0020}conversion\u{0020}system,\u{0020}which\u{0020}can\u{0020}slightly\u{0020}adjust\u{0020}the\u{0020}user's\u{0020}gravity.\nRelax\u{0020}your\u{0020}spirit\u{0020}and\u{0020}listen\u{0020}to\u{0020}the\u{0020}prayer.\u{0020}This\u{0020}will\u{0020}make\u{0020}the\u{0020}body\u{0020}of\u{0020}the\u{0020}little\u{0020}knight\u{0020}lighter\u{0020}and\u{0020}more\u{0020}flexible.", "icon_duoluolisi_zs2", "0", 2, 2, "3_{lv}*100", "Dolores", "1_110021_5", 10, "3_100", "300080,300081,300082", "0", "0", "0", "0", "0", "聆听祷言", "由多瑙支部为多洛莉丝研发的装备，该武装除了配备了基本的防卫系统和通信系统，还加入了重力转化系统，可以小幅度调节使用者的重力。\n放松你的精神聆听祷言，这会使小小骑士的躯体更轻松，更灵活。", "多洛莉丝"},
[300082] = {300082, "Restrain\u{0020}the\u{0020}Ego", "Equipment\u{0020}developed\u{0020}by\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}for\u{0020}Dolores.\u{0020}This\u{0020}armament\u{0020}has\u{0020}extreme\u{0020}protection\u{0020}ability\u{0020}and\u{0020}is\u{0020}not\u{0020}affected\u{0020}by\u{0020}temperature,\u{0020}but\u{0020}the\u{0020}weight\u{0020}is\u{0020}utterly\u{0020}high,\u{0020}three\u{0020}times\u{0020}that\u{0020}of\u{0020}other\u{0020}similar\u{0020}equipment.\nBe\u{0020}down-to-earth.\u{0020}Even\u{0020}if\u{0020}you\u{0020}walk\u{0020}slowly,\u{0020}every\u{0020}step\u{0020}of\u{0020}the\u{0020}little\u{0020}knight\u{0020}is\u{0020}solid.", "icon_duoluolisi_zs3", "0", 2, 3, "3_{lv}*100", "Dolores", "1_110021_5", 10, "3_100", "300080,300081,300082", "0", "0", "0", "0", "0", "约束本我", "由多瑙支部为多洛莉丝研发的装备，该武装拥有极高防护能力且不受温度的影响，但重量出奇的高，是其他同款装备的三倍。\n脚踏实地，即使走得很慢，但小小骑士的每一步都无边扎实。", "多洛莉丝"},
[300090] = {300090, "Scythe\u{0020}of\u{0020}Adjudication", "This\u{0020}equipment\u{0020}is\u{0020}the\u{0020}first-generation\u{0020}attack\u{0020}equipment\u{0020}developed\u{0020}by\u{0020}a\u{0020}scientist\u{0020}who\u{0020}is\u{0020}addicted\u{0020}to\u{0020}the\u{0020}fantasy\u{0020}of\u{0020}magical\u{0020}girls.\u{0020}The\u{0020}equipment\u{0020}uses\u{0020}the\u{0020}mysterious\u{0020}\"S\"\u{0020}metal.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}this\u{0020}metal\u{0020}does\u{0020}not\u{0020}exist\u{0020}in\u{0020}this\u{0020}universe.\u{0020}Therefore,\u{0020}all\u{0020}existing\u{0020}attacks\u{0020}in\u{0020}this\u{0020}world\u{0020}cannot\u{0020}harm\u{0020}this\u{0020}equipment\u{0020}(according\u{0020}to\u{0020}this\u{0020}scientist,\u{0020}the\u{0020}authenticity\u{0020}remains\u{0020}to\u{0020}be\u{0020}verified).\nIn\u{0020}addition,\u{0020}this\u{0020}equipment\u{0020}has\u{0020}the\u{0020}ability\u{0020}to\u{0020}burn\u{0020}air.\u{0020}When\u{0020}wielded,\u{0020}it\u{0020}will\u{0020}bring\u{0020}up\u{0020}a\u{0020}blue\u{0020}light\u{0020}flame\u{0020}of\u{0020}over\u{0020}5,000\u{0020}degree\u{0020}Celsius.", "icon_mogenlefei_zs1", "0", 4, 1, "1_{lv}*100", "Morgan\u{0020}Le\u{0020}Fay", "1_110021_20", 10, "1_100", "300090,300091,300092", "0", "0", "0", "0", "0", "0", "0", "0"},
[300091] = {300091, "Four-Dimensional\u{0020}Thread", "This\u{0020}equipment\u{0020}is\u{0020}the\u{0020}first-generation\u{0020}auxiliary\u{0020}equipment\u{0020}developed\u{0020}by\u{0020}a\u{0020}scientist\u{0020}who\u{0020}is\u{0020}addicted\u{0020}to\u{0020}the\u{0020}fantasy\u{0020}of\u{0020}magical\u{0020}girls.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}this\u{0020}equipment\u{0020}is\u{0020}able\u{0020}to\u{0020}tear\u{0020}the\u{0020}spatial\u{0020}dimension\u{0020}and\u{0020}form\u{0020}a\u{0020}connection\u{0020}with\u{0020}the\u{0020}fourth\u{0020}dimension\u{0020}(according\u{0020}to\u{0020}this\u{0020}scientist,\u{0020}the\u{0020}authenticity\u{0020}remains\u{0020}to\u{0020}be\u{0020}verified).\nThe\u{0020}requirement\u{0020}for\u{0020}users\u{0020}is\u{0020}to\u{0020}have\u{0020}childlike\u{0020}imagination\u{0020}to\u{0020}exert\u{0020}its\u{0020}true\u{0020}power.", "icon_mogenlefei_zs2", "0", 4, 2, "3_{lv}*100", "Morgan\u{0020}Le\u{0020}Fay", "1_110021_20", 10, "3_100", "300090,300091,300092", "0", "0", "0", "0", "0", "0", "0", "0"},
[300092] = {300092, "Wing\u{0020}of\u{0020}Expulsion", "This\u{0020}equipment\u{0020}is\u{0020}the\u{0020}first-generation\u{0020}auxiliary\u{0020}equipment\u{0020}developed\u{0020}by\u{0020}a\u{0020}scientist\u{0020}who\u{0020}is\u{0020}addicted\u{0020}to\u{0020}the\u{0020}fantasy\u{0020}of\u{0020}magical\u{0020}girls.\u{0020}The\u{0020}equipment\u{0020}is\u{0020}made\u{0020}of\u{0020}a\u{0020}sufficient\u{0020}amount\u{0020}of\u{0020}titanium\u{0020}alloy.\nAnd\u{0020}a\u{0020}new\u{0020}Light's\u{0020}Legacy\u{0020}system\u{0020}(named\u{0020}by\u{0020}this\u{0020}scientist)\u{0020}is\u{0020}featured.\u{0020}By\u{0020}consuming\u{0020}the\u{0020}energy\u{0020}of\u{0020}the\u{0020}transformation\u{0020}core,\u{0020}virtual\u{0020}light\u{0020}wings\u{0020}are\u{0020}created.\u{0020}Except\u{0020}for\u{0020}the\u{0020}slightly\u{0020}higher\u{0020}energy\u{0020}consumption,\u{0020}it\u{0020}is\u{0020}very\u{0020}excellent\u{0020}in\u{0020}terms\u{0020}of\u{0020}speed\u{0020}and\u{0020}stability.\nWhat\u{0020}exactly\u{0020}is\u{0020}this\u{0020}system\u{0020}remains\u{0020}unknown.", "icon_mogenlefei_zs3", "0", 4, 3, "1_{lv}*100", "Morgan\u{0020}Le\u{0020}Fay", "1_110021_20", 10, "1_100", "300090,300091,300092", "0", "0", "0", "0", "0", "0", "0", "0"},
[300100] = {300100, "Knight's\u{0020}Blade", "Equipment\u{0020}developed\u{0020}by\u{0020}the\u{0020}Danube\u{0020}branch.\u{0020}This\u{0020}armament\u{0020}is\u{0020}made\u{0020}of\u{0020}light\u{0020}metal.\u{0020}While\u{0020}ensuring\u{0020}a\u{0020}certain\u{0020}lethality,\u{0020}its\u{0020}weight\u{0020}has\u{0020}been\u{0020}effectively\u{0020}reduced,\u{0020}which\u{0020}can\u{0020}meet\u{0020}the\u{0020}needs\u{0020}of\u{0020}high-speed\u{0020}combat.\nA\u{0020}once-broken\u{0020}sharp\u{0020}sword\u{0020}now\u{0020}returns\u{0020}to\u{0020}its\u{0020}battlefield.", "icon_alaita_zs1", "0", 3, 1, "3_{lv}*100", "Alaita", "1_110021_10", 10, "3_100", "300100,300101,300102", "0", "0", "0", "0", "0", "骑士利刃", "由多瑙支部研发的装备，该武装由轻金属制成，在确保一定杀伤力的同时重量上进行了有效的削减，能够满足高速战斗的需求。\n一度折断过的利剑，如今重返属于它的战场。", "阿莱塔"},
[300101] = {300101, "Forge\u{0020}Ahead", "Equipment\u{0020}developed\u{0020}by\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}for\u{0020}Alaita.\u{0020}Made\u{0020}of\u{0020}high-strength\u{0020}alloy,\u{0020}this\u{0020}armament\u{0020}has\u{0020}high\u{0020}protection\u{0020}ability\u{0020}and\u{0020}is\u{0020}not\u{0020}affected\u{0020}by\u{0020}temperature,\u{0020}but\u{0020}its\u{0020}weight\u{0020}is\u{0020}surprisingly\u{0020}high,\u{0020}three\u{0020}times\u{0020}that\u{0020}of\u{0020}other\u{0020}similar\u{0020}equipment.\nThe\u{0020}price\u{0020}of\u{0020}taking\u{0020}the\u{0020}wrong\u{0020}path\u{0020}is\u{0020}three\u{0020}times\u{0020}that\u{0020}of\u{0020}others.\u{0020}Think\u{0020}before\u{0020}you\u{0020}move\u{0020}forward.", "icon_alaita_zs2", "0", 3, 2, "1_{lv}*100", "Alaita", "1_110021_10", 10, "1_100", "300100,300101,300102", "0", "0", "0", "0", "0", "砥砺前行", "由多瑙支部为阿莱塔研发的装备，采用高强度合金制造，该武装拥有极高防护能力且不受温度的影响，但重量出奇的高，是其他同款装备的三倍。\n走错路的代价是其他人的三倍，在你前行之前，先思考。", "阿莱塔"},
[300102] = {300102, "Faith\u{0020}Perception", "Equipment\u{0020}developed\u{0020}by\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}for\u{0020}Alaita.\u{0020}In\u{0020}addition\u{0020}to\u{0020}being\u{0020}equipped\u{0020}with\u{0020}a\u{0020}basic\u{0020}defense\u{0020}system\u{0020}and\u{0020}communication\u{0020}system,\u{0020}it\u{0020}can\u{0020}also\u{0020}be\u{0020}directly\u{0020}connected\u{0020}to\u{0020}the\u{0020}system\u{0020}of\u{0020}the\u{0020}third\u{0020}laboratory\u{0020}and\u{0020}receive\u{0020}the\u{0020}analysis\u{0020}data\u{0020}of\u{0020}the\u{0020}system\u{0020}in\u{0020}real\u{0020}time\u{0020}during\u{0020}battle.\nRemember\u{0020}to\u{0020}stay\u{0020}in\u{0020}touch\u{0020}with\u{0020}your\u{0020}teammates.", "icon_alaita_zs3", "0", 3, 3, "3_{lv}*100", "Alaita", "1_110021_10", 10, "3_100", "300100,300101,300102", "0", "0", "0", "0", "0", "信念感知", "由多瑙支部为阿莱塔研发的装备，除了配备了基本的防卫系统和通信系统，还可以与第三研究室的系统直连，在战斗中实时接收系统的分析数据。\n记得与你的队友常联系。", "阿莱塔"},
[300110] = {300110, "Hidden\u{0020}Scythe", "A\u{0020}pair\u{0020}of\u{0020}scythes\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters,\u{0020}specially\u{0020}designed\u{0020}for\u{0020}troops\u{0020}performing\u{0020}covert\u{0020}operations.\u{0020}The\u{0020}design\u{0020}purpose\u{0020}is\u{0020}to\u{0020}ensure\u{0020}lethality\u{0020}and\u{0020}range\u{0020}on\u{0020}the\u{0020}basis\u{0020}of\u{0020}supporting\u{0020}covert\u{0020}operations.\u{0020}The\u{0020}bottom\u{0020}ends\u{0020}of\u{0020}the\u{0020}two\u{0020}scythes\u{0020}are\u{0020}connected\u{0020}by\u{0020}chains\u{0020}for\u{0020}the\u{0020}driver\u{0020}to\u{0020}recover.\nOnly\u{0020}Jacksui\u{0020}can\u{0020}distinguish\u{0020}the\u{0020}hidden\u{0020}scythe\u{0020}in\u{0020}the\u{0020}recovery\u{0020}startup.\u{0020}Other\u{0020}users\u{0020}are\u{0020}injured\u{0020}to\u{0020}varying\u{0020}degrees.\u{0020}This\u{0020}child\u{0020}may\u{0020}be\u{0020}a\u{0020}born\u{0020}assassin...", "icon_ruoshui_zs1", "0", 3, 1, "1_{lv}*100", "Jacksui", "1_110021_10", 10, "1_100", "300110,300111,300112", "0", "0", "0", "0", "0", "隐镰", "由艾吉斯总部设计并制造的双镰，专为执行隐秘行动的部队所设计。设计初衷便是在支持隐秘行动的基础上保证杀伤力和射程，采用链条将双镰底端连接以便驾驶员回收。\n只有弱水能辨别回收启动中的隐镰，其他使用者都被不同程度的划伤，这孩子或许是与生俱来的暗杀者……", "弱水"},
[300111] = {300111, "She\u{0020}Comes\u{0020}from\u{0020}the\u{0020}Darkness", "A\u{0020}stealth\u{0020}suit\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters,\u{0020}specially\u{0020}designed\u{0020}for\u{0020}troops\u{0020}performing\u{0020}covert\u{0020}operations.\u{0020}Made\u{0020}of\u{0020}a\u{0020}material\u{0020}that\u{0020}can\u{0020}generate\u{0020}a\u{0020}negative\u{0020}refractive\u{0020}index\u{0020}field.\u{0020}When\u{0020}activated,\u{0020}it\u{0020}can\u{0020}give\u{0020}the\u{0020}driver\u{0020}the\u{0020}effect\u{0020}of\u{0020}optical\u{0020}camouflage\u{0020}for\u{0020}covert\u{0020}operations.\nThe\u{0020}researcher\u{0020}who\u{0020}designed\u{0020}this\u{0020}dress\u{0020}was\u{0020}commended\u{0020}as\u{0020}the\u{0020}best\u{0020}employee\u{0020}of\u{0020}the\u{0020}year.\u{0020}He\u{0020}really\u{0020}gets\u{0020}it.", "icon_ruoshui_zs2", "0", 3, 2, "3_{lv}*100", "Jacksui", "1_110021_10", 10, "3_100", "300110,300111,300112", "0", "0", "0", "0", "0", "她从黑暗中来", "由艾吉斯总部设计并制造的潜行服，专为执行隐秘行动的部队所设计。采用能够生成负折射率力场的材质，启动时能让驾驶员获得到光学迷彩的效果以便执行隐蔽行动。\n设计这件衣服的研究员被表彰为年度最佳员工，他真的好懂。", "弱水"},
[300112] = {300112, "Clear\u{0020}Vision", "An\u{0020}eye\u{0020}mask\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters,\u{0020}specially\u{0020}designed\u{0020}for\u{0020}troops\u{0020}performing\u{0020}covert\u{0020}operations.\u{0020}While\u{0020}covering\u{0020}the\u{0020}driver's\u{0020}face,\u{0020}it\u{0020}can\u{0020}collect\u{0020}surrounding\u{0020}information\u{0020}and\u{0020}transmit\u{0020}the\u{0020}generated\u{0020}environmental\u{0020}data\u{0020}to\u{0020}the\u{0020}driver's\u{0020}brain.\nThe\u{0020}eyes\u{0020}are\u{0020}an\u{0020}important\u{0020}window\u{0020}for\u{0020}conveying\u{0020}human\u{0020}emotions.\u{0020}Once\u{0020}covered,\u{0020}it\u{0020}gets\u{0020}▉▉.", "icon_ruoshui_zs3", "0", 3, 3, "1_{lv}*100", "Jacksui", "1_110021_10", 10, "1_100", "300110,300111,300112", "0", "0", "0", "0", "0", "目明", "由艾吉斯总部设计并制造的目罩，专为执行隐秘行动的部队所设计。遮挡住驾驶员面容的同时，能够采集周边情报并将生成的环境数据传输至驾驶员大脑。\n眼睛是传递人类情绪的重要窗口，一旦遮住，就显得▉▉了起来。", "弱水"},
[300120] = {300120, "Knight's\u{0020}Glory", "Equipment\u{0020}developed\u{0020}by\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}for\u{0020}Gloria.\u{0020}This\u{0020}armament\u{0020}is\u{0020}made\u{0020}of\u{0020}heavy\u{0020}metal\u{0020}and\u{0020}can\u{0020}burst\u{0020}out\u{0020}huge\u{0020}destructive\u{0020}power\u{0020}in\u{0020}an\u{0020}instant.\u{0020}The\u{0020}ultra-high\u{0020}temperature\u{0020}blade\u{0020}can\u{0020}destroy\u{0020}any\u{0020}armor.\nGloria,\u{0020}who\u{0020}has\u{0020}broken\u{0020}free\u{0020}from\u{0020}her\u{0020}family,\u{0020}becomes\u{0020}terrifying\u{0020}the\u{0020}moment\u{0020}she\u{0020}gets\u{0020}the\u{0020}weapon...", "icon_geluoliya_zs1", "0", 3, 1, "1_{lv}*100", "Gloria", "1_110021_10", 10, "1_100", "300120,300121,300122", "0", "0", "0", "0", "0", "骑士荣耀", "由多瑙支部为格洛丽亚研发的装备，该武装由重金属制成，能够在瞬时爆发出巨大的破坏力，超高温的斧刃无论何种护甲都能破坏殆尽。\n挣脱了家庭的格洛丽亚，拿到武器的那一刻，恐怖了起来……", "格洛丽亚"},
[300121] = {300121, "Proverb\u{0020}is\u{0020}Hard\u{0020}to\u{0020}Distinguish", "Equipment\u{0020}developed\u{0020}by\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}for\u{0020}Gloria.\u{0020}This\u{0020}arm\u{0020}guard\u{0020}is\u{0020}made\u{0020}of\u{0020}heavy\u{0020}metal\u{0020}and\u{0020}is\u{0020}equipped\u{0020}with\u{0020}a\u{0020}giant\u{0020}axe.\u{0020}While\u{0020}providing\u{0020}good\u{0020}defense,\u{0020}the\u{0020}built-in\u{0020}power\u{0020}mechanism\u{0020}can\u{0020}reduce\u{0020}the\u{0020}burden\u{0020}on\u{0020}the\u{0020}driver\u{0020}when\u{0020}using\u{0020}heavy\u{0020}weapons.\nIf\u{0020}the\u{0020}proverb\u{0020}is\u{0020}hard\u{0020}to\u{0020}distinguish,\u{0020}then\u{0020}summarize\u{0020}it\u{0020}yourself.\u{0020}Using\u{0020}your\u{0020}fists...", "icon_geluoliya_zs2", "0", 3, 2, "3_{lv}*100", "Gloria", "1_110021_10", 10, "3_100", "300120,300121,300122", "0", "0", "0", "0", "0", "箴言难辨", "由多瑙支部为格洛丽亚研发的装备，该护臂由重金属制成，与巨斧同时配备。在提供不俗的防御力的同时，内藏的动力机构能够让减轻驾驶员使用重型武器的负担。\n如果箴言难以被辨别，那就自己总结吧，用拳头……", "格洛丽亚"},
[300122] = {300122, "Just\u{0020}Beacon", "Equipment\u{0020}developed\u{0020}by\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}for\u{0020}Gloria.\u{0020}Made\u{0020}of\u{0020}light\u{0020}metal,\u{0020}it\u{0020}is\u{0020}mainly\u{0020}equipped\u{0020}for\u{0020}drivers\u{0020}with\u{0020}heavy\u{0020}weapons\u{0020}to\u{0020}assist\u{0020}in\u{0020}balance.\u{0020}Due\u{0020}to\u{0020}its\u{0020}attack\u{0020}performance,\u{0020}it\u{0020}can\u{0020}also\u{0020}serve\u{0020}as\u{0020}a\u{0020}firepower\u{0020}point\u{0020}at\u{0020}close\u{0020}range\u{0020}to\u{0020}attack\u{0020}the\u{0020}enemy.\nKid,\u{0020}someone\u{0020}will\u{0020}lead\u{0020}you.\u{0020}She\u{0020}will\u{0020}let\u{0020}you\u{0020}walk\u{0020}unswervingly\u{0020}in\u{0020}this\u{0020}treacherous\u{0020}world.\u{0020}She\u{0020}is...", "icon_geluoliya_zs3", "0", 3, 3, "1_{lv}*100", "Gloria", "1_110021_10", 10, "1_100", "300120,300121,300122", "0", "0", "0", "0", "0", "公正道标", "由多瑙支部为格洛丽亚研发的装备，由轻金属制成，主要配备给持重武装的驾驶员，用于辅助平衡。由于其持有攻击性能，在近距离下也能作为一个火力点，对敌人进行打击。\n孩子，会有人带领你的，她会让你不偏不倚地行走在这诡谲莫测的人世之间，她是……", "格洛丽亚"},
[300130] = {300130, "Umbrella\u{0020}of\u{0020}Expelling\u{0020}Light", "This\u{0020}equipment\u{0020}is\u{0020}the\u{0020}second-generation\u{0020}attack\u{0020}equipment\u{0020}developed\u{0020}by\u{0020}a\u{0020}scientist\u{0020}who\u{0020}is\u{0020}addicted\u{0020}to\u{0020}the\u{0020}fantasy\u{0020}of\u{0020}magical\u{0020}girls.\u{0020}The\u{0020}equipment\u{0020}uses\u{0020}the\u{0020}mysterious\u{0020}\"S\"\u{0020}metal.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}this\u{0020}metal\u{0020}does\u{0020}not\u{0020}exist\u{0020}in\u{0020}this\u{0020}universe.\u{0020}Therefore,\u{0020}all\u{0020}existing\u{0020}attack\u{0020}methods\u{0020}in\u{0020}this\u{0020}world\u{0020}cannot\u{0020}destroy\u{0020}this\u{0020}equipment.\u{0020}(According\u{0020}to\u{0020}this\u{0020}scientist,\u{0020}the\u{0020}authenticity\u{0020}remains\u{0020}to\u{0020}be\u{0020}verified).\nWhen\u{0020}the\u{0020}umbrella\u{0020}is\u{0020}unfolded,\u{0020}light\u{0020}wings\u{0020}will\u{0020}be\u{0020}activated\u{0020}to\u{0020}increase\u{0020}the\u{0020}weapon's\u{0020}output\u{0020}and\u{0020}give\u{0020}the\u{0020}weapon\u{0020}strong\u{0020}propulsion.", "icon_lilisi_zs1", "0", 2, 1, "1_{lv}*100", "Lilith", "1_110021_5", 10, "1_100", "300130,300131,300132", "0", "0", "0", "0", "0", "驱光之伞", "该装备是一名沉迷魔法少女幻想的科学官研发出的第二代攻击型装备，装备采用神秘的“S”金属，据说该物质并不存于这个宇宙，因此现世的所有攻击方式都无法摧毁这件装备。（出自该科学官之口，真实性有待考证）\n在伞架展开状态下会启动光翼增加武器出力，赋予武器强大的推进力。", "莉莉丝"},
[300131] = {300131, "Wing\u{0020}of\u{0020}Unfolding\u{0020}Feathers", "This\u{0020}equipment\u{0020}is\u{0020}the\u{0020}second-generation\u{0020}auxiliary\u{0020}equipment\u{0020}developed\u{0020}by\u{0020}a\u{0020}scientist\u{0020}who\u{0020}is\u{0020}addicted\u{0020}to\u{0020}the\u{0020}fantasy\u{0020}of\u{0020}magical\u{0020}girls.\u{0020}The\u{0020}equipment\u{0020}is\u{0020}made\u{0020}of\u{0020}a\u{0020}sufficient\u{0020}amount\u{0020}of\u{0020}titanium\u{0020}alloy\u{0020}and\u{0020}adopts\u{0020}a\u{0020}wing-like\u{0020}design.\u{0020}While\u{0020}providing\u{0020}strong\u{0020}propulsion,\u{0020}it\u{0020}also\u{0020}serves\u{0020}as\u{0020}a\u{0020}shield\u{0020}and\u{0020}can\u{0020}protect\u{0020}the\u{0020}equipped\u{0020}person\u{0020}from\u{0020}any\u{0020}external\u{0020}attack.\nFly\u{0020}like\u{0020}a\u{0020}bird.", "icon_lilisi_zs2", "0", 2, 2, "3_{lv}*100", "Lilith", "1_110021_5", 10, "3_100", "300130,300131,300132", "0", "0", "0", "0", "0", "展羽之翼", "该装备是一名沉迷魔法少女幻想的科学官研发出的第二代辅助型装备，装备是用足量的钛合金制作而成，采用了羽翼状设计，在提供强大的推进力的同时也担任了盾牌的职责，能够从任何外部攻击中保护装备者。\n像鸟儿一样飞翔吧。", "莉莉丝"},
[300132] = {300132, "Holy\u{0020}Lotus", "This\u{0020}equipment\u{0020}is\u{0020}the\u{0020}second-generation\u{0020}auxiliary\u{0020}equipment\u{0020}developed\u{0020}by\u{0020}a\u{0020}scientist\u{0020}who\u{0020}is\u{0020}addicted\u{0020}to\u{0020}the\u{0020}fantasy\u{0020}of\u{0020}magical\u{0020}girls.\u{0020}While\u{0020}having\u{0020}enemy\u{0020}detection\u{0020}and\u{0020}communication\u{0020}functions,\u{0020}it\u{0020}can\u{0020}also\u{0020}suppress\u{0020}the\u{0020}mental\u{0020}induction\u{0020}ability\u{0020}of\u{0020}the\u{0020}equipped\u{0020}person\u{0020}to\u{0020}a\u{0020}certain\u{0020}extent\u{0020}to\u{0020}prevent\u{0020}the\u{0020}equipped\u{0020}person\u{0020}from\u{0020}collapsing\u{0020}mentally\u{0020}due\u{0020}to\u{0020}receiving\u{0020}too\u{0020}many\u{0020}negative\u{0020}emotions\u{0020}during\u{0020}battle\u{0020}because\u{0020}of\u{0020}too\u{0020}strong\u{0020}induction\u{0020}ability.\nThe\u{0020}inspiration\u{0020}of\u{0020}the\u{0020}creator\u{0020}comes\u{0020}from\u{0020}ancient\u{0020}poems\u{0020}of\u{0020}Kyushu.", "icon_lilisi_zs3", "0", 2, 3, "3_{lv}*100", "Lilith", "1_110021_5", 10, "3_100", "300130,300131,300132", "0", "0", "0", "0", "0", "圣洁之莲", "该装备是一名沉迷魔法少女幻想的科学官研发出的第二代辅助型装备，具备索敌通信机能的同时，能够对装备者的精神感应力起到一定的抑制作用，防止装备者因感应力太强在战斗时接收到过多的负面感情导致精神崩坏。\n制作者的灵感来源于九州古诗。", "莉莉丝"},
[300140] = {300140, "Woodcutter", "An\u{0020}axe-type\u{0020}weapon\u{0020}specially\u{0020}customized\u{0020}by\u{0020}Siren\u{0020}for\u{0020}Korowin.\u{0020}Equipped\u{0020}to\u{0020}Korowin\u{0020}in\u{0020}the\u{0020}name\u{0020}of\u{0020}the\u{0020}Katya\u{0020}branch\u{0020}and\u{0020}made\u{0020}of\u{0020}new\u{0020}alloy\u{0020}materials.\u{0020}This\u{0020}weapon\u{0020}can\u{0020}easily\u{0020}split\u{0020}the\u{0020}shell\u{0020}of\u{0020}sin,\u{0020}but\u{0020}there\u{0020}is\u{0020}nothing\u{0020}special\u{0020}in\u{0020}appearance.\n\"If\u{0020}this\u{0020}axe\u{0020}is\u{0020}thrown\u{0020}into\u{0020}the\u{0020}lake,\u{0020}can\u{0020}I\u{0020}exchange\u{0020}it\u{0020}for\u{0020}a\u{0020}gold\u{0020}one?\"", "icon_keluowen_zs1", "0", 3, 1, "1_{lv}*100", "Korowin", "1_110021_10", 10, "1_100", "300140,300141,300142", "0", "0", "0", "0", "0", "樵夫", "塞伦公司为科罗温特别定制的斧型武器，以卡佳支部的名义装配给科罗温，使用新型合金材料制作而成。该武器能够轻松劈开原罪的外壳，但是在外观上并没有什么特殊的地方。\n“如果把这个斧子扔进湖里，能换个金的吗？”", "科罗温"},
[300141] = {300141, "Hercules'\u{0020}Grip", "An\u{0020}arm\u{0020}guard\u{0020}specially\u{0020}customized\u{0020}by\u{0020}Siren\u{0020}for\u{0020}Korowin.\u{0020}Equipped\u{0020}to\u{0020}Korowin\u{0020}in\u{0020}the\u{0020}name\u{0020}of\u{0020}the\u{0020}Katya\u{0020}branch\u{0020}and\u{0020}made\u{0020}of\u{0020}new\u{0020}alloy\u{0020}materials.\u{0020}The\u{0020}interior\u{0020}of\u{0020}the\u{0020}arm\u{0020}guard\u{0020}greatly\u{0020}enhances\u{0020}the\u{0020}user's\u{0020}grip\u{0020}through\u{0020}a\u{0020}complex\u{0020}mechanical\u{0020}structure,\u{0020}making\u{0020}it\u{0020}difficult\u{0020}for\u{0020}the\u{0020}weapon\u{0020}in\u{0020}their\u{0020}hand\u{0020}to\u{0020}be\u{0020}knocked\u{0020}off.\u{0020}Can\u{0020}easily\u{0020}destroy\u{0020}vital\u{0020}parts\u{0020}when\u{0020}attacking\u{0020}the\u{0020}enemy.\u{0020}But\u{0020}the\u{0020}overall\u{0020}appearance\u{0020}is\u{0020}very\u{0020}ordinary.\nThere\u{0020}are\u{0020}some\u{0020}words\u{0020}on\u{0020}the\u{0020}lower\u{0020}right\u{0020}corner\u{0020}of\u{0020}the\u{0020}elbow\u{0020}\"Please\u{0020}do\u{0020}not\u{0020}shake\u{0020}hands\u{0020}with\u{0020}other\u{0020}drivers\u{0020}while\u{0020}wearing\u{0020}this\u{0020}arm\u{0020}guard.\"", "icon_keluowen_zs2", "0", 3, 2, "3_{lv}*100", "Korowin", "1_110021_10", 10, "3_100", "300140,300141,300142", "0", "0", "0", "0", "0", "海格力斯之握", "塞伦公司为科罗温特别定制的臂铠，以卡佳支部的名义装配给科罗温，使用新型合金材料制作而成。臂铠内部通过复杂的机械结构极大地提升了使用者的握力，让其手中的武器不易被打飞或者在攻击敌人时可以轻松破坏要害部位。但是整体的外观上非常普通。\n在肘部装甲的右下角有一行小字“请勿在装备此臂铠的情况下与其他驾驶员握手。”", "科罗温"},
[300142] = {300142, "Ordinary\u{0020}Goggles", "A\u{0020}pair\u{0020}of\u{0020}goggles\u{0020}specially\u{0020}customized\u{0020}by\u{0020}Siren\u{0020}for\u{0020}Korowin.\u{0020}Equipped\u{0020}to\u{0020}Korowin\u{0020}in\u{0020}the\u{0020}name\u{0020}of\u{0020}the\u{0020}Katya\u{0020}branch\u{0020}and\u{0020}made\u{0020}of\u{0020}new\u{0020}alloy\u{0020}materials.\u{0020}There\u{0020}are\u{0020}360\u{0020}lenses\u{0020}hidden\u{0020}on\u{0020}the\u{0020}goggles\u{0020}that\u{0020}can\u{0020}see\u{0020}everything\u{0020}around\u{0020}and\u{0020}display\u{0020}it\u{0020}on\u{0020}the\u{0020}lenses.\u{0020}When\u{0020}making\u{0020}long-distance\u{0020}attacks,\u{0020}it\u{0020}will\u{0020}perform\u{0020}auxiliary\u{0020}aiming\u{0020}and\u{0020}is\u{0020}a\u{0020}powerful\u{0020}weapon\u{0020}that\u{0020}combines\u{0020}offense\u{0020}and\u{0020}defense.\n\"So...\u{0020}so\u{0020}much\u{0020}data.\u{0020}My\u{0020}eyes\u{0020}are\u{0020}dazzled.\u{0020}Forget\u{0020}it.\u{0020}It's\u{0020}better\u{0020}to\u{0020}wear\u{0020}it\u{0020}on\u{0020}my\u{0020}head.\"", "icon_keluowen_zs3", "0", 3, 3, "1_{lv}*100", "Korowin", "1_110021_10", 10, "1_100", "300140,300141,300142", "0", "0", "0", "0", "0", "“普通”护目镜", "塞伦公司为科罗温特别定制的护目镜，以卡佳支部的名义装配给科罗温，使用新型合金材料制作而成。护目镜上暗藏全视角镜头可以洞悉周围的一切情况，并显示在镜片上。在进行远距离攻击时会进行辅助瞄准，是一件攻守兼备的利器。\n“好...好多的数据，眼睛都看花了，算了还是戴在头上好了。”", "科罗温"},
[300150] = {300150, "Caring", "The\u{0020}third-generation\u{0020}close\u{0020}combat\u{0020}equipment\u{0020}made\u{0020}by\u{0020}the\u{0020}strongest\u{0020}arms\u{0020}manufacturer\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region\u{0020}-\u{0020}\"Siren\".\u{0020}This\u{0020}armament\u{0020}uses\u{0020}a\u{0020}drill\u{0020}bit\u{0020}as\u{0020}the\u{0020}attack\u{0020}part.\u{0020}When\u{0020}it\u{0020}rotates,\u{0020}it\u{0020}has\u{0020}far\u{0020}better\u{0020}penetration\u{0020}performance\u{0020}than\u{0020}other\u{0020}types\u{0020}of\u{0020}weapons.\u{0020}Sophia\u{0020}named\u{0020}it\u{0020}\"Caring\",\u{0020}a\u{0020}caring\u{0020}that\u{0020}no\u{0020}one\u{0020}except\u{0020}sin\u{0020}can\u{0020}bear.", "icon_suofeiya_zs1", "0", 3, 1, "3_{lv}*100", "Zofia", "1_110021_10", 10, "3_100", "300150,300151,300152", "0", "0", "0", "0", "0", "“关爱”", "由卡佳地区最强的军火制造商—“塞伦”制作的第三代近战装备，该武装使用钻头作为攻击部，当其旋转起来时拥有远超其他类型武器的穿透性能。索菲亚将其取名为“关爱”，除了原罪谁都消受不起的关爱。", "索菲亚"},
[300151] = {300151, "Absolute\u{0020}Force\u{0020}Field", "The\u{0020}test-type\u{0020}defense\u{0020}equipment\u{0020}made\u{0020}by\u{0020}the\u{0020}strongest\u{0020}arms\u{0020}manufacturer\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region\u{0020}-\u{0020}\"Siren\".\u{0020}By\u{0020}changing\u{0020}the\u{0020}output\u{0020}form\u{0020}of\u{0020}Nimbus\u{0020}energy,\u{0020}a\u{0020}defensive\u{0020}force\u{0020}field\u{0020}that\u{0020}can\u{0020}resist\u{0020}attacks\u{0020}is\u{0020}created.\u{0020}This\u{0020}is\u{0020}currently\u{0020}in\u{0020}the\u{0020}testing\u{0020}stage\u{0020}and\u{0020}may\u{0020}have\u{0020}embarrassing\u{0020}situations\u{0020}such\u{0020}as\u{0020}accidentally\u{0020}defending\u{0020}internal\u{0020}attacks.\u{0020}But\u{0020}for\u{0020}Sophia,\u{0020}nothing\u{0020}can\u{0020}stop\u{0020}her\u{0020}from\u{0020}attacking\u{0020}the\u{0020}enemy\u{0020}in\u{0020}front\u{0020}of\u{0020}her.\u{0020}I\u{0020}am\u{0020}afraid\u{0020}that\u{0020}even\u{0020}the\u{0020}rumored\u{0020}defensive\u{0020}force\u{0020}field\u{0020}known\u{0020}as\u{0020}absolute\u{0020}defense\u{0020}cannot\u{0020}stop\u{0020}her.", "icon_suofeiya_zs2", "0", 3, 2, "1_{lv}*100", "Zofia", "1_110021_10", 10, "1_100", "300150,300151,300152", "0", "0", "0", "0", "0", "绝对力场", "由卡佳地区最强的军火制造商—“塞伦”制作的测试型防御装备，通过改变尼姆比斯能的输出形式来获得可以抵御攻击的防御力场。目前是处在测试阶段的装备，可能会出现例如将内部的攻击也防御住的尴尬情况。但是对于索菲亚来说什么都阻止不了她攻击眼前的敌人，恐怕连传闻中号称绝对防御的防御力场也阻挡不住。", "索菲亚"},
[300152] = {300152, "Shackles", "The\u{0020}prototype\u{0020}of\u{0020}the\u{0020}standard\u{0020}mobile\u{0020}equipment\u{0020}made\u{0020}by\u{0020}the\u{0020}strongest\u{0020}arms\u{0020}manufacturer\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region\u{0020}-\u{0020}\"Siren\".\u{0020}Different\u{0020}from\u{0020}the\u{0020}mass-produced\u{0020}model,\u{0020}this\u{0020}prototype\u{0020}sacrifices\u{0020}some\u{0020}mobility\u{0020}in\u{0020}exchange\u{0020}for\u{0020}higher\u{0020}stability\u{0020}and\u{0020}load-bearing\u{0020}capacity.\u{0020}The\u{0020}greatest\u{0020}significance\u{0020}of\u{0020}this\u{0020}equipment\u{0020}lies\u{0020}in\u{0020}restricting\u{0020}Sophia's\u{0020}activity\u{0020}range\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}and\u{0020}preventing\u{0020}her\u{0020}from\u{0020}being\u{0020}surrounded\u{0020}by\u{0020}the\u{0020}enemy\u{0020}due\u{0020}to\u{0020}being\u{0020}addicted\u{0020}to\u{0020}battle.\u{0020}Sophia\u{0020}herself\u{0020}is\u{0020}very\u{0020}dissatisfied\u{0020}with\u{0020}this.\u{0020}She\u{0020}thinks\u{0020}this\u{0020}is\u{0020}the\u{0020}shackle\u{0020}that\u{0020}the\u{0020}branch\u{0020}has\u{0020}put\u{0020}on\u{0020}her.", "icon_suofeiya_zs3", "0", 3, 3, "1_{lv}*100", "Zofia", "1_110021_10", 10, "1_100", "300150,300151,300152", "0", "0", "0", "0", "0", "脚镣", "由卡佳地区最强的军火制造商—“塞伦”制作的制式机动装备的原型机，与量产型不同的是该原型机牺牲了部分机动能力来换取更高的稳定性和承重能力。这件装备最大的意义在于限制了索菲亚在战场上的活动范围，不会因为沉迷于战斗而陷入敌人的包围。索菲亚本人对此是十分不满，她觉得这就是支部给她上的脚镣。", "索菲亚"},
[300160] = {300160, "Last\u{0020}Effort", "The\u{0020}standard\u{0020}light\u{0020}firepower\u{0020}weapon\u{0020}of\u{0020}the\u{0020}college\u{0020}affiliated\u{0020}to\u{0020}the\u{0020}Sahara\u{0020}branch.\u{0020}It\u{0020}is\u{0020}one\u{0020}of\u{0020}the\u{0020}standard\u{0020}equipment\u{0020}of\u{0020}the\u{0020}college\u{0020}security\u{0020}department.\u{0020}Due\u{0020}to\u{0020}its\u{0020}small\u{0020}size,\u{0020}it\u{0020}is\u{0020}very\u{0020}suitable\u{0020}for\u{0020}drivers\u{0020}to\u{0020}carry\u{0020}with\u{0020}them\u{0020}as\u{0020}a\u{0020}backup.\u{0020}Of\u{0020}course,\u{0020}don't\u{0020}underestimate\u{0020}the\u{0020}firepower\u{0020}of\u{0020}this\u{0020}gun.\u{0020}It\u{0020}is\u{0020}more\u{0020}than\u{0020}enough\u{0020}to\u{0020}deal\u{0020}with\u{0020}minor\u{0020}sins.\n\"This\u{0020}is\u{0020}my\u{0020}last\u{0020}resort.\u{0020}If\u{0020}this\u{0020}doesn't\u{0020}work...\u{0020}\"", "icon_anan_zs1", "0", 3, 1, "3_{lv}*100", "Anan", "1_110021_10", 10, "3_100", "300160,300161,300162", "0", "0", "0", "0", "0", "最后的努力", "萨哈拉支部所属学院的制式轻火力武器。是学院保卫科的标准装备之一，由于体积小巧非常适合驾驶员随身携带作为备用。当然千万不要小看该枪支的火力，对付一般的低等原罪绰绰有余。\n“这是我最后的努力了，如果这都不行的话......”", "安安"},
[300161] = {300161, "Their\u{0020}Guardian", "The\u{0020}standard\u{0020}shield\u{0020}of\u{0020}the\u{0020}college\u{0020}affiliated\u{0020}to\u{0020}the\u{0020}Sahara\u{0020}branch.\u{0020}It\u{0020}is\u{0020}one\u{0020}of\u{0020}the\u{0020}standard\u{0020}equipment\u{0020}of\u{0020}the\u{0020}college\u{0020}security\u{0020}department.\u{0020}It\u{0020}can\u{0020}provide\u{0020}strong\u{0020}frontal\u{0020}defense\u{0020}ability.\u{0020}However,\u{0020}due\u{0020}to\u{0020}the\u{0020}lack\u{0020}of\u{0020}funds\u{0020}to\u{0020}install\u{0020}a\u{0020}gravity-assisted\u{0020}device,\u{0020}the\u{0020}driver\u{0020}needs\u{0020}to\u{0020}undergo\u{0020}certain\u{0020}physical\u{0020}training\u{0020}before\u{0020}being\u{0020}able\u{0020}to\u{0020}use\u{0020}it\u{0020}flexibly.\n\"I\u{0020}am\u{0020}a\u{0020}driver,\u{0020}I\u{0020}am\u{0020}a\u{0020}warrior,\u{0020}I\u{0020}am\u{0020}their\u{0020}guardian.\"", "icon_anan_zs2", "0", 3, 2, "3_{lv}*100", "Anan", "1_110021_10", 10, "3_100", "300160,300161,300162", "0", "0", "0", "0", "0", "他们的守护者", "萨哈拉支部所属学院的制式盾牌。是学院保卫科的标准装备之一，可以提供强大的正面防护能力，但是由于没有经费加装重力辅助装置，其重量需要驾驶员进行一定的体能训练后方可灵活使用。\n“我是驾驶员，我是个战士，我是他们的守护者。”", "安安"},
[300162] = {300162, "A\u{0020}Slow\u{0020}Sparrow\u{0020}Should\u{0020}Make\u{0020}an\u{0020}Early\u{0020}Start", "The\u{0020}special\u{0020}mobile\u{0020}equipment\u{0020}supported\u{0020}by\u{0020}the\u{0020}Sahara\u{0020}branch.\u{0020}Driven\u{0020}by\u{0020}Nimbus\u{0020}energy,\u{0020}it\u{0020}replaces\u{0020}the\u{0020}driver's\u{0020}legs\u{0020}for\u{0020}mobility\u{0020}and\u{0020}can\u{0020}greatly\u{0020}help\u{0020}the\u{0020}driver\u{0020}save\u{0020}physical\u{0020}strength.\u{0020}Although\u{0020}it\u{0020}is\u{0020}very\u{0020}fast,\u{0020}it\u{0020}is\u{0020}disliked\u{0020}by\u{0020}most\u{0020}drivers\u{0020}because\u{0020}it\u{0020}will\u{0020}affect\u{0020}combat\u{0020}performance.\u{0020}However,\u{0020}it\u{0020}is\u{0020}very\u{0020}suitable\u{0020}for\u{0020}Anan,\u{0020}who\u{0020}is\u{0020}short\u{0020}in\u{0020}stature,\u{0020}to\u{0020}march\u{0020}on\u{0020}the\u{0020}battlefield.\n\"So\u{0020}fast.\u{0020}Faster\u{0020}than\u{0020}the\u{0020}captain\u{0020}and\u{0020}the\u{0020}others...\u{0020}Oops,\u{0020}accidentally\u{0020}ran\u{0020}too\u{0020}far.\"", "icon_anan_zs3", "0", 3, 3, "3_{lv}*100", "Anan", "1_110021_10", 10, "3_100", "300160,300161,300162", "0", "0", "0", "0", "0", "笨鸟先飞", "萨哈拉支部特别支援的机动设备，以尼姆比斯能作为驱动力代替驾驶员的双腿进行机动，可以很大程度上帮助驾驶员节省体力。虽然速度很快，但是由于会影响战斗时的发挥而被大部分驾驶员所嫌弃，却很适合体型矮小的安安在战场上行军。\n“好快，比队长她们跑得还快...糟糕，一不小心跑太远了。”", "安安"},
[300170] = {300170, "High-Frequency\u{0020}Oscillation\u{0020}Twin\u{0020}Blades", "Equipment\u{0020}derived\u{0020}from\u{0020}the\u{0020}top\u{0020}scientific\u{0020}research\u{0020}plan\u{0020}in\u{0020}the\u{0020}Maya\u{0020}region.\u{0020}A\u{0020}double-edged\u{0020}armament\u{0020}with\u{0020}powerful\u{0020}attack\u{0020}performance.\u{0020}Through\u{0020}the\u{0020}high-speed\u{0020}vibration\u{0020}of\u{0020}the\u{0020}blade\u{0020}body,\u{0020}it\u{0020}can\u{0020}quickly\u{0020}cut\u{0020}the\u{0020}flesh\u{0020}of\u{0020}sin.\u{0020}Even\u{0020}if\u{0020}the\u{0020}attacked\u{0020}target\u{0020}does\u{0020}not\u{0020}die,\u{0020}it\u{0020}will\u{0020}lose\u{0020}its\u{0020}combat\u{0020}ability.\n\"It's\u{0020}really\u{0020}good\u{0020}that\u{0020}the\u{0020}enemy\u{0020}is\u{0020}sin\u{0020}and\u{0020}not\u{0020}human.\"\u{0020}-\u{0020}A\u{0020}peace-loving\u{0020}weapon\u{0020}designer", "icon_luoshalinde_zs1", "0", 3, 1, "1_{lv}*100", "Rosalind", "1_110021_10", 10, "1_100", "300170,300171,300172", "0", "0", "0", "0", "0", "高波震荡双刃", "在玛雅地区顶尖科技研究计划中所衍生的装备，拥有强大攻击性能的双刃型武装。通过刀体的高速震动可以快速切割原罪肉体，被攻击的目标就算不死也会丧失战斗能力。\n“敌人是原罪而不是人类真是太好了。”——爱好和平的武器设计师", "罗莎琳德"},
[300171] = {300171, "Nano-Assisted\u{0020}Iron\u{0020}Arm", "Equipment\u{0020}derived\u{0020}from\u{0020}the\u{0020}top\u{0020}scientific\u{0020}research\u{0020}plan\u{0020}in\u{0020}the\u{0020}Maya\u{0020}region.\u{0020}A\u{0020}highly\u{0020}functional\u{0020}auxiliary\u{0020}equipment.\u{0020}The\u{0020}mechanical\u{0020}arms\u{0020}fixed\u{0020}on\u{0020}both\u{0020}sides\u{0020}of\u{0020}the\u{0020}body\u{0020}can\u{0020}be\u{0020}used\u{0020}as\u{0020}additional\u{0020}arms.\u{0020}While\u{0020}having\u{0020}both\u{0020}strength\u{0020}and\u{0020}flexibility,\u{0020}the\u{0020}iron\u{0020}arm\u{0020}can\u{0020}also\u{0020}activate\u{0020}the\u{0020}built-in\u{0020}module\u{0020}to\u{0020}increase\u{0020}the\u{0020}combat\u{0020}ability\u{0020}of\u{0020}the\u{0020}user.\u{0020}If\u{0020}necessary,\u{0020}it\u{0020}can\u{0020}directly\u{0020}attack\u{0020}and\u{0020}catch\u{0020}the\u{0020}enemy\u{0020}off\u{0020}guard.\n\"If\u{0020}I\u{0020}have\u{0020}four\u{0020}arms,\u{0020}I\u{0020}won't\u{0020}be\u{0020}afraid\u{0020}of\u{0020}close\u{0020}combat\u{0020}with\u{0020}people.\u{0020}But\u{0020}if\u{0020}I\u{0020}encounter\u{0020}flying\u{0020}enemies,\u{0020}it\u{0020}will\u{0020}be\u{0020}a\u{0020}headache.\"\u{0020}-\u{0020}An\u{0020}imaginative\u{0020}weapon\u{0020}designer", "icon_luoshalinde_zs2", "0", 3, 2, "3_{lv}*100", "Rosalind", "1_110021_10", 10, "3_100", "300170,300171,300172", "0", "0", "0", "0", "0", "纳米辅助铁臂", "在玛雅地区顶尖科技研究计划中所衍生的装备，极具功能性的辅助装备。固定在身体两侧的机械臂可以充当额外的手臂使用。兼具力量和灵活的同时，铁臂还可以启动内置的模块对使用者进行战斗增幅。必要时可以直接进行攻击，打敌人一个措手不及。\n“有四个手臂的话就不怕和人近身格斗了，不过遇到飞行的敌人可就苦恼了。”——充满想象力的武器设计师", "罗莎琳德"},
[300172] = {300172, "Subsonic\u{0020}Acceleration\u{0020}Engine", "Equipment\u{0020}derived\u{0020}from\u{0020}the\u{0020}top\u{0020}scientific\u{0020}research\u{0020}plan\u{0020}in\u{0020}the\u{0020}Maya\u{0020}region.\u{0020}A\u{0020}thruster\u{0020}that\u{0020}provides\u{0020}high\u{0020}mobility.\u{0020}It\u{0020}can\u{0020}accelerate\u{0020}to\u{0020}supersonic\u{0020}speed\u{0020}in\u{0020}seconds.\u{0020}The\u{0020}fastest\u{0020}speed\u{0020}is\u{0020}at\u{0020}18\u{0020}Mach,\u{0020}but\u{0020}it\u{0020}will\u{0020}cause\u{0020}a\u{0020}great\u{0020}burden\u{0020}on\u{0020}the\u{0020}driver's\u{0020}gigantified\u{0020}body.\n\"Will\u{0020}it\u{0020}be\u{0020}faster\u{0020}if\u{0020}it\u{0020}is\u{0020}painted\u{0020}red?\"\u{0020}-\u{0020}An\u{0020}impatient\u{0020}equipment\u{0020}designer", "icon_luoshalinde_zs3", "0", 3, 3, "1_{lv}*100", "Rosalind", "1_110021_10", 10, "1_100", "300170,300171,300172", "0", "0", "0", "0", "0", "亚音速加速引擎", "在玛雅地区顶尖科技研究计划中所衍生的装备，提供高机动性的推进器。可以在几秒内加速到超音速，最快速度可达到18马赫但是会对驾驶员巨大化的身体造成极大的负担。\n“涂成红色会不会更快一点？”——\u{0020}\u{0020}急性子的装备设计师\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{00