[300180] = {300180, "Victory-bestowed\u{0020}Shield", "A\u{0020}shield-type\u{0020}equipment\u{0020}specially\u{0020}made\u{0020}by\u{0020}the\u{0020}first\u{0020}research\u{0020}lab\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}Katya\u{0020}branch.\u{0020}Was\u{0020}intended\u{0020}to\u{0020}improve\u{0020}the\u{0020}defense\u{0020}ability\u{0020}of\u{0020}defensive\u{0020}drivers,\u{0020}but\u{0020}in\u{0020}Lyfa's\u{0020}hands,\u{0020}it\u{0020}has\u{0020}become\u{0020}a\u{0020}\"killing\"\u{0020}weapon.\nThe\u{0020}strongest\u{0020}defense\u{0020}is\u{0020}offense!", "icon_lifa_zs1", "0", 3, 1, "3_{lv}*100", "Lyfa", "1_110021_10", 10, "3_100", "300180,300181,300182", "0", "0", "0", "0", "0", "高波震荡双刃", "在玛雅地区顶尖科技研究计划中所衍生的装备，拥有强大攻击性能的双刃型武装。通过刀体的高速震动可以快速切割原罪肉体，被攻击的目标就算不死也会丧失战斗能力。\n“敌人是原罪而不是人类真是太好了。”——爱好和平的武器设计师", "罗莎琳德"},
[300181] = {300181, "Communication\u{0020}Cap\u{0020}-\u{0020}Maid\u{0020}Type", "A\u{0020}communication\u{0020}device\u{0020}specially\u{0020}configured\u{0020}for\u{0020}the\u{0020}Danube\u{0020}First\u{0020}Guards\u{0020}Squad\u{0020}by\u{0020}the\u{0020}research\u{0020}laboratory\u{0020}of\u{0020}the\u{0020}Danube\u{0020}branch.\u{0020}In\u{0020}order\u{0020}to\u{0020}satisfy\u{0020}Lyfa's\u{0020}\"maid\u{0020}dream\",\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}Valkyries\u{0020}used\u{0020}her\u{0020}authority\u{0020}to\u{0020}purchase\u{0020}it\u{0020}from\u{0020}the\u{0020}Danube\u{0020}branch.\nThis\u{0020}is\u{0020}called\u{0020}professionalism.", "icon_lifa_zs2", "0", 3, 2, "3_{lv}*100", "Lyfa", "1_110021_10", 10, "3_100", "300180,300181,300182", "0", "0", "0", "0", "0", "纳米辅助铁臂", "在玛雅地区顶尖科技研究计划中所衍生的装备，极具功能性的辅助装备。固定在身体两侧的机械臂可以充当额外的手臂使用。兼具力量和灵活的同时，铁臂还可以启动内置的模块对使用者进行战斗增幅。必要时可以直接进行攻击，打敌人一个措手不及。\n“有四个手臂的话就不怕和人近身格斗了，不过遇到飞行的敌人可就苦恼了。”——充满想象力的武器设计师", "罗莎琳德"},
[300182] = {300182, "Ring\u{0020}of\u{0020}Nibelungen", "An\u{0020}auxiliary\u{0020}equipment\u{0020}specially\u{0020}made\u{0020}by\u{0020}the\u{0020}first\u{0020}research\u{0020}lab\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}Katya\u{0020}branch.\u{0020}Participated\u{0020}in\u{0020}the\u{0020}development\u{0020}by\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}Valkyries.\u{0020}It\u{0020}can\u{0020}increase\u{0020}the\u{0020}driver's\u{0020}strength\u{0020}in\u{0020}battle,\u{0020}but\u{0020}its\u{0020}actual\u{0020}ability\u{0020}is\u{0020}far\u{0020}more\u{0020}than\u{0020}that.\nBe\u{0020}careful\u{0020}of\u{0020}the\u{0020}people\u{0020}in\u{0020}the\u{0020}fog.", "icon_lifa_zs3", "0", 3, 3, "1_{lv}*100", "Lyfa", "1_110021_10", 10, "1_100", "300180,300181,300182", "0", "0", "0", "0", "0", "亚音速加速引擎", "在玛雅地区顶尖科技研究计划中所衍生的装备，提供高机动性的推进器。可以在几秒内加速到超音速，最快速度可达到18马赫但是会对驾驶员巨大化的身体造成极大的负担。\n“涂成红色会不会更快一点？”——\u{0020}\u{0020}急性子的装备设计师\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\u{0020}\