[300210] = {300210, "Black\u{0020}Heart\u{0020}Reflecting\u{0020}White\u{0020}Shadow", "Combat\u{0020}equipment\u{0020}specially\u{0020}developed\u{0020}by\u{0020}the\u{0020}research\u{0020}laboratory\u{0020}of\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}for\u{0020}Cynthia.\u{0020}The\u{0020}scythe\u{0020}and\u{0020}shield\u{0020}that\u{0020}were\u{0020}independent\u{0020}now\u{0020}form\u{0020}an\u{0020}integrated\u{0020}combat\u{0020}mode\u{0020}of\u{0020}offense\u{0020}and\u{0020}defense\u{0020}under\u{0020}the\u{0020}cooperation\u{0020}of\u{0020}Cynthia\u{0020}and\u{0020}Cynemia.\u{0020}In\u{0020}the\u{0020}battlefield,\u{0020}it\u{0020}is\u{0020}like\u{0020}an\u{0020}invincible\u{0020}chariot,\u{0020}easily\u{0020}crushing\u{0020}the\u{0020}sin's\u{0020}front\u{0020}line.\u{0020}The\u{0020}only\u{0020}drawback\u{0020}is\u{0020}that\u{0020}the\u{0020}two\u{0020}actually\u{0020}only\u{0020}have\u{0020}a\u{0020}single\u{0020}person's\u{0020}energy\u{0020}storage,\u{0020}resulting\u{0020}in\u{0020}a\u{0020}greatly\u{0020}shortened\u{0020}combat\u{0020}time.\nThe\u{0020}black\u{0020}heart\u{0020}reflects\u{0020}a\u{0020}pure\u{0020}white\u{0020}shadow.\u{0020}It\u{0020}seems\u{0020}like\u{0020}two\u{0020}people,\u{0020}but\u{0020}in\u{0020}fact\u{0020}we\u{0020}are\u{0020}one.", "icon_xinxiya_zs1", "0", 4, 1, "1_{lv}*100", "Cynthia", "1_110021_20", 10, "1_100", "300210,300211,300212", "0", "0", "0", "0", "0", "0", "0", "0"},
