[300311] = {300311, "Grandma's\u{0020}Intention", "A\u{0020}set\u{0020}of\u{0020}protective\u{0020}gear\u{0020}developed\u{0020}by\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}of\u{0020}AEGIS.\u{0020}Its\u{0020}appearance\u{0020}mimics\u{0020}the\u{0020}clothes\u{0020}hand-sewn\u{0020}by\u{0020}Ophelia's\u{0020}grandma\u{0020}for\u{0020}her.\u{0020}The\u{0020}original\u{0020}is\u{0020}both\u{0020}warm\u{0020}and\u{0020}breathable,\u{0020}while\u{0020}this\u{0020}protective\u{0020}gear\u{0020}is\u{0020}both\u{0020}defensive\u{0020}and\u{0020}lightweight.\n\"Since\u{0020}I\u{0020}can't\u{0020}fit\u{0020}into\u{0020}the\u{0020}clothes\u{0020}every\u{0020}year\u{0020}as\u{0020}I\u{0020}grow\u{0020}older,\u{0020}grandma\u{0020}helps\u{0020}tailor\u{0020}them\u{0020}every\u{0020}year,\u{0020}but\u{0020}she\u{0020}never\u{0020}says\u{0020}it's\u{0020}hard\u{0020}work...\"", "icon_aofeiliya_zs2", "0", 4, 2, "3_{lv}*100", "Ophelia", "1_110021_20", 10, "3_100", "300310,300311,300312", "0", "0", "0", "0", "0", "0", "0", "0"},
