[300331] = {300331, "Something\u{0020}to\u{0020}Remove", "A\u{0020}special\u{0020}neck\u{0020}guard\u{0020}for\u{0020}S52.\u{0020}It\u{0020}has\u{0020}a\u{0020}built-in\u{0020}positioning\u{0020}system\u{0020}that\u{0020}can\u{0020}monitor\u{0020}the\u{0020}driver's\u{0020}location\u{0020}in\u{0020}real\u{0020}time.\u{0020}Since\u{0020}S52\u{0020}often\u{0020}spreads\u{0020}words\u{0020}that\u{0020}are\u{0020}not\u{0020}conducive\u{0020}to\u{0020}organizational\u{0020}unity,\u{0020}regardless\u{0020}of\u{0020}occasion\u{0020}and\u{0020}place.\u{0020}She\u{0020}even\u{0020}incited\u{0020}other\u{0020}drivers\u{0020}to\u{0020}resist\u{0020}AEGIS\u{0020}during\u{0020}battle.\u{0020}In\u{0020}order\u{0020}to\u{0020}effectively\u{0020}stop\u{0020}this\u{0020}behavior\u{0020}and\u{0020}urge\u{0020}her\u{0020}to\u{0020}focus\u{0020}on\u{0020}combat,\u{0020}a\u{0020}restricting\u{0020}function\u{0020}and\u{0020}monitoring\u{0020}system\u{0020}that\u{0020}can\u{0020}be\u{0020}remotely\u{0020}controlled\u{0020}are\u{0020}added.\u{0020}The\u{0020}effect\u{0020}is\u{0020}remarkable.", "icon_kelang_zs2", "0", 4, 2, "3_{lv}*100", "Courant", "1_110021_20", 10, "3_100", "300330,300331,300332", "0", "0", "0", "0", "0", "0", "0", "0"},
