[300340] = {300340, "Daydream", "One\u{0020}of\u{0020}the\u{0020}restraints\u{0020}specially\u{0020}developed\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}headquarters\u{0020}for\u{0020}the\u{0020}prisoner\u{0020}Loki.\u{0020}In\u{0020}order\u{0020}to\u{0020}better\u{0020}use\u{0020}the\u{0020}prisoners,\u{0020}AEGIS\u{0020}generously\u{0020}meets\u{0020}their\u{0020}various\u{0020}requirements.\u{0020}As\u{0020}long\u{0020}as\u{0020}they\u{0020}are\u{0020}still\u{0020}useful\u{0020}tools,\u{0020}this\u{0020}privilege\u{0020}can\u{0020}continue.\nThe\u{0020}freedom\u{0020}lost\u{0020}keeps\u{0020}you\u{0020}alive.", "icon_luoji_zs1", "0", 4, 1, "1_{lv}*100", "Loki", "1_110021_20", 10, "1_100", "300340,300341,300342", "0", "0", "0", "0", "0", "0", "0", "0"},
