[300460] = {300460, "Sunset", "The\u{0020}weapon\u{0020}that\u{0020}appears\u{0020}when\u{0020}Fubuki\u{0020}Azuma\u{0020}uses\u{0020}her\u{0020}ability\u{0020}\"Sunset\".\u{0020}It\u{0020}can\u{0020}extend\u{0020}and\u{0020}retract\u{0020}freely\u{0020}according\u{0020}to\u{0020}her\u{0020}will.\nConcrete,\u{0020}steel,\u{0020}and\u{0020}even\u{0020}the\u{0020}bodies\u{0020}of\u{0020}Sin\u{0020}are\u{0020}easily\u{0020}pierced\u{0020}by\u{0020}it,\u{0020}a\u{0020}weapon\u{0020}that,\u{0020}true\u{0020}to\u{0020}its\u{0020}name,\u{0020}could\u{0020}pierce\u{0020}even\u{0020}the\u{0020}sun\u{0020}itself.", "icon_dongfengwuxi_zs1", "0", 4, 1, "1_{lv}*100", "Fubuki\u{0020}Azuma", "1_110021_20", 10, "1_100", "300460,300461,300462", "0", "0", "0", "0", "0", "0", "0", "0"},
