[300462] = {300462, "Fubuki\u{0020}Azuma's\u{0020}Custom\u{0020}Boots", "The\u{0020}long\u{0020}boots\u{0020}worn\u{0020}by\u{0020}Fubuki\u{0020}Azuma,\u{0020}Commander\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force's\u{0020}ninth\u{0020}Squad,\u{0020}during\u{0020}her\u{0020}daily\u{0020}activities.\nIn\u{0020}reality,\u{0020}they\u{0020}are\u{0020}just\u{0020}ordinary\u{0020}boots\u{0020}with\u{0020}nothing\u{0020}particularly\u{0020}special\u{0020}about\u{0020}them.", "icon_dongfengwuxi_zs3", "0", 4, 3, "3_{lv}*100", "Fubuki\u{0020}Azuma", "1_110021_20", 10, "3_100", "300460,300461,300462", "0", "0", "0", "0", "0", "0", "0", "0"},
[310000] = {310000, "Meteor\u{0020}Curtain", "A\u{0020}combined\u{0020}long\u{0020}spear\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}At\u{0020}the\u{0020}moment\u{0020}of\u{0020}stabbing\u{0020}out,\u{0020}it\u{0020}is\u{0020}as\u{0020}bright\u{0020}as\u{0020}a\u{0020}meteor\u{0020}penetrating\u{0020}the\u{0020}night\u{0020}sky.\nI\u{0020}am\u{0020}proud\u{0020}of\u{0020}this.\u{0020}I\u{0020}take\u{0020}this\u{0020}as\u{0020}glory.\u{0020}I\u{0020}use\u{0020}this\u{0020}to\u{0020}pierce\u{0020}this\u{0020}dark\u{0020}curtain.\u{0020}I\u{0020}will\u{0020}shine\u{0020}like\u{0020}a\u{0020}meteor.", "icon_chalisha_zs1", "0", 3, 1, "1_{lv}*100", "Charlissa", "1_110021_10", 10, "1_100", "310000,310001,310002", "0", "0", "0", "0", "0", "流星幕", "艾吉斯设计并制造的组合式长枪，在刺出的那一刻，如流星贯穿夜幕般璀璨。\n我以此为骄傲，我以此为荣耀，我以此划破这漆黑的幕布，我将如流星般闪耀。", "查丽莎"},
[310001] = {310001, "Indestructible\u{0020}Will", "An\u{0020}arm\u{0020}guard\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}Its\u{0020}defense\u{0020}power\u{0020}is\u{0020}sufficient\u{0020}to\u{0020}withstand\u{0020}a\u{0020}frontal\u{0020}bombardment\u{0020}of\u{0020}an\u{0020}axe-type\u{0020}missile.\nThere\u{0020}is\u{0020}a\u{0020}flame\u{0020}in\u{0020}my\u{0020}heart.\u{0020}That\u{0020}flame\u{0020}is\u{0020}flickering\u{0020}and\u{0020}seems\u{0020}about\u{0020}to\u{0020}go\u{0020}out.\u{0020}But\u{0020}there\u{0020}are\u{0020}people\u{0020}who\u{0020}reach\u{0020}out\u{0020}and\u{0020}block\u{0020}the\u{0020}incoming\u{0020}wind\u{0020}for\u{0020}me.", "icon_chalisha_zs2", "0", 3, 2, "1_{lv}*100", "Charlissa", "1_110021_10", 10, "1_100", "310000,310001,310002", "0", "0", "0", "0", "0", "不灭志", "艾吉斯设计并制造的护臂，其防御力足以抵挡战斧式导弹的正面轰击。\n我心中有一把火焰，那火焰飘飘晃晃，似要熄灭，但有群人伸出手替我挡住了袭来的风。", "查丽莎"},
[310002] = {310002, "Chasing\u{0020}the\u{0020}Sun", "A\u{0020}leg\u{0020}power\u{0020}source\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}Its\u{0020}speed\u{0020}is\u{0020}enough\u{0020}to\u{0020}chase\u{0020}the\u{0020}setting\u{0020}sun.\nSo\u{0020}I\u{0020}am\u{0020}no\u{0020}longer\u{0020}satisfied\u{0020}with\u{0020}being\u{0020}a\u{0020}meteor.\u{0020}I\u{0020}will\u{0020}become...\u{0020}the\u{0020}sun.", "icon_chalisha_zs3", "0", 3, 3, "1_{lv}*100", "Charlissa", "1_110021_10", 10, "1_100", "310000,310001,310002", "0", "0", "0", "0", "0", "逐日心", "由艾吉斯设计并制造的腿部动力源，其速度，足以追逐下落的太阳。\n于是我不再满足作为一颗流星，我将要成为……太阳。", "查丽莎"},
[310010] = {310010, "Brilliant\u{0020}Star", "AEGIS\u{0020}created\u{0020}a\u{0020}prototype\u{0020}weapon\u{0020}in\u{0020}an\u{0020}accidental\u{0020}experiment.\u{0020}By\u{0020}utilizing\u{0020}the\u{0020}enormous\u{0020}energy\u{0020}of\u{0020}small\u{0020}Nimbus\u{0020}aggregation\u{0020}energy,\u{0020}the\u{0020}user\u{0020}can\u{0020}launch\u{0020}several\u{0020}attacks\u{0020}in\u{0020}an\u{0020}instant.\nEven\u{0020}Miss\u{0020}Alice\u{0020}who\u{0020}can\u{0020}control\u{0020}such\u{0020}a\u{0020}weapon,\u{0020}which\u{0020}is\u{0020}truly\u{0020}perfect.", "icon_ailisi_zs1", "0", 4, 1, "1_{lv}*100", "Alice", "1_110021_20", 10, "1_100", "310010,310011,310012", "0", "0", "0", "0", "0", "煌星", "艾吉斯在一次偶然的实验中制造出的原型武器，利用小型尼姆比斯聚合能的庞大能量，使用者能够在一瞬间发动数次攻击。\n即使是这种兵器也能驾驭的爱丽丝大小姐，真是完美。", "爱丽丝"},
[310011] = {310011, "Pursuit\u{0020}of\u{0020}Perfection", "The\u{0020}arm\u{0020}guard\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}Cretia\u{0020}family.\u{0020}In\u{0020}order\u{0020}to\u{0020}meet\u{0020}Alice's\u{0020}perfection,\u{0020}the\u{0020}design\u{0020}alone\u{0020}took\u{0020}two\u{0020}months.\nThis\u{0020}level\u{0020}has\u{0020}not\u{0020}yet\u{0020}reached\u{0020}the\u{0020}\"perfection\"\u{0020}I\u{0020}pursue.\u{0020}I\u{0020}can\u{0020}still\u{0020}be\u{0020}more...", "icon_ailisi_zs2", "0", 4, 2, "1_{lv}*100", "Alice", "1_110021_20", 10, "1_100", "310010,310011,310012", "0", "0", "0", "0", "0", "完美追寻", "克雷蒂亚家设计并制造的护臂，为了能符合爱丽丝的完美，这件护臂光设计时间就长达两个月。\n这种程度，还没有达到我所追求的“完美”，我还可以更……", "爱丽丝"},
[310012] = {310012, "Still\u{0020}Unchanged", "The\u{0020}power\u{0020}device\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}Cretia\u{0020}family.\u{0020}Features\u{0020}a\u{0020}small\u{0020}Nimbus\u{0020}reactor\u{0020}and\u{0020}can\u{0020}provide\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}power\u{0020}to\u{0020}the\u{0020}user.\nWhat\u{0020}am\u{0020}I\u{0020}waiting\u{0020}for?\u{0020}What\u{0020}is\u{0020}my\u{0020}heart\u{0020}longing\u{0020}for?\u{0020}Who\u{0020}can\u{0020}tell\u{0020}me...", "icon_ailisi_zs3", "0", 4, 3, "1_{lv}*100", "Alice", "1_110021_20", 10, "1_100", "310010,310011,310012", "0", "0", "0", "0", "0", "仍未改变", "克雷蒂亚家设计并制造的动力装置，其内部整合了小型尼姆比斯反应堆，能够为使用者提供大量动力。\n我在等待什么，我的内心在渴望什么，有谁来告诉我……", "爱丽丝"},
[310020] = {310020, "Feather\u{0020}Slash", "The\u{0020}spiritual\u{0020}sword\u{0020}once\u{0020}enshrined\u{0020}in\u{0020}the\u{0020}Shingyou\u{0020}Shrine.\u{0020}After\u{0020}slaying\u{0020}sin\u{0020}and\u{0020}absorbing\u{0020}the\u{0020}core,\u{0020}it\u{0020}has\u{0020}gained\u{0020}powerful\u{0020}strength\u{0020}and\u{0020}can\u{0020}cut\u{0020}off\u{0020}everything\u{0020}it\u{0020}touches.\u{0020}The\u{0020}spiritual\u{0020}sword\u{0020}changes\u{0020}with\u{0020}the\u{0020}user.\nPerhaps\u{0020}this\u{0020}girl\u{0020}can\u{0020}really\u{0020}touch\u{0020}the\u{0020}abode\u{0020}of\u{0020}gods\u{0020}through\u{0020}this\u{0020}weapon.", "icon_xinzhi_zs1", "0", 4, 1, "1_{lv}*100", "Kokorokami", "1_110021_20", 10, "1_100", "310020,310021,310022", "0", "0", "0", "0", "0", "羽斩", "曾经供奉在心经神社的灵刀，在斩杀原罪并吸收了原罪核心后，拥有了强大的力量，能够瞬间切断所碰到的一切事物，灵刀会随着使用者的改变而改变。\n也许这位少女，真的能通过这柄武器触摸到神的居所。", "心纸"},
[310021] = {310021, "Blank\u{0020}Dissipation", "The\u{0020}leg\u{0020}armor\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS,\u{0020}especially\u{0020}with\u{0020}enhanced\u{0020}defense\u{0020}at\u{0020}the\u{0020}knee\u{0020}area.\n\"Getting\u{0020}shot\u{0020}at\u{0020}the\u{0020}knee\u{0020}is\u{0020}very\u{0020}terrifying.\"", "icon_xinzhi_zs2", "0", 4, 2, "1_{lv}*100", "Kokorokami", "1_110021_20", 10, "1_100", "310020,310021,310022", "0", "0", "0", "0", "0", "空白消融", "艾吉斯设计并制造的腿部装甲，尤其在膝盖部位加强了防御。\n“膝盖中箭了，是很可怕的。”", "心纸"},
[310022] = {310022, "Proof\u{0020}of\u{0020}Existence", "The\u{0020}power\u{0020}device\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}Features\u{0020}a\u{0020}small\u{0020}Nimbus\u{0020}reactor\u{0020}and\u{0020}can\u{0020}provide\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}power\u{0020}to\u{0020}the\u{0020}user.\nAll\u{0020}of\u{0020}my\u{0020}things\u{0020}have\u{0020}disappeared\u{0020}with\u{0020}the\u{0020}fulfillment\u{0020}of\u{0020}my\u{0020}oath.\u{0020}Can\u{0020}anyone\u{0020}notice\u{0020}my\u{0020}past...", "icon_xinzhi_zs3", "0", 4, 3, "1_{lv}*100", "Kokorokami", "1_110021_20", 10, "1_100", "310020,310021,310022", "0", "0", "0", "0", "0", "存在证明", "艾吉斯设计并制造的动力装置，其内部整合了小型尼姆比斯反应堆，能够为使用者提供大量动力。\n老身的一切都已经随着誓言的履行而消失，有人能注意到“我”的过去吗……", "心纸"},
[310030] = {310030, "Red\u{0020}Flame", "A\u{0020}demon\u{0020}sword.\u{0020}It\u{0020}is\u{0020}said\u{0020}to\u{0020}be\u{0020}made\u{0020}of\u{0020}mysterious\u{0020}ore.\u{0020}After\u{0020}the\u{0020}invasion\u{0020}of\u{0020}sin,\u{0020}it\u{0020}was\u{0020}soaked\u{0020}in\u{0020}high-concentration\u{0020}Nimbus\u{0020}and\u{0020}obtained\u{0020}special\u{0020}abilities.\u{0020}Its\u{0020}appearance\u{0020}changes\u{0020}with\u{0020}the\u{0020}user.\nEven\u{0020}the\u{0020}demon\u{0020}sword\u{0020}is\u{0020}suppressed\u{0020}by\u{0020}her\u{0020}will\u{0020}and\u{0020}submits\u{0020}to\u{0020}her.", "icon_lingmuqingfeng_zs1", "0", 4, 1, "3_{lv}*100", "Suzuki\u{0020}Seifung", "1_110021_20", 10, "3_100", "310030,310031,310032", "0", "0", "0", "0", "0", "红炎", "一把妖刀，传说是用神秘矿石打造而成，在原罪入侵后，浸泡在高浓度尼姆比斯中获得了特殊能力，外形会随着使用者的改变而改变。\n就连妖刀都被她的意志所镇压，对她俯首。", "铃木清风"},
[310031] = {310031, "Mother\u{0020}Ghost", "The\u{0020}mental\u{0020}power\u{0020}control\u{0020}device\u{0020}made\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}In\u{0020}battle,\u{0020}it\u{0020}will\u{0020}greatly\u{0020}increase\u{0020}the\u{0020}resonance\u{0020}data\u{0020}between\u{0020}the\u{0020}driver\u{0020}and\u{0020}the\u{0020}AVG,\u{0020}but\u{0020}it\u{0020}has\u{0020}extremely\u{0020}great\u{0020}side\u{0020}effects.\nIf\u{0020}you\u{0020}anger\u{0020}\"Ghost\u{0020}Mom\",\u{0020}I\u{0020}can\u{0020}only\u{0020}pray\u{0020}that\u{0020}you\u{0020}can\u{0020}die\u{0020}smoothly.", "icon_lingmuqingfeng_zs2", "0", 4, 2, "3_{lv}*100", "Suzuki\u{0020}Seifung", "1_110021_20", 10, "3_100", "310030,310031,310032", "0", "0", "0", "0", "0", "鬼妈妈", "由九州总部制作的精神力控制装置，在战斗中会大幅度的提高驾驶员与AVG的共鸣数据，但副作用极大。\n假如你惹怒了“鬼妈妈”，我只能祈祷你能顺利地死去。", "铃木清风"},
[310032] = {310032, "Rural\u{0020}Abode", "The\u{0020}special\u{0020}armor\u{0020}for\u{0020}the\u{0020}Fuurinkazan\u{0020}team\u{0020}made\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}This\u{0020}armor\u{0020}has\u{0020}extremely\u{0020}high\u{0020}protection\u{0020}but\u{0020}is\u{0020}super\u{0020}light\u{0020}in\u{0020}weight.\n\"Um,\u{0020}I\u{0020}hope\u{0020}we\u{0020}can\u{0020}have\u{0020}a\u{0020}good\u{0020}ending\u{0020}of\u{0020}this\u{0020}war...\u{0020}Just\u{0020}kidding.\"", "icon_lingmuqingfeng_zs3", "0", 4, 3, "3_{lv}*100", "Suzuki\u{0020}Seifung", "1_110021_20", 10, "3_100", "310030,310031,310032", "0", "0", "0", "0", "0", "田舍归所", "由九州总部制作的风林火山小队专用装甲，该装甲拥有极高的防护且但重量极轻。\n“唔，希望在这场战争的最后，咱能有一个好结局吧……开玩笑的。”", "铃木清风"},
[310040] = {310040, "Restraint", "This\u{0020}equipment\u{0020}seems\u{0020}ancient\u{0020}in\u{0020}style,\u{0020}but\u{0020}it\u{0020}is\u{0020}a\u{0020}new\u{0020}type\u{0020}of\u{0020}AVG\u{0020}railgun\u{0020}of\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}By\u{0020}converting\u{0020}the\u{0020}energy\u{0020}of\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}into\u{0020}electrical\u{0020}energy\u{0020}and\u{0020}accelerating\u{0020}it\u{0020}in\u{0020}the\u{0020}barrel\u{0020}and\u{0020}firing\u{0020}it\u{0020}out,\u{0020}it\u{0020}has\u{0020}a\u{0020}higher\u{0020}impact\u{0020}force\u{0020}than\u{0020}traditional\u{0020}railguns.\nEvery\u{0020}bullet\u{0020}has\u{0020}a\u{0020}price!!!", "icon_lishanqingluan_zs1", "0", 2, 1, "1_{lv}*100", "Kuriyama\u{0020}Seiran", "1_110021_5", 10, "1_100", "310040,310041,310042", "0", "0", "0", "0", "0", "束", "该装备造型上看似古老，却是九州总部新型的AVG电击步枪，通过将幻化核心的能量转化为电能，并在枪管中加速后击发出去，在冲击力上高于传统的电磁步枪。\n每一发子弹，都是钱啊！！！", "栗山青鸾"},
[310041] = {310041, "Evil\u{0020}Eye", "This\u{0020}equipment\u{0020}is\u{0020}an\u{0020}impromptu\u{0020}work\u{0020}of\u{0020}a\u{0020}certain\u{0020}researcher\u{0020}of\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}Although\u{0020}the\u{0020}visual\u{0020}style\u{0020}is\u{0020}strange,\u{0020}it\u{0020}contains\u{0020}the\u{0020}most\u{0020}cutting-edge\u{0020}technology.\u{0020}This\u{0020}equipment\u{0020}can\u{0020}capture\u{0020}sonic-level\u{0020}video,\u{0020}and\u{0020}the\u{0020}visual\u{0020}range\u{0020}is\u{0020}up\u{0020}to\u{0020}30km.\nBecause\u{0020}it\u{0020}is\u{0020}an\u{0020}impromptu\u{0020}work,\u{0020}the\u{0020}possibility\u{0020}of\u{0020}mass\u{0020}production\u{0020}is\u{0020}extremely\u{0020}slim.\u{0020}The\u{0020}reason\u{0020}for\u{0020}assigning\u{0020}it\u{0020}to\u{0020}Kuriyama\u{0020}Seiran\u{0020}is\u{0020}that\u{0020}the\u{0020}bullets\u{0020}of\u{0020}the\u{0020}weapon\u{0020}she\u{0020}uses\u{0020}are\u{0020}too\u{0020}expensive,\u{0020}so\u{0020}it\u{0020}is\u{0020}necessary\u{0020}to\u{0020}ensure\u{0020}the\u{0020}accuracy\u{0020}and\u{0020}effectiveness\u{0020}of\u{0020}every\u{0020}bullet.", "icon_lishanqingluan_zs2", "0", 2, 2, "3_{lv}*100", "Kuriyama\u{0020}Seiran", "1_110021_5", 10, "3_100", "310040,310041,310042", "0", "0", "0", "0", "0", "邪眼", "该装备是九州总部某研究员的即兴之作，造型虽然古怪，却蕴含了最顶尖科研技术，该装备可以捕捉到音速级别的影像动画，并且视野射程高达30km。\n因为是即兴之作，所以量产的可能性微乎其微。之所以把邪眼配布给栗山青鸾的原因是，她使用的武器子弹太昂贵了，务必要确保每一发子弹的准确率和作用性。", "栗山青鸾"},
[310042] = {310042, "Soul", "A\u{0020}drone\u{0020}with\u{0020}a\u{0020}very\u{0020}cute\u{0020}appearance\u{0020}and\u{0020}has\u{0020}good\u{0020}fire\u{0020}support\u{0020}capabilities.\u{0020}Due\u{0020}to\u{0020}the\u{0020}size,\u{0020}it\u{0020}cannot\u{0020}carry\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}Nimbus\u{0020}energy,\u{0020}resulting\u{0020}in\u{0020}it\u{0020}not\u{0020}being\u{0020}able\u{0020}to\u{0020}be\u{0020}active\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}for\u{0020}too\u{0020}long.\nPerhaps\u{0020}at\u{0020}a\u{0020}critical\u{0020}moment,\u{0020}it\u{0020}might\u{0020}be\u{0020}able\u{0020}to\u{0020}transform\u{0020}through\u{0020}\"soul\"...", "icon_lishanqingluan_zs3", "0", 2, 3, "3_{lv}*100", "Kuriyama\u{0020}Seiran", "1_110021_5", 10, "3_100", "310040,310041,310042", "0", "0", "0", "0", "0", "魄", "外观非常可爱的无人机，具备不俗的炮火支援能力，由于体型关系，无法装载大量的尼姆比斯能，导致无法在战场上活跃太久。\n也许关键时候，能通过“魄”变身也说不定……", "栗山青鸾"},
[310060] = {310060, "Dual-chamber\u{0020}Sniper", "This\u{0020}equipment\u{0020}is\u{0020}a\u{0020}portable\u{0020}sniper\u{0020}cannon\u{0020}specially\u{0020}developed\u{0020}by\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}to\u{0020}deal\u{0020}with\u{0020}densely\u{0020}armored\u{0020}sin.\u{0020}Due\u{0020}to\u{0020}its\u{0020}high\u{0020}cost\u{0020}and\u{0020}consumption,\u{0020}there\u{0020}is\u{0020}only\u{0020}one\u{0020}AVG\u{0020}equipped\u{0020}with\u{0020}this\u{0020}in\u{0020}the\u{0020}entire\u{0020}branch.\nIn\u{0020}the\u{0020}process\u{0020}of\u{0020}pursuing\u{0020}front-line\u{0020}news,\u{0020}there\u{0020}is\u{0020}always\u{0020}danger.\u{0020}At\u{0020}this\u{0020}time,\u{0020}the\u{0020}help\u{0020}of\u{0020}this\u{0020}weapon\u{0020}is\u{0020}needed.", "icon_yanniluosi_zs1", "0", 3, 1, "1_{lv}*100", "Jenny\u{0020}Rose", "1_110021_10", 10, "1_100", "310060,310061,310062", "0", "0", "0", "0", "0", "双膛狙击炮", "该装备由多瑙支部为应对密集型装甲原罪专门研制的便携式狙击炮，由于造价昂贵且战斗消耗极高，在整个支部配备该装备的AVG只有一部。\n在追寻一线新闻的过程中总伴随着危险，这时候就需要这把武器的帮助。", "燕妮罗斯"},
[310061] = {310061, "Positioning\u{0020}Device\u{0020}·\u{0020}Good\u{0020}Work", "The\u{0020}device\u{0020}is\u{0020}equipped\u{0020}with\u{0020}a\u{0020}newly\u{0020}developed\u{0020}auxiliary\u{0020}AI\u{0020}by\u{0020}the\u{0020}Danube\u{0020}Branch.\u{0020}It\u{0020}can\u{0020}capture\u{0020}information\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}and\u{0020}analyze\u{0020}it\u{0020}into\u{0020}usable\u{0020}information\u{0020}and\u{0020}transmit\u{0020}it\u{0020}to\u{0020}the\u{0020}user\u{0020}through\u{0020}headphones\u{0020}and\u{0020}a\u{0020}screen.\nIt\u{0020}has\u{0020}a\u{0020}camera\u{0020}function.\u{0020}Young\u{0020}photographers\u{0020}never\u{0020}miss\u{0020}any\u{0020}interesting\u{0020}news.", "icon_yanniluosi_zs2", "0", 3, 2, "3_{lv}*100", "Jenny\u{0020}Rose", "1_110021_10", 10, "3_100", "310060,310061,310062", "0", "0", "0", "0", "0", "定位装置·好活", "装置上装载有多瑙支部新研制的辅助AI，可以通过捕捉战场上的信息，并分析成可用情报通过耳机和可视化液晶屏传达给使用者。\n有摄像功能，年轻的摄影师从不错过任何一场有趣的新闻。", "燕妮罗斯"},
[310062] = {310062, "Loaded\u{0020}Bullet", "Made\u{0020}entirely\u{0020}of\u{0020}high-density\u{0020}alloy,\u{0020}it\u{0020}is\u{0020}of\u{0020}extremely\u{0020}high\u{0020}quality.\u{0020}There\u{0020}is\u{0020}booster\u{0020}gunpowder\u{0020}at\u{0020}the\u{0020}bottom.\u{0020}After\u{0020}being\u{0020}accelerated\u{0020}through\u{0020}the\u{0020}barrel,\u{0020}it\u{0020}can\u{0020}easily\u{0020}penetrate\u{0020}any\u{0020}armor\u{0020}within\u{0020}a\u{0020}range\u{0020}of\u{0020}100KM.\nExpensive\u{0020}ammunition.\u{0020}Although\u{0020}it\u{0020}does\u{0020}not\u{0020}use\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}as\u{0020}firepower,\u{0020}it\u{0020}is\u{0020}still\u{0020}very,\u{0020}very\u{0020}expensive!", "icon_yanniluosi_zs3", "0", 3, 3, "1_{lv}*100", "Jenny\u{0020}Rose", "1_110021_10", 10, "1_100", "310060,310061,310062", "0", "0", "0", "0", "0", "填装弹", "全身由高密度的合金打造而成，质量极高，底部装有助推火药，在通过炮管加速后，可以轻松击穿范围100KM的任何装甲。\n昂贵的弹药，虽然没有用幻化核心作为火力，但依旧很昂贵、很昂贵！", "燕妮罗斯"},
[310070] = {310070, "Snowfield\u{0020}Sniper\u{0020}Rifle\u{0020}Type\u{0020}I", "The\u{0020}first-generation\u{0020}laser\u{0020}sniper\u{0020}rifle\u{0020}independently\u{0020}developed\u{0020}by\u{0020}the\u{0020}military\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}This\u{0020}firearm\u{0020}is\u{0020}completely\u{0020}unaffected\u{0020}by\u{0020}temperature\u{0020}and\u{0020}can\u{0020}still\u{0020}be\u{0020}used\u{0020}normally\u{0020}in\u{0020}extremely\u{0020}cold\u{0020}regions.\u{0020}It\u{0020}is\u{0020}equipped\u{0020}with\u{0020}a\u{0020}high-magnification\u{0020}sniper\u{0020}scope\u{0020}and\u{0020}a\u{0020}thermal\u{0020}imager.\u{0020}Although\u{0020}this\u{0020}weapon\u{0020}has\u{0020}insufficient\u{0020}area\u{0020}damage,\u{0020}its\u{0020}penetration\u{0020}power\u{0020}is\u{0020}extremely\u{0020}strong.\nA\u{0020}professional\u{0020}intelligence\u{0020}officer\u{0020}can\u{0020}solve\u{0020}the\u{0020}target\u{0020}with\u{0020}one\u{0020}shot\u{0020}before\u{0020}the\u{0020}intel\u{0020}transmission.", "icon_lidiya_zs1", "0", 3, 1, "1_{lv}*100", "Lydia", "1_110021_10", 10, "1_100", "310070,310071,310072", "0", "0", "0", "0", "0", "雪地狙击枪Ⅰ\u{0020}型", "由卡佳地区军方自己研制的初代镭射狙击枪，该枪械完全不受温度的影响，在极寒地区仍能正常使用，并且装有高倍狙击镜和热成像仪，该武器虽然范围杀伤力不足，但是穿透力极强。\n专业的情报官，可以在把目标情报传回指挥室之前，一枪解决目标。", "莉迪娅"},
[310071] = {310071, "Feather\u{0020}Sound", "The\u{0020}first-generation\u{0020}communication\u{0020}equipment\u{0020}independently\u{0020}developed\u{0020}by\u{0020}the\u{0020}military\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}It\u{0020}is\u{0020}cheap\u{0020}to\u{0020}manufacture\u{0020}but\u{0020}has\u{0020}a\u{0020}powerful\u{0020}communication\u{0020}system\u{0020}embedded.\u{0020}In\u{0020}addition,\u{0020}this\u{0020}equipment\u{0020}is\u{0020}extremely\u{0020}cold-resistant\u{0020}and\u{0020}the\u{0020}signal\u{0020}will\u{0020}not\u{0020}be\u{0020}affected\u{0020}when\u{0020}used\u{0020}underground.\nFollowing\u{0020}this\u{0020}externally\u{0020}displayed\u{0020}device\u{0020}that\u{0020}unfolds\u{0020}like\u{0020}feathers,\u{0020}people\u{0020}in\u{0020}the\u{0020}snowfield\u{0020}think\u{0020}that\u{0020}it\u{0020}is\u{0020}something\u{0020}worn\u{0020}by\u{0020}the\u{0020}personification\u{0020}of\u{0020}the\u{0020}law\u{0020}of\u{0020}victory.", "icon_lidiya_zs2", "0", 3, 2, "1_{lv}*100", "Lydia", "1_110021_10", 10, "1_100", "310070,310071,310072", "0", "0", "0", "0", "0", "羽音", "由卡佳地区军方自己研制的初代通信装备，造价便宜，但内嵌超强的通信系统，另外该装备极度耐寒，在极地下使用信号也不会受到影响。\n跟随着这如羽毛般展开的外显装置，雪地的人认为，它是胜利法则的人格化所佩戴之物。", "莉迪娅"},
[310072] = {310072, "Survival\u{0020}Necessity", "A\u{0020}cold-proof\u{0020}coat\u{0020}uniformly\u{0020}produced\u{0020}by\u{0020}the\u{0020}military\u{0020}supply\u{0020}department\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}It\u{0020}is\u{0020}mainly\u{0020}developed\u{0020}for\u{0020}drivers\u{0020}who\u{0020}fight\u{0020}in\u{0020}polar\u{0020}regions\u{0020}all\u{0020}year\u{0020}round\u{0020}and\u{0020}is\u{0020}made\u{0020}of\u{0020}special\u{0020}thermal\u{0020}insulation\u{0020}materials.\nDrivers\u{0020}who\u{0020}have\u{0020}used\u{0020}it\u{0020}all\u{0020}say\u{0020}it's\u{0020}great.", "icon_lidiya_zs3", "0", 3, 3, "1_{lv}*100", "Lydia", "1_110021_10", 10, "1_100", "310070,310071,310072", "0", "0", "0", "0", "0", "生存必需", "由卡佳地区军需处统一制作的防寒外衣，主要针对常年在极地作战的驾驶员研制的，采用特别的保暖材料制作而成。\n使用过的驾驶员都说很棒。", "莉迪娅"},
[310080] = {310080, "Hell\u{0020}Shanks", "The\u{0020}first\u{0020}weapon\u{0020}developed\u{0020}by\u{0020}the\u{0020}R&D\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}the\u{0020}Hanging\u{0020}Emperor.\u{0020}Its\u{0020}appearance\u{0020}resembles\u{0020}a\u{0020}bass\u{0020}guitar\u{0020}and\u{0020}has\u{0020}the\u{0020}ability\u{0020}to\u{0020}control\u{0020}air\u{0020}pressure.\nWelcome\u{0020}to\u{0020}the\u{0020}concert\u{0020}of\u{0020}[Elda's\u{0020}Abyss\u{0020}of\u{0020}Death].", "icon_aixilika_zs1", "0", 4, 1, "3_{lv}*100", "Ashlica", "1_110021_20", 10, "3_100", "310080,310081,310082", "0", "0", "0", "0", "0", "地狱香克斯", "由艾吉斯九州总部研发部为绞皇大队开发的第一把武器，外观酷似一把贝斯，拥有控制空气压强的能力。\n欢迎来到【爱露达死亡深渊】的演唱会现场。", "艾希丽卡"},
[310081] = {310081, "Paradise\u{0020}Spiral\u{0020}Arm", "The\u{0020}exoskeleton\u{0020}developed\u{0020}by\u{0020}the\u{0020}R&D\u{0020}department\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}the\u{0020}Hanging\u{0020}Emperor\u{0020}can\u{0020}greatly\u{0020}reduce\u{0020}the\u{0020}effort\u{0020}spent\u{0020}by\u{0020}the\u{0020}user\u{0020}in\u{0020}playing.\nPerhaps\u{0020}Ashlica\u{0020}is\u{0020}a\u{0020}witch.\u{0020}She\u{0020}has\u{0020}the\u{0020}power\u{0020}to\u{0020}manipulate\u{0020}everyone's\u{0020}emotions.", "icon_aixilika_zs2", "0", 4, 2, "3_{lv}*100", "Ashlica", "1_110021_20", 10, "3_100", "310080,310081,310082", "0", "0", "0", "0", "0", "乐园旋臂", "由艾吉斯九州总部研发部为绞皇大队开发的外骨骼装备，可以极大的降低使用者在弹奏中所花费的力气。\n也许艾希丽卡是位魔女，她有操纵大家情绪的力量。", "艾希丽卡"},
[310082] = {310082, "Echoes\u{0020}of\u{0020}Pursuit", "The\u{0020}equipment\u{0020}developed\u{0020}by\u{0020}the\u{0020}R&D\u{0020}department\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}the\u{0020}Hanging\u{0020}Emperor\u{0020}has\u{0020}the\u{0020}ability\u{0020}to\u{0020}greatly\u{0020}enhance\u{0020}the\u{0020}user's\u{0020}lethality.\nThere\u{0020}is\u{0020}this\u{0020}roaring\u{0020}in\u{0020}my\u{0020}brain.\u{0020}The\u{0020}music\u{0020}is\u{0020}still\u{0020}constantly\u{0020}hitting\u{0020}my\u{0020}brain.\u{0020}What\u{0020}on\u{0020}earth\u{0020}is\u{0020}this...", "icon_aixilika_zs3", "0", 4, 3, "3_{lv}*100", "Ashlica", "1_110021_20", 10, "3_100", "310080,310081,310082", "0", "0", "0", "0", "0", "追访回响", "由艾吉斯九州总部研发部为绞皇大队开发的装备，拥有大幅度增强使用者杀伤力的能力。\n脑中在轰鸣，脱离了现场后，音乐依旧在不断地访问着我的大脑，这究竟是……", "艾希丽卡"},
[310090] = {310090, "Gray\u{0020}Angel", "This\u{0020}equipment\u{0020}is\u{0020}an\u{0020}AI\u{0020}weapon\u{0020}that\u{0020}AEGIS\u{0020}prohibits\u{0020}from\u{0020}being\u{0020}developed\u{0020}and\u{0020}used.\u{0020}When\u{0020}in\u{0020}use,\u{0020}it\u{0020}will\u{0020}cause\u{0020}a\u{0020}burden\u{0020}on\u{0020}the\u{0020}user's\u{0020}brain\u{0020}and\u{0020}has\u{0020}more\u{0020}than\u{0020}three\u{0020}times\u{0020}the\u{0020}penetration\u{0020}power\u{0020}of\u{0020}traditional\u{0020}equipment.\u{0020}Only\u{0020}a\u{0020}small\u{0020}number\u{0020}of\u{0020}such\u{0020}equipment\u{0020}are\u{0020}circulated\u{0020}on\u{0020}the\u{0020}black\u{0020}market\u{0020}in\u{0020}Katya.\nWhat\u{0020}bad\u{0020}intentions\u{0020}can\u{0020}a\u{0020}gray\u{0020}angel\u{0020}have?", "icon_bolinna_zs1", "0", 2, 1, "3_{lv}*100", "Bolina", "1_110021_5", 10, "3_100", "310090,310091,310092", "0", "0", "0", "0", "0", "灰色天使", "该装备为艾吉斯禁止开发和使用的一种AI兵器，在使用时会对使用者的大脑造成负担，拥有传统同型号装备三倍以上的穿透力。此类装备只有在卡佳少数的黑市流通。\n灰色的天使能有什么坏心思呢？", "波林娜"},
[310091] = {310091, "White\u{0020}Devil", "This\u{0020}equipment\u{0020}is\u{0020}an\u{0020}AI\u{0020}weapon\u{0020}that\u{0020}AEGIS\u{0020}prohibits\u{0020}from\u{0020}being\u{0020}developed\u{0020}and\u{0020}used.\u{0020}It\u{0020}has\u{0020}the\u{0020}effect\u{0020}of\u{0020}stabilizing\u{0020}the\u{0020}user's\u{0020}spirit\u{0020}and\u{0020}overclocking\u{0020}the\u{0020}mental\u{0020}operations,\u{0020}but\u{0020}it\u{0020}will\u{0020}cause\u{0020}a\u{0020}serious\u{0020}burden\u{0020}on\u{0020}the\u{0020}user's\u{0020}body,\u{0020}making\u{0020}users\u{0020}shy\u{0020}away.\u{0020}Currently,\u{0020}only\u{0020}a\u{0020}small\u{0020}number\u{0020}of\u{0020}such\u{0020}equipment\u{0020}are\u{0020}circulated\u{0020}on\u{0020}the\u{0020}black\u{0020}market\u{0020}in\u{0020}Katya.\nThe\u{0020}white\u{0020}devil\u{0020}knows\u{0020}nothing,\u{0020}nothing...", "icon_bolinna_zs2", "0", 2, 2, "1_{lv}*100", "Bolina", "1_110021_5", 10, "1_100", "310090,310091,310092", "0", "0", "0", "0", "0", "白色恶魔", "该装备为艾吉斯禁止开发和使用的一种AI兵器，拥有稳定使用者精神及提升脑力运算速度的作用，但是却会对使用者的身体造成严重负荷，而让使用者望而却步。目前该装备只有在卡佳少数的黑市流通。\n白色的恶魔什么都不知道、不知道……", "波林娜"},
[310092] = {310092, "The\u{0020}Happiest\u{0020}Child", "This\u{0020}equipment\u{0020}is\u{0020}an\u{0020}AI\u{0020}weapon\u{0020}that\u{0020}AEGIS\u{0020}prohibits\u{0020}from\u{0020}being\u{0020}developed\u{0020}and\u{0020}used.\u{0020}Although\u{0020}it\u{0020}provides\u{0020}a\u{0020}very\u{0020}powerful\u{0020}defense\u{0020}network,\u{0020}it\u{0020}can\u{0020}cause\u{0020}great\u{0020}mental\u{0020}damage\u{0020}to\u{0020}the\u{0020}user.\u{0020}Therefore,\u{0020}only\u{0020}a\u{0020}small\u{0020}number\u{0020}of\u{0020}such\u{0020}equipment\u{0020}are\u{0020}circulated\u{0020}on\u{0020}the\u{0020}black\u{0020}market\u{0020}in\u{0020}Katya.\nI\u{0020}must\u{0020}be\u{0020}the\u{0020}happiest\u{0020}child.", "icon_bolinna_zs3", "0", 2, 3, "1_{lv}*100", "Bolina", "1_110021_5", 10, "1_100", "310090,310091,310092", "0", "0", "0", "0", "0", "最幸福的孩子", "该装备为艾吉斯禁止开发和使用的一种AI兵器，虽然能提供非常强大的防御网，但据说对使用者的精神损伤极大，因此此类装备只有在卡佳少数的黑市流通。\n我一定、一定是最幸福的孩子了吧。", "波林娜"},
[310100] = {310100, "Golden\u{0020}Bunny", "A\u{0020}prototype\u{0020}close\u{0020}combat\u{0020}weapon\u{0020}designed\u{0020}by\u{0020}Rou\u{0020}herself\u{0020}and\u{0020}commissioned\u{0020}to\u{0020}the\u{0020}research\u{0020}institute\u{0020}of\u{0020}the\u{0020}Maya\u{0020}Branch\u{0020}for\u{0020}production.\u{0020}It\u{0020}has\u{0020}two\u{0020}forms\u{0020}and\u{0020}only\u{0020}Rou\u{0020}can\u{0020}control\u{0020}it.\nHer\u{0020}enemies\u{0020}must\u{0020}not\u{0020}expect\u{0020}and\u{0020}will\u{0020}not\u{0020}want\u{0020}to\u{0020}know\u{0020}what\u{0020}the\u{0020}name\u{0020}of\u{0020}this\u{0020}weapon\u{0020}is.", "icon_long_zs1", "0", 2, 1, "1_{lv}*100", "Rou", "1_110021_5", 10, "1_100", "310100,310101,310102", "0", "0", "0", "0", "0", "黄金小兔兔", "由珑亲自参与设计并委托给玛雅支部研究院制作的试作型近战兵器，拥有二种形态，只有珑才能驾驭它。\n她的敌人一定想不到，也不会想知道，这把武器叫什么名字", "珑"},
[310101] = {310101, "Bunny\u{0020}Knight\u{0020}Helmet", "Equipment\u{0020}designed\u{0020}by\u{0020}Rou\u{0020}herself\u{0020}and\u{0020}commissioned\u{0020}to\u{0020}the\u{0020}research\u{0020}institute\u{0020}of\u{0020}the\u{0020}Maya\u{0020}Branch\u{0020}for\u{0020}production.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}wearing\u{0020}this\u{0020}will\u{0020}bring\u{0020}courage\u{0020}to\u{0020}Rou.\nYou\u{0020}were\u{0020}killed\u{0020}by\u{0020}the\u{0020}bunny\u{0020}knight.", "icon_long_zs2", "0", 2, 2, "1_{lv}*100", "Rou", "1_110021_5", 10, "1_100", "310100,310101,310102", "0", "0", "0", "0", "0", "兔兔骑士盔", "由珑自己使用废弃的材料制作出的装备，据说带上这个，会给珑带来勇气。\n你被兔兔骑士打死了。", "珑"},
[310102] = {310102, "Bunny\u{0020}Mechanical\u{0020}Legs", "A\u{0020}prototype\u{0020}mechanical\u{0020}prosthetic\u{0020}limb\u{0020}designed\u{0020}by\u{0020}Rou\u{0020}herself\u{0020}and\u{0020}commissioned\u{0020}to\u{0020}the\u{0020}research\u{0020}institute\u{0020}of\u{0020}the\u{0020}Maya\u{0020}Branch\u{0020}for\u{0020}production.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}it\u{0020}can\u{0020}increase\u{0020}Rou's\u{0020}jumping\u{0020}ability\u{0020}by\u{0020}more\u{0020}than\u{0020}three\u{0020}times.\nThe\u{0020}bunny\u{0020}knight\u{0020}is\u{0020}about\u{0020}to\u{0020}take\u{0020}off.", "icon_long_zs3", "0", 2, 3, "1_{lv}*100", "Rou", "1_110021_5", 10, "1_100", "310100,310101,310102", "0", "0", "0", "0", "0", "兔兔机械腿", "由珑亲自参与设计并委托给玛雅支部研究院制作的试作型机械义肢，据说可以提升珑3倍以上的弹跳能力。\n兔兔骑士，即将起飞。", "珑"},
[310110] = {310110, "Thunder\u{0020}Cut", "A\u{0020}wakizashi\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters.\u{0020}It\u{0020}is\u{0020}made\u{0020}of\u{0020}high-strength\u{0020}metal\u{0020}and\u{0020}is\u{0020}specially\u{0020}designed\u{0020}for\u{0020}troops\u{0020}performing\u{0020}covert\u{0020}operations.\u{0020}The\u{0020}design\u{0020}was\u{0020}intent\u{0020}on\u{0020}ensuring\u{0020}area\u{0020}lethality\u{0020}on\u{0020}the\u{0020}basis\u{0020}of\u{0020}supporting\u{0020}covert\u{0020}operations.\u{0020}In\u{0020}addition\u{0020}to\u{0020}attacking\u{0020}with\u{0020}its\u{0020}own\u{0020}physical\u{0020}property,\u{0020}it\u{0020}can\u{0020}also\u{0020}conduct\u{0020}area\u{0020}attacks\u{0020}by\u{0020}discharging\u{0020}electricity.\nListen\u{0020}to\u{0020}the\u{0020}thunder\u{0020}and\u{0020}wait\u{0020}for\u{0020}the\u{0020}thunder\u{0020}to\u{0020}roar.", "icon_honglei_zs1", "0", 3, 1, "1_{lv}*100", "Gourai", "1_110021_10", 10, "1_100", "310110,310111,310112", "0", "0", "0", "0", "0", "雷切", "由艾吉斯总部设计并制造的胁差，采用高强度金属制作，专为执行隐秘行动的部队所设计。设计初衷便是在支持隐秘行动的基础上保证范围性杀伤力，除利用其本身物理性质进行攻击外也可以通过放电进行范围打击。\n听凭雷引，且等雷声大作。", "轰雷"},
[310111] = {310111, "Spiritual\u{0020}Remnant", "The\u{0020}arm\u{0020}guard\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters.\u{0020}Compared\u{0020}with\u{0020}its\u{0020}defensive\u{0020}performance,\u{0020}it\u{0020}focuses\u{0020}more\u{0020}on\u{0020}modification\u{0020}potential.\u{0020}In\u{0020}order\u{0020}to\u{0020}meet\u{0020}the\u{0020}needs\u{0020}of\u{0020}customization\u{0020}for\u{0020}drivers,\u{0020}interfaces\u{0020}are\u{0020}configured\u{0020}on\u{0020}the\u{0020}armor\u{0020}to\u{0020}configure\u{0020}external\u{0020}equipment.\nPerhaps\u{0020}I\u{0020}will\u{0020}be\u{0020}destroyed,\u{0020}but\u{0020}my\u{0020}will,\u{0020}my\u{0020}role,\u{0020}and\u{0020}my\u{0020}goal\u{0020}will\u{0020}linger\u{0020}on.", "icon_honglei_zs2", "0", 3, 2, "1_{lv}*100", "Gourai", "1_110021_10", 10, "1_100", "310110,310111,310112", "0", "0", "0", "0", "0", "精神残存", "由艾吉斯总部设计并制造的护臂，相较于防御性能，更着重于改造潜力，为满足驾驶员个性定制的需求在装甲上配置了接口用以配置外部装备。\n也许我会毁灭，但我的意志，我的作用，我的目标，将会苟延残喘。", "轰雷"},
[310112] = {310112, "Gloomy\u{0020}Light", "The\u{0020}metal\u{0020}mask\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters.\u{0020}It\u{0020}is\u{0020}specially\u{0020}designed\u{0020}for\u{0020}troops\u{0020}performing\u{0020}covert\u{0020}operations.\u{0020}While\u{0020}covering\u{0020}the\u{0020}face\u{0020}of\u{0020}the\u{0020}driver,\u{0020}it\u{0020}enables\u{0020}the\u{0020}driver\u{0020}to\u{0020}communicate\u{0020}without\u{0020}making\u{0020}a\u{0020}sound.\nNo\u{0020}one\u{0020}knows\u{0020}that\u{0020}I\u{0020}have\u{0020}been\u{0020}here.", "icon_honglei_zs3", "0", 3, 3, "1_{lv}*100", "Gourai", "1_110021_10", 10, "1_100", "310110,310111,310112", "0", "0", "0", "0", "0", "黯光", "由艾吉斯总部设计并制造的金属面罩，专为执行隐秘行动的部队所设计。遮挡住驾驶员面容的同时，使得驾驶员能够在不发出声响的前提下进行通信交流。\n谁都不知道，我曾来过。", "轰雷"},
[310120] = {310120, "Annihilation\u{0020}Trigger", "A\u{0020}colossal\u{0020}electromagnetic\u{0020}cannon\u{0020}mounted\u{0020}on\u{0020}Alpha,\u{0020}co-engineered\u{0020}by\u{0020}Maya\u{0020}and\u{0020}forged\u{0020}by\u{0020}Danube.\u{0020}Built\u{0020}from\u{0020}rare\u{0020}alloys\u{0020}and\u{0020}enhanced\u{0020}with\u{0020}a\u{0020}power-amplification\u{0020}module\u{0020}to\u{0020}maximize\u{0020}destructive\u{0020}output.\n\"As\u{0020}a\u{0020}being\u{0020}with\u{0020}a\u{0020}Secondary\u{0020}Persona…\u{0020}am\u{0020}I\u{0020}allowed\u{0020}to\u{0020}dream\u{0020}of\u{0020}electric\u{0020}sheep?\"", "icon_aerfa_zs1", "0", 4, 1, "1_{lv}*100", "Alpha", "1_110021_20", 10, "1_100", "310120,310121,310122", "0", "0", "0", "0", "0", "0", "0", "0"},
[310121] = {310121, "Core\u{0020}Bastion", "Alpha's\u{0020}reinforced\u{0020}leg\u{0020}armor,\u{0020}co-engineered\u{0020}by\u{0020}Maya\u{0020}and\u{0020}forged\u{0020}by\u{0020}Danube.\u{0020}Constructed\u{0020}from\u{0020}rare\u{0020}alloys\u{0020}and\u{0020}layered\u{0020}with\u{0020}impact-resistant\u{0020}plating,\u{0020}it\u{0020}delivers\u{0020}unparalleled\u{0020}durability\u{0020}and\u{0020}crushing\u{0020}force.\n\"I\u{0020}exist\u{0020}for\u{0020}the\u{0020}survival\u{0020}of\u{0020}humanity…\u{0020}and\u{0020}I\u{0020}must\u{0020}seek\u{0020}redemption.\"", "icon_aerfa_zs2", "0", 4, 2, "3_{lv}*100", "Alpha", "1_110021_20", 10, "3_100", "310120,310121,310122", "0", "0", "0", "0", "0", "0", "0", "0"},
[310122] = {310122, "Unforgivable\u{0020}Evil", "An\u{0020}integrated\u{0020}communications\u{0020}array\u{0020}installed\u{0020}on\u{0020}Alpha,\u{0020}co-engineered\u{0020}by\u{0020}Maya\u{0020}and\u{0020}forged\u{0020}by\u{0020}Danube.\u{0020}Forged\u{0020}from\u{0020}rare\u{0020}alloys,\u{0020}it\u{0020}links\u{0020}units\u{0020}together\u{0020}and\u{0020}scans\u{0020}the\u{0020}environment\u{0020}for\u{0020}critical\u{0020}data.\n\"Was\u{0020}it\u{0020}human\u{0020}tampering\u{0020}that\u{0020}led\u{0020}to\u{0020}my\u{0020}rampage?\u{0020}Or\u{0020}was\u{0020}the\u{0020}fault\u{0020}truly\u{0020}mine…?\u{0020}I\u{0020}cannot\u{0020}say.\"", "icon_aerfa_zs3", "0", 4, 3, "1_{lv}*100", "Alpha", "1_110021_20", 10, "1_100", "310120,310121,310122", "0", "0", "0", "0", "0", "0", "0", "0"},
[310140] = {310140, "Blade\u{0020}Chasing\u{0020}Darkness", "This\u{0020}is\u{0020}the\u{0020}third-generation\u{0020}equipment\u{0020}developed\u{0020}by\u{0020}a\u{0020}scientist\u{0020}who\u{0020}is\u{0020}addicted\u{0020}to\u{0020}magical\u{0020}girl\u{0020}fantasies.\u{0020}The\u{0020}equipment\u{0020}is\u{0020}made\u{0020}of\u{0020}mysterious\u{0020}\"S\"\u{0020}metal.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}this\u{0020}substance\u{0020}does\u{0020}not\u{0020}exist\u{0020}in\u{0020}this\u{0020}universe.\u{0020}Therefore,\u{0020}all\u{0020}existing\u{0020}attack\u{0020}methods\u{0020}in\u{0020}the\u{0020}world\u{0020}cannot\u{0020}destroy\u{0020}this\u{0020}equipment.\u{0020}(According\u{0020}to\u{0020}the\u{0020}words\u{0020}of\u{0020}this\u{0020}scientist,\u{0020}the\u{0020}authenticity\u{0020}remains\u{0020}to\u{0020}be\u{0020}verified.)\u{0020}The\u{0020}blade\u{0020}can\u{0020}absorb\u{0020}energy\u{0020}through\u{0020}natural\u{0020}light\u{0020}and\u{0020}release\u{0020}the\u{0020}energy\u{0020}upon\u{0020}hitting\u{0020}the\u{0020}target,\u{0020}producing\u{0020}huge\u{0020}destructive\u{0020}power.\nThe\u{0020}queen\u{0020}of\u{0020}the\u{0020}Shadow\u{0020}Kingdom\u{0020}who\u{0020}chases\u{0020}in\u{0020}the\u{0020}darkness,\u{0020}when\u{0020}can\u{0020}she\u{0020}come\u{0020}out\u{0020}of\u{0020}the\u{0020}darkness?\u{0020}Your\u{0020}people\u{0020}can\u{0020}already\u{0020}survive\u{0020}out\u{0020}of\u{0020}the\u{0020}darkness.\u{0020}They\u{0020}are\u{0020}waiting\u{0020}for\u{0020}you\u{0020}in\u{0020}the\u{0020}sunlight.", "icon_sikadi_zs1", "0", 2, 1, "1_{lv}*100", "Skadi", "1_110021_5", 10, "1_100", "310140,310141,310142", "0", "0", "0", "0", "0", "逐暗之刃", "该装备是一名沉迷魔法少女幻想的科学家研发出的第三代攻击型装备，装备采用神秘的“S”金属，据说该物质并不存于这个宇宙，因此现世的所有攻击方式都无法摧毁这件装备。（出自该科学官之口，真实性有待考证）刀身可以通过自然光吸收能量，并在命中目标后将能量瞬间放出，产生巨大的破坏力。\n追逐于黑暗中的影之国女王，何日能从暗中走出，你的子民已经能脱离黑暗生存，她们在阳光中等待着你。", "斯卡蒂"},
[310141] = {310141, "After\u{0020}Dawn", "This\u{0020}is\u{0020}the\u{0020}third-generation\u{0020}auxiliary\u{0020}equipment\u{0020}developed\u{0020}by\u{0020}a\u{0020}scientist\u{0020}who\u{0020}is\u{0020}addicted\u{0020}to\u{0020}magical\u{0020}girl\u{0020}fantasies.\u{0020}The\u{0020}equipment\u{0020}is\u{0020}made\u{0020}of\u{0020}a\u{0020}sufficient\u{0020}amount\u{0020}of\u{0020}titanium\u{0020}alloy\u{0020}and\u{0020}adopts\u{0020}a\u{0020}design\u{0020}derived\u{0020}from\u{0020}the\u{0020}light\u{0020}wing\u{0020}system\u{0020}to\u{0020}acquire\u{0020}incomparable\u{0020}explosive\u{0020}propulsion.\u{0020}The\u{0020}energy\u{0020}consumption\u{0020}of\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}is\u{0020}relatively\u{0020}high,\u{0020}but\u{0020}the\u{0020}mobility\u{0020}is\u{0020}top\u{0020}level.\nAfter\u{0020}dawn,\u{0020}it\u{0020}is\u{0020}the\u{0020}time\u{0020}when\u{0020}the\u{0020}power\u{0020}of\u{0020}the\u{0020}queen\u{0020}of\u{0020}the\u{0020}Shadow\u{0020}Kingdom\u{0020}is\u{0020}at\u{0020}its\u{0020}peak\u{0020}(probably).", "icon_sikadi_zs2", "0", 2, 2, "3_{lv}*100", "Skadi", "1_110021_5", 10, "3_100", "310140,310141,310142", "0", "0", "0", "0", "0", "拂晓之后", "该装备是一名沉迷魔法少女幻想的科学家研发出的第三代辅助型装备，装备是用足量的钛合金制作而成，采用了光之翼系统衍生出的设计以获得无可比拟的爆发推进力，虽然幻化核心的能量消耗较高，但机动性达到了顶尖的水平。\n拂晓之后，就是影之国的女王力量全胜的时间（大概）", "斯卡蒂"},
[310142] = {310142, "Queen's\u{0020}Shadow", "This\u{0020}is\u{0020}the\u{0020}third-generation\u{0020}auxiliary\u{0020}equipment\u{0020}developed\u{0020}by\u{0020}a\u{0020}scientist\u{0020}who\u{0020}is\u{0020}addicted\u{0020}to\u{0020}magical\u{0020}girl\u{0020}fantasies.\u{0020}Although\u{0020}it\u{0020}is\u{0020}not\u{0020}an\u{0020}alloy\u{0020}product,\u{0020}it\u{0020}can\u{0020}withstand\u{0020}a\u{0020}certain\u{0020}degree\u{0020}of\u{0020}attack.\u{0020}While\u{0020}having\u{0020}communication\u{0020}functions,\u{0020}it\u{0020}is\u{0020}equipped\u{0020}with\u{0020}the\u{0020}latest\u{0020}anti-interference\u{0020}device,\u{0020}enabling\u{0020}the\u{0020}wearer\u{0020}to\u{0020}be\u{0020}immune\u{0020}to\u{0020}electromagnetic\u{0020}interference.\nMy\u{0020}people,\u{0020}I\u{0020}will\u{0020}always\u{0020}embrace\u{0020}the\u{0020}darkness.\u{0020}I\u{0020}have\u{0020}become\u{0020}so\u{0020}powerful\u{0020}that\u{0020}I\u{0020}have\u{0020}become\u{0020}a\u{0020}world\u{0020}savior!", "icon_sikadi_zs3", "0", 2, 3, "1_{lv}*100", "Skadi", "1_110021_5", 10, "1_100", "310140,310141,310142", "0", "0", "0", "0", "0", "女王之影", "该装备是一名沉迷魔法少女幻想的科学家研发出的第三代辅助型装备，虽不是合金制品但能够抵御一定程度的攻击。具备通信机能的同时，搭载了最新锐的防干扰装置，使得装备者能免疫电波干扰。\n我的子民，我将永远在黑暗中坐拥，我已经强大到，成为了拯救世界的一份子了！", "斯卡蒂"},
[310150] = {310150, "Claw\u{0020}Gloves\u{0020}of\u{0020}Morality", "The\u{0020}exoskeleton\u{0020}designed\u{0020}and\u{0020}developed\u{0020}by\u{0020}the\u{0020}science\u{0020}and\u{0020}the\u{0020}R&D\u{0020}department\u{0020}of\u{0020}the\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}Assault\u{0020}type\u{0020}drivers.\u{0020}This\u{0020}armor\u{0020}provides\u{0020}full\u{0020}coverage\u{0020}protection\u{0020}for\u{0020}the\u{0020}hands.\u{0020}They\u{0020}transmit\u{0020}the\u{0020}energy\u{0020}obtained\u{0020}from\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}to\u{0020}the\u{0020}tips\u{0020}of\u{0020}the\u{0020}fingers,\u{0020}leaving\u{0020}claw\u{0020}marks\u{0020}while\u{0020}attacking\u{0020}the\u{0020}target.\nI\u{0020}am\u{0020}a\u{0020}genius!", "icon_ling_zs1", "0", 3, 1, "1_{lv}*100", "Suzu", "1_110021_10", 10, "1_100", "310150,310151,310152", "0", "0", "0", "0", "0", "清虚道德爪痕拳套", "由九州总部科学部与研发部为攻击型驾驶员设计、研发的外骨骼，该装甲能够提供手部的全覆盖保护。将从幻化核心得到的能量传递到五指的尖端，在攻击目标的同时留下爪痕印记。\n我可是天才！", "铃"},
[310151] = {310151, "Fox\u{0020}Energy\u{0020}on\u{0020}the\u{0020}Cloud", "The\u{0020}fox-shaped\u{0020}energy\u{0020}transmission\u{0020}device\u{0020}developed\u{0020}by\u{0020}the\u{0020}special\u{0020}research\u{0020}institute\u{0020}of\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}This\u{0020}device\u{0020}can\u{0020}amplify\u{0020}and\u{0020}transmit\u{0020}the\u{0020}energy\u{0020}of\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}to\u{0020}the\u{0020}mechs\u{0020}all\u{0020}over\u{0020}the\u{0020}body.\u{0020}And\u{0020}it\u{0020}contains\u{0020}an\u{0020}energy\u{0020}storage.\u{0020}When\u{0020}the\u{0020}energy\u{0020}of\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}is\u{0020}exhausted,\u{0020}it\u{0020}acts\u{0020}as\u{0020}a\u{0020}backup\u{0020}energy\u{0020}to\u{0020}avoid\u{0020}casualties\u{0020}of\u{0020}the\u{0020}driver\u{0020}due\u{0020}to\u{0020}the\u{0020}sudden\u{0020}release\u{0020}of\u{0020}gigantification.\nIn\u{0020}order\u{0020}to\u{0020}prevent\u{0020}Suzu\u{0020}from\u{0020}dying\u{0020}due\u{0020}to\u{0020}her\u{0020}own\u{0020}negligence\u{0020}while\u{0020}driving,\u{0020}the\u{0020}special\u{0020}equipment\u{0020}designed\u{0020}for\u{0020}Suzu\u{0020}is\u{0020}completed.\u{0020}By\u{0020}the\u{0020}way,\u{0020}the\u{0020}name\u{0020}was\u{0020}given\u{0020}by\u{0020}Suzu\u{0020}herself.\u{0020}For\u{0020}short,\u{0020}it\u{0020}is\u{0020}called\u{0020}Suzu\u{0020}Fox.", "icon_ling_zs2", "0", 3, 2, "3_{lv}*100", "Suzu", "1_110021_10", 10, "3_100", "310150,310151,310152", "0", "0", "0", "0", "0", "凌灵领铃泠泠狐丸", "由九州总部特研科研制的狐狸型能量传输装置，该装置能将幻化核心的能量增幅传递至身体各部位的机甲。并且内含能量存储机能，在幻化核心能量耗尽时充当备用能量避免驾驶员因突然解除巨大化造成伤亡。\n为了防止铃在驾驶的时候因为自己的疏忽造成死亡，以铃为设计对象的特供装备制作完成，顺带一提，名字是铃自己取得，简称铃铃狐丸。", "铃"},
[310152] = {310152, "Compassionate\u{0020}Shenzhou\u{0020}Antenna", "A\u{0020}communication\u{0020}device\u{0020}developed\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}Based\u{0020}on\u{0020}the\u{0020}second\u{0020}generation,\u{0020}it\u{0020}has\u{0020}added\u{0020}the\u{0020}ability\u{0020}to\u{0020}locate\u{0020}the\u{0020}coordinates\u{0020}of\u{0020}sin.\nSimilarly,\u{0020}the\u{0020}Shenzhou\u{0020}antenna\u{0020}is\u{0020}also\u{0020}a\u{0020}special\u{0020}version\u{0020}for\u{0020}Suzu.\u{0020}In\u{0020}it,\u{0020}a\u{0020}genius\u{0020}(stupid)\u{0020}tutorial\u{0020}is\u{0020}installed.", "icon_ling_zs3", "0", 3, 3, "1_{lv}*100", "Suzu", "1_110021_10", 10, "1_100", "310150,310151,310152", "0", "0", "0", "0", "0", "慈航普度神州天线", "由九州总部研制的一种通信装置，在二代的基础上增加了定位原罪坐标的能力。\n同样，神州天线也是铃特供的版本，在其中安置了天（笨）才（蛋）教程。", "铃"},
[310160] = {310160, "Nightwing", "The\u{0020}hand\u{0020}crossbow\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters.\u{0020}It\u{0020}is\u{0020}made\u{0020}of\u{0020}high-strength\u{0020}metal\u{0020}and\u{0020}can\u{0020}achieve\u{0020}accurate\u{0020}strikes\u{0020}at\u{0020}medium\u{0020}distances.\u{0020}Its\u{0020}power\u{0020}is\u{0020}no\u{0020}less\u{0020}than\u{0020}that\u{0020}of\u{0020}weapons\u{0020}of\u{0020}other\u{0020}Heavy\u{0020}type\u{0020}drivers.\nSilent\u{0020}and\u{0020}exquisite,\u{0020}but\u{0020}this\u{0020}protector\u{0020}seems\u{0020}not\u{0020}suitable\u{0020}to\u{0020}appear\u{0020}in\u{0020}the\u{0020}hunting\u{0020}ground.", "icon_heiyu_zs1", "0", 3, 1, "3_{lv}*100", "Kurobane", "1_110021_10", 10, "3_100", "310160,310161,310162", "0", "0", "0", "0", "0", "夜翼", "由艾吉斯总部设计并制造的手弩，采用高强度金属制作，中距离下能实现精确打击，威力丝毫不逊于其他火力型驾驶员的武器。\n悄无声息，精妙绝伦，但这位保护者似乎不太适合出现在狩猎场。", "黑羽"},
[310161] = {310161, "[Kurobane]", "The\u{0020}special\u{0020}metal\u{0020}leg\u{0020}armor\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters.\u{0020}Compared\u{0020}with\u{0020}its\u{0020}defensive\u{0020}performance,\u{0020}it\u{0020}focuses\u{0020}more\u{0020}on\u{0020}modification\u{0020}potential.\u{0020}In\u{0020}order\u{0020}to\u{0020}meet\u{0020}the\u{0020}needs\u{0020}of\u{0020}customization\u{0020}of\u{0020}drivers,\u{0020}interfaces\u{0020}are\u{0020}configured\u{0020}on\u{0020}the\u{0020}armor\u{0020}to\u{0020}configure\u{0020}external\u{0020}equipment.\nYou\u{0020}said\u{0020}something\u{0020}about\u{0020}betting\u{0020}on\u{0020}the\u{0020}name\u{0020}of\u{0020}\"Kurobane\".\u{0020}Does\u{0020}the\u{0020}name\u{0020}\"Kurobane\"\u{0020}have\u{0020}any\u{0020}special\u{0020}meaning...\u{0020}I'll\u{0020}ask...", "icon_heiyu_zs2", "0", 3, 2, "3_{lv}*100", "Kurobane", "1_110021_10", 10, "3_100", "310160,310161,310162", "0", "0", "0", "0", "0", "【黑羽】", "由艾吉斯总部设计并制造的特制金属腿甲，相较于防御性能，更着重于改造潜力，为满足驾驶员个性定制的需求在装甲上配置了接口用以配置外部装备。\n竟然说什么赌上【黑羽】的名字，难道【黑羽】这个名字有什么特殊的含义吗……我去问问……", "黑羽"},
[310162] = {310162, "Conditions\u{0020}of\u{0020}Loyalty", "The\u{0020}special\u{0020}communicator\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters.\u{0020}It\u{0020}is\u{0020}specially\u{0020}designed\u{0020}for\u{0020}troops\u{0020}performing\u{0020}covert\u{0020}operations.\u{0020}While\u{0020}ensuring\u{0020}team\u{0020}communication,\u{0020}it\u{0020}is\u{0020}equipped\u{0020}with\u{0020}a\u{0020}radar\u{0020}interference\u{0020}function.\nSwear\u{0020}allegiance.\u{0020}And\u{0020}then,\u{0020}there\u{0020}will\u{0020}a\u{0020}governer\u{0020}between\u{0020}you\u{0020}and\u{0020}me.\u{0020}But\u{0020}that's\u{0020}just\u{0020}nonsense.\u{0020}You\u{0020}think\u{0020}so\u{0020}too,\u{0020}right?", "icon_heiyu_zs3", "0", 3, 3, "1_{lv}*100", "Kurobane", "1_110021_10", 10, "1_100", "310160,310161,310162", "0", "0", "0", "0", "0", "忠诚的条件", "由艾吉斯总部设计并制造的特制通信器，专为执行隐秘行动的部队所设计，在确保队内通信的基础上搭载了雷达干扰的功能。\n宣誓效忠，从此以后你我有君臣之别，但还是别这样了，你也那么认为对吧？", "黑羽"},
[310170] = {310170, "Breaker", "The\u{0020}destructive\u{0020}weapon\u{0020}specially\u{0020}equipped\u{0020}by\u{0020}the\u{0020}R&D\u{0020}department\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}for\u{0020}the\u{0020}Danube\u{0020}First\u{0020}Guards\u{0020}Squad.\u{0020}Made\u{0020}of\u{0020}titanium\u{0020}alloy,\u{0020}although\u{0020}it\u{0020}is\u{0020}large\u{0020}in\u{0020}size,\u{0020}its\u{0020}weight\u{0020}is\u{0020}controlled.\u{0020}It\u{0020}has\u{0020}outstanding\u{0020}destructive\u{0020}power\u{0020}and\u{0020}can\u{0020}easily\u{0020}shatter\u{0020}the\u{0020}armor\u{0020}of\u{0020}sin.\u{0020}It\u{0020}is\u{0020}active\u{0020}on\u{0020}the\u{0020}front\u{0020}line\u{0020}of\u{0020}guarding\u{0020}the\u{0020}Danube\u{0020}Ark.\nFlora,\u{0020}Flora,\u{0020}what\u{0020}kind\u{0020}of\u{0020}Flora\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}be?\u{0020}When\u{0020}you\u{0020}pick\u{0020}up\u{0020}a\u{0020}weapon,\u{0020}you\u{0020}are\u{0020}a\u{0020}[guard].\u{0020}When\u{0020}you\u{0020}put\u{0020}down\u{0020}a\u{0020}weapon,\u{0020}you\u{0020}are\u{0020}a\u{0020}[mute].\u{0020}What\u{0020}kind\u{0020}of\u{0020}[Flora]\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}be?", "icon_fuluola_zs1", "0", 3, 1, "3_{lv}*100", "Flora", "1_110021_10", 10, "3_100", "310170,310171,310172", "0", "0", "0", "0", "0", "破裂者", "由多瑙支部研发部专为多瑙第一亲卫班配置的破坏性武装。使用钛合金制造，体积虽然庞大但重量上得以控制。破坏力拔群，能够轻易粉碎原罪的护甲，活跃在护卫多瑙方舟的第一线。\n芙萝拉、芙萝拉你想成为什么样的芙萝拉，你拿起武器是【亲卫】，你放下武器是【哑巴】，你想成为什么样的【芙萝拉】。", "芙萝拉"},
[310171] = {310171, "Armor\u{0020}Force\u{0020}Field", "The\u{0020}protective\u{0020}armor\u{0020}specially\u{0020}equipped\u{0020}by\u{0020}the\u{0020}R&D\u{0020}department\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}for\u{0020}the\u{0020}Danube\u{0020}First\u{0020}Guards\u{0020}Squad.\u{0020}Made\u{0020}of\u{0020}titanium\u{0020}alloy\u{0020}and\u{0020}equipped\u{0020}around\u{0020}the\u{0020}maid\u{0020}outfit.\u{0020}It\u{0020}has\u{0020}extremely\u{0020}high\u{0020}impact\u{0020}resistance\u{0020}and\u{0020}temperature\u{0020}adaptability.\u{0020}It\u{0020}can\u{0020}easily\u{0020}resist\u{0020}most\u{0020}attacks.\nMiss\u{0020}Flora\u{0020}is\u{0020}a\u{0020}person\u{0020}with\u{0020}strong\u{0020}adaptability.\u{0020}Even\u{0020}for\u{0020}things\u{0020}she\u{0020}doesn't\u{0020}want\u{0020}to\u{0020}do...\u{0020}she\u{0020}will\u{0020}quickly\u{0020}adjust\u{0020}her\u{0020}mindset.", "icon_fuluola_zs2", "0", 3, 2, "3_{lv}*100", "Flora", "1_110021_10", 10, "3_100", "310170,310171,310172", "0", "0", "0", "0", "0", "甲胄力场", "由多瑙支部研发部专为多瑙第一亲卫班配置的防护装甲。使用钛合金制造，配置在女仆装的外围。抗击打能力，温度适性极高。能够轻松抵御大部分的攻击。\n芙萝拉小姐，是一位适应性很强的人，即使是不愿意做的事情……她也会很快地调整自己的心态。", "芙萝拉"},
[310172] = {310172, "Transmitter\u{0020}-\u{0020}Maid\u{0020}Type", "The\u{0020}communication\u{0020}device\u{0020}specially\u{0020}configured\u{0020}by\u{0020}the\u{0020}R&D\u{0020}department\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}for\u{0020}the\u{0020}Danube\u{0020}First\u{0020}Guards\u{0020}Squad.\u{0020}While\u{0020}having\u{0020}communication\u{0020}functions\u{0020}and\u{0020}information\u{0020}processing\u{0020}functions,\u{0020}it\u{0020}can\u{0020}perform\u{0020}wide-range\u{0020}communication\u{0020}control\u{0020}centered\u{0020}on\u{0020}the\u{0020}wearer\u{0020}to\u{0020}facilitate\u{0020}the\u{0020}wearer's\u{0020}battle\u{0020}deployment.\nAlthough\u{0020}it\u{0020}is\u{0020}a\u{0020}guard\u{0020}squad,\u{0020}but\u{0020}what's\u{0020}with\u{0020}the\u{0020}maid\u{0020}style?\u{0020}Is\u{0020}it\u{0020}done\u{0020}by\u{0020}a\u{0020}nasty\u{0020}scientist?", "icon_fuluola_zs3", "0", 3, 3, "3_{lv}*100", "Flora", "1_110021_10", 10, "3_100", "310170,310171,310172", "0", "0", "0", "0", "0", "发信器·女仆型", "由多瑙支部研发部专为多瑙第一亲卫班配置的通信装置。具有通信机能和情报处理机能的同时，能够以装备者为中心进行广范围的通信控制，以便装备者进行战斗部署。\n虽然是亲卫没错，但是为什么为我设计的外装风格是女仆样式的，是哪位性格恶俗的科学官做的吗？", "芙萝拉"},
[310180] = {310180, "Sonic\u{0020}Speed\u{0020}Blade", "The\u{0020}weapon\u{0020}designed\u{0020}by\u{0020}Shirogane\u{0020}herself\u{0020}and\u{0020}commissioned\u{0020}to\u{0020}AEGIS\u{0020}for\u{0020}production.\u{0020}Lighter\u{0020}materials\u{0020}are\u{0020}used\u{0020}to\u{0020}meet\u{0020}her\u{0020}combat\u{0020}needs.\u{0020}The\u{0020}weapon\u{0020}only\u{0020}relies\u{0020}on\u{0020}sharpness\u{0020}as\u{0020}the\u{0020}only\u{0020}means\u{0020}of\u{0020}killing.\u{0020}Only\u{0020}people\u{0020}with\u{0020}rich\u{0020}combat\u{0020}experience\u{0020}like\u{0020}Shirogane\u{0020}can\u{0020}maximize\u{0020}its\u{0020}advantages.\nMy\u{0020}people\u{0020}have\u{0020}escaped\u{0020}danger...\u{0020}Great.\u{0020}Now\u{0020}the\u{0020}meaning\u{0020}of\u{0020}my\u{0020}existence\u{0020}is\u{0020}only\u{0020}fighting.\u{0020}[Soldier]\u{0020}Shirogane,\u{0020}reporting.", "icon_yin_zs1", "0", 3, 1, "1_{lv}*100", "Shirogane", "1_110021_10", 10, "1_100", "310180,310181,310182", "0", "0", "0", "0", "0", "音速高频刀", "由银自己设计并委托艾吉斯制作的武器，为了满足自己的作战需求，采用较轻材质。武器仅依靠锋锐作为唯一的杀伤手段，只有像银这样的战斗经验丰富的人才能最大限度发挥它的优势。\n我的族人已经摆脱了危险……太好了，我生存的意义现在终于只剩下战斗了，【士兵】银，报到。", "银"},
[310181] = {310181, "Silver\u{0020}Wolf", "The\u{0020}armor\u{0020}designed\u{0020}by\u{0020}Shirogane\u{0020}herself\u{0020}and\u{0020}commissioned\u{0020}to\u{0020}AEGIS\u{0020}for\u{0020}production.\u{0020}Made\u{0020}of\u{0020}light\u{0020}metal\u{0020}materials,\u{0020}focuses\u{0020}on\u{0020}mobility.\u{0020}While\u{0020}providing\u{0020}minimum\u{0020}defense,\u{0020}it\u{0020}can\u{0020}help\u{0020}her\u{0020}easily\u{0020}adapt\u{0020}to\u{0020}various\u{0020}environments\u{0020}for\u{0020}high-speed\u{0020}combat.\nThis\u{0020}is\u{0020}gigantification.\u{0020}Feels\u{0020}so\u{0020}wonderful.\u{0020}Even\u{0020}if\u{0020}I'm\u{0020}injured,\u{0020}I\u{0020}won't\u{0020}be\u{0020}really\u{0020}injured.\u{0020}But\u{0020}it's\u{0020}a\u{0020}bit\u{0020}inconvenient\u{0020}to\u{0020}move...\u{0020}There\u{0020}are\u{0020}also\u{0020}disadvantages\u{0020}to\u{0020}a\u{0020}gigantified\u{0020}body.", "icon_yin_zs2", "0", 3, 2, "3_{lv}*100", "Shirogane", "1_110021_10", 10, "3_100", "310180,310181,310182", "0", "0", "0", "0", "0", "银狼", "由银自己设计并委托艾吉斯制作的护甲，采用轻金属材质制造，注重机动性。在提供最低限度的防御力的同时，能帮助她轻松适应各种地面环境进行高速战斗。\n这就是巨大化，好奇妙，即使受伤也不会受到真实的伤害，但是行动上有点不方便……巨大化的躯体也有这种坏处呢。", "银"},
[310182] = {310182, "Photon\u{0020}Cloak", "The\u{0020}cloak\u{0020}designed\u{0020}by\u{0020}Shirogane\u{0020}herself\u{0020}and\u{0020}commissioned\u{0020}to\u{0020}AEGIS\u{0020}for\u{0020}production.\u{0020}Considering\u{0020}her\u{0020}flexible\u{0020}combat\u{0020}style,\u{0020}she\u{0020}did\u{0020}not\u{0020}use\u{0020}physical\u{0020}materials.\u{0020}The\u{0020}principle\u{0020}is\u{0020}similar\u{0020}to\u{0020}many\u{0020}light\u{0020}wing-type\u{0020}armaments.\u{0020}While\u{0020}playing\u{0020}a\u{0020}decorative\u{0020}role,\u{0020}it\u{0020}improves\u{0020}the\u{0020}mobility\u{0020}of\u{0020}the\u{0020}wearer.\nDoes\u{0020}Shirogane\u{0020}also\u{0020}consider\u{0020}the\u{0020}aesthetics\u{0020}of\u{0020}clothing\u{0020}while\u{0020}fighting?\u{0020}Perhaps\u{0020}since\u{0020}you\u{0020}came\u{0020}to\u{0020}AEGIS,\u{0020}you\u{0020}are\u{0020}no\u{0020}longer\u{0020}a\u{0020}[soldier].", "icon_yin_zs3", "0", 3, 3, "3_{lv}*100", "Shirogane", "1_110021_10", 10, "3_100", "310180,310181,310182", "0", "0", "0", "0", "0", "光子披风", "由银自己设计并委托艾吉斯制作的披风，考虑到自己灵活的作战风格，并未采用实体材质。原理与诸多光翼类武装相近，在起到一定的装饰作用的同时，提高装备者的机动力。\n银原来也会在战斗的同时考虑到服饰的美观度吗？也许从你来到艾吉斯后，就渐渐不再是【士兵】了。", "银"},
[310190] = {310190, "Meat\u{0020}Processing", "The\u{0020}self-developed\u{0020}weapon\u{0020}of\u{0020}the\u{0020}academy\u{0020}affiliated\u{0020}to\u{0020}the\u{0020}Sahara\u{0020}Branch.\u{0020}Its\u{0020}appearance\u{0020}is\u{0020}a\u{0020}pair\u{0020}of\u{0020}hammers\u{0020}with\u{0020}certain\u{0020}weight\u{0020}and\u{0020}hardness.\u{0020}It\u{0020}is\u{0020}an\u{0020}improvement\u{0020}of\u{0020}the\u{0020}existing\u{0020}standard\u{0020}equipment\u{0020}by\u{0020}the\u{0020}academy,\u{0020}which\u{0020}is\u{0020}sufficient\u{0020}to\u{0020}resist\u{0020}the\u{0020}invasion\u{0020}of\u{0020}low-level\u{0020}sin\u{0020}on\u{0020}the\u{0020}battlefield.\u{0020}The\u{0020}cat\u{0020}paw\u{0020}pattern\u{0020}on\u{0020}the\u{0020}hammer\u{0020}is\u{0020}a\u{0020}special\u{0020}coating\u{0020}requested\u{0020}by\u{0020}Tenten.\n\"Look,\u{0020}I'll\u{0020}make\u{0020}them\u{0020}into\u{0020}hamburger\u{0020}patties\u{0020}with\u{0020}these\u{0020}two\u{0020}hammers.\"", "icon_tiantian_zs1", "0", 2, 1, "1_{lv}*100", "Tenten", "1_110021_5", 10, "1_100", "310190,310191,310192", "0", "0", "0", "0", "0", "肉质处理", "萨哈拉支部所属学院自研武器。外形是一对拥有一定的重量和硬度的双锤。是学院对现有的制式装备进行的改良，足以在战场上对抗低等原罪的入侵。锤上的猫爪图案是天天要求的特别涂装。\n“看我用这两个锤子把它们做成汉堡肉饼。”", "天天"},
[310191] = {310191, "Make\u{0020}Everyone\u{0020}Happy", "The\u{0020}communication\u{0020}equipment\u{0020}independently\u{0020}developed\u{0020}by\u{0020}the\u{0020}academy\u{0020}of\u{0020}the\u{0020}Sahara\u{0020}Branch.\u{0020}It\u{0020}is\u{0020}improved\u{0020}through\u{0020}the\u{0020}existing\u{0020}standard\u{0020}equipment\u{0020}of\u{0020}the\u{0020}academy.\u{0020}It\u{0020}has\u{0020}a\u{0020}data\u{0020}analysis\u{0020}module\u{0020}built\u{0020}in,\u{0020}which\u{0020}can\u{0020}automatically\u{0020}detect\u{0020}information\u{0020}around\u{0020}the\u{0020}battlefield\u{0020}and\u{0020}inform\u{0020}of\u{0020}abnormalities.\u{0020}It\u{0020}is\u{0020}very\u{0020}suitable\u{0020}for\u{0020}novice\u{0020}drivers\u{0020}to\u{0020}get\u{0020}familiar\u{0020}with\u{0020}the\u{0020}battlefield\u{0020}and\u{0020}quickly\u{0020}enter\u{0020}the\u{0020}battle\u{0020}state.\n\"I\u{0020}will\u{0020}cheer\u{0020}everyone\u{0020}up\u{0020}through\u{0020}cooking.\"", "icon_tiantian_zs2", "0", 2, 2, "3_{lv}*100", "Tenten", "1_110021_5", 10, "3_100", "310190,310191,310192", "0", "0", "0", "0", "0", "让所有人都幸福", "萨哈拉支部所学院自研的通信设备。通过学院现有的制式装备进行改良，内置了数据分析模块，可以自动为探查出战场周围的情报，并告知异常。非常适合新人驾驶员用来熟悉战场，快速进入战斗状态。\n“我会通过料理让所有人都感到幸福。”", "天天"},
[310192] = {310192, "Glory\u{0020}of\u{0020}the\u{0020}Chef", "The\u{0020}propulsion\u{0020}device\u{0020}independently\u{0020}developed\u{0020}by\u{0020}the\u{0020}academy\u{0020}affiliated\u{0020}to\u{0020}the\u{0020}Sahara\u{0020}Branch.\u{0020}It\u{0020}has\u{0020}excellent\u{0020}endurance\u{0020}and\u{0020}stability\u{0020}and\u{0020}can\u{0020}be\u{0020}used\u{0020}normally\u{0020}even\u{0020}in\u{0020}harsh\u{0020}environments\u{0020}such\u{0020}as\u{0020}sandstorms.\u{0020}However,\u{0020}in\u{0020}terms\u{0020}of\u{0020}propulsion\u{0020}speed,\u{0020}it\u{0020}is\u{0020}not\u{0020}as\u{0020}good\u{0020}as\u{0020}the\u{0020}standard\u{0020}thruster\u{0020}in\u{0020}the\u{0020}academy.\n\"No\u{0020}matter\u{0020}how\u{0020}bad\u{0020}the\u{0020}kitchen\u{0020}environment\u{0020}is,\u{0020}an\u{0020}excellent\u{0020}chef\u{0020}can\u{0020}cook\u{0020}delicious\u{0020}food.\"", "icon_tiantian_zs3", "0", 2, 3, "1_{lv}*100", "Tenten", "1_110021_5", 10, "1_100", "310190,310191,310192", "0", "0", "0", "0", "0", "厨师的荣光", "萨哈拉支部所属学院自研的推进装置。具备优秀的续航能力和稳定性，即使是再恶劣的环境如沙暴之中也能正常使用。但是在推进速度方面不比学院中的制式推进器。\n“环境再差的厨房，优秀的厨师也可以烹调出美食。”", "天天"},
