[310572] = {310572, "\"My\u{0020}Familiar\"", "The\u{0020}savior\u{0020}of\u{0020}the\u{0020}world\u{0020}has\u{0020}also\u{0020}turned\u{0020}into\u{0020}an\u{0020}octopus,\u{0020}but\u{0020}luckily\u{0020}I\u{0020}saved\u{0020}him\u{0020}in\u{0020}time.\u{0020}Otherwise,\u{0020}the\u{0020}beast\u{0020}he\u{0020}became\u{0020}would\u{0020}have\u{0020}ravaged\u{0020}the\u{0020}entire\u{0020}world.\n\"Isn't\u{0020}that\u{0020}just\u{0020}me!?\"", "icon_sikadimv_zs3", "0", 4, 3, "1_{lv}*100", "Skadi\u{0020}(Witch)", "1_110021_20", 10, "1_100", "310570,310571,310572", "0", "0", "0", "0", "0", "0", "0", "0"},
[310590] = {310590, "Gift\u{0020}of\u{0020}Pallas", "A\u{0020}lance-type\u{0020}weapon\u{0020}developed\u{0020}by\u{0020}AEGIS\u{0020}Danube\u{0020}Branch\u{0020}and\u{0020}converted\u{0020}for\u{0020}Dragon\u{0020}Knights\u{0020}use.\u{0020}Its\u{0020}slightly\u{0020}luxurious\u{0020}decorations\u{0020}are\u{0020}not\u{0020}merely\u{0020}for\u{0020}show.\u{0020}Only\u{0020}enemies\u{0020}pierced\u{0020}by\u{0020}it\u{0020}know\u{0020}the\u{0020}pain\u{0020}hidden\u{0020}within.\nThe\u{0020}lance\u{0020}is\u{0020}only\u{0020}a\u{0020}feint.\u{0020}The\u{0020}short\u{0020}sword\u{0020}in\u{0020}the\u{0020}right\u{0020}hand\u{0020}is\u{0020}the\u{0020}true\u{0020}key\u{0020}to\u{0020}victory.", "icon_mihaier_zs1", "0", 4, 1, "1_{lv}*100", "Mikael", "1_110021_20", 10, "1_100", "310590,310591,310592", "0", "0", "0", "0", "0", "0", "0", "0"},
[310591] = {310591, "Will\u{0020}for\u{0020}Total\u{0020}Victory", "A\u{0020}communication\u{0020}device\u{0020}developed\u{0020}by\u{0020}AEGIS\u{0020}Danube\u{0020}Branch\u{0020}and\u{0020}converted\u{0020}for\u{0020}Dragon\u{0020}Knights\u{0020}use.\u{0020}Since\u{0020}Dragon\u{0020}Knights\u{0020}carry\u{0020}the\u{0020}risk\u{0020}of\u{0020}going\u{0020}berserk,\u{0020}it\u{0020}not\u{0020}only\u{0020}provides\u{0020}normal\u{0020}communication\u{0020}functions,\u{0020}but\u{0020}also\u{0020}helps\u{0020}stabilize\u{0020}the\u{0020}Driver's\u{0020}brain\u{0020}waves.\nWin\u{0020}the\u{0020}local\u{0020}battle\u{0020}first,\u{0020}then\u{0020}crush\u{0020}the\u{0020}elite\u{0020}enemy,\u{0020}and\u{0020}finally\u{0020}achieve\u{0020}total\u{0020}victory.", "icon_mihaier_zs2", "0", 4, 2, "3_{lv}*100", "Mikael", "1_110021_20", 10, "3_100", "310590,310591,310592", "0", "0", "0", "0", "0", "0", "0", "0"},
[310592] = {310592, "Triumph", "A\u{0020}mobility\u{0020}device\u{0020}developed\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}Danube\u{0020}Branch\u{0020}laboratory\u{0020}specifically\u{0020}for\u{0020}Dragon\u{0020}Knights.\u{0020}When\u{0020}deployed,\u{0020}its\u{0020}mechanical\u{0020}structure\u{0020}maintains\u{0020}balance\u{0020}during\u{0020}charges\u{0020}like\u{0020}a\u{0020}pair\u{0020}of\u{0020}wings,\u{0020}while\u{0020}also\u{0020}allowing\u{0020}the\u{0020}user\u{0020}to\u{0020}perform\u{0020}maneuvers\u{0020}the\u{0020}enemy\u{0020}does\u{0020}not\u{0020}expect.\nAs\u{0020}expected,\u{0020}I\u{0020}won\u{0020}again...\u{0020}But\u{0020}what\u{0020}am\u{0020}I\u{0020}fighting\u{0020}for?", "icon_mihaier_zs3", "0", 4, 3, "1_{lv}*100", "Mikael", "1_110021_20", 10, "3_100", "310590,310591,310592", "0", "0", "0", "0", "0", "0", "0", "0"},
[310610] = {310610, "Mira's\u{0020}Custom\u{0020}Choker", "The\u{0020}accessory\u{0020}Mira\u{0020}Kamiunten\u{0020}habitually\u{0020}wears\u{0020}around\u{0020}her\u{0020}neck.\nIt\u{0020}feels\u{0020}like\u{0020}as\u{0020}long\u{0020}as\u{0020}she\u{0020}has\u{0020}this\u{0020}choker\u{0020}on,\u{0020}she\u{0020}gives\u{0020}off\u{0020}a\u{0020}very\u{0020}trendy\u{0020}\"delinquent\u{0020}gal\"\u{0020}vibe.", "icon_shangyuntianmeiluo_zs1", "0", 4, 1, "1_{lv}*100", "Mira\u{0020}Kamiunten", "1_110021_20", 10, "1_100", "310610,310611,310612", "0", "0", "0", "0", "0", "0", "0", "0"},
[310611] = {310611, "Mira's\u{0020}Custom\u{0020}Uniform", "The\u{0020}uniform\u{0020}of\u{0020}Mira\u{0020}Kamiunten,\u{0020}Commander\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force's\u{0020}Second\u{0020}Squad,\u{0020}modified\u{0020}appropriately\u{0020}to\u{0020}suit\u{0020}her\u{0020}personal\u{0020}taste.\nWhenever\u{0020}she\u{0020}wears\u{0020}this\u{0020}outfit,\u{0020}everyone\u{0020}subconsciously\u{0020}treats\u{0020}her\u{0020}like\u{0020}the\u{0020}biker\u{0020}gang\u{0020}delinquent\u{0020}she\u{0020}used\u{0020}to\u{0020}be.", "icon_shangyuntianmeiluo_zs2", "0", 4, 2, "3_{lv}*100", "Mira\u{0020}Kamiunten", "1_110021_20", 10, "3_100", "310610,310611,310612", "0", "0", "0", "0", "0", "0", "0", "0"},
[310612] = {310612, "Mira's\u{0020}Custom\u{0020}Boots", "The\u{0020}long\u{0020}boots\u{0020}worn\u{0020}by\u{0020}Mira\u{0020}Kamiunten,\u{0020}Commander\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force's\u{0020}Second\u{0020}Squad,\u{0020}during\u{0020}her\u{0020}daily\u{0020}activities.\nIn\u{0020}reality,\u{0020}they\u{0020}are\u{0020}just\u{0020}ordinary\u{0020}boots\u{0020}with\u{0020}nothing\u{0020}particularly\u{0020}special\u{0020}about\u{0020}them.", "icon_shangyuntianmeiluo_zs3", "0", 4, 3, "3_{lv}*100", "Mira\u{0020}Kamiunten", "1_110021_20", 10, "3_100", "310610,310611,310612", "0", "0", "0", "0", "0", "0", "0", "0"},
[320000] = {320000, "Unjust\u{0020}Act\u{0020}of\u{0020}Justice", "The\u{0020}Nimbus\u{0020}energy\u{0020}required\u{0020}for\u{0020}this\u{0020}equipment\u{0020}can\u{0020}support\u{0020}a\u{0020}team\u{0020}to\u{0020}sortie\u{0020}more\u{0020}than\u{0020}three\u{0020}times,\u{0020}and\u{0020}its\u{0020}lethality\u{0020}is\u{0020}proportional\u{0020}to\u{0020}energy\u{0020}consumption.\nPowerful\u{0020}firepower,\u{0020}like\u{0020}a\u{0020}roar\u{0020}from\u{0020}hell.\u{0020}The\u{0020}sweeping\u{0020}flames\u{0020}will\u{0020}surely\u{0020}burn\u{0020}everything\u{0020}to\u{0020}ashes.", "icon_jinkula_zs1", "0", 2, 1, "3_{lv}*100", "Kinkura", "1_110021_5", 10, "3_100", "320000,320001,320002", "0", "0", "0", "0", "0", "正义的不义之举", "启用这件装备进行一次战斗所需要的尼姆比斯能可以维持一个正常小队出击3次有余，其杀伤力也与消耗成正比。\n强大的火力，仿佛来自地狱的咆哮，席卷的烈焰必将一切事物焚烧殆尽。", "金库啦"},
[320001] = {320001, "Powerful\u{0020}Wealth", "The\u{0020}foot\u{0020}armor\u{0020}customized\u{0020}for\u{0020}Kinkura\u{0020}by\u{0020}AEGIS.\nIt\u{0020}is\u{0020}said\u{0020}that\u{0020}Kinkura\u{0020}designated\u{0020}the\u{0020}scientist\u{0020}she\u{0020}liked\u{0020}most\u{0020}to\u{0020}make\u{0020}it.", "icon_jinkula_zs2", "0", 2, 2, "1_{lv}*100", "Kinkura", "1_110021_5", 10, "1_100", "320000,320001,320002", "0", "0", "0", "0", "0", "无所不能之财", "艾吉斯为金库啦定制的足甲。\n听闻是金库啦直接上门指定了中意的科学官来制作。", "金库啦"},
[320002] = {320002, "Emotion\u{0020}Is\u{0020}Priceless", "The\u{0020}power\u{0020}device\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}Features\u{0020}a\u{0020}small\u{0020}Nimbus\u{0020}reactor\u{0020}and\u{0020}provides\u{0020}a\u{0020}ton\u{0020}of\u{0020}power\u{0020}to\u{0020}the\u{0020}user.\nI\u{0020}will\u{0020}use\u{0020}valuable\u{0020}things\u{0020}to\u{0020}protect\u{0020}priceless\u{0020}things.", "icon_jinkula_zs3", "0", 2, 3, "1_{lv}*100", "Kinkura", "1_110021_5", 10, "1_100", "320000,320001,320002", "0", "0", "0", "0", "0", "情感乃无价之物", "艾吉斯设计并制造的动力装置，其内部整合了小型尼姆比斯反应堆，能够为使用者提供大量动力。\n我会用有价之物来守护无价之物。", "金库啦"},
[320010] = {320010, "Flawless\u{0020}Laziness", "Gin's\u{0020}life\u{0020}goal\u{0020}is\u{0020}to\u{0020}stay\u{0020}at\u{0020}home\u{0020}forever!\u{0020}If\u{0020}Alice\u{0020}is\u{0020}\"the\u{0020}perfect\u{0020}lady\",\u{0020}then\u{0020}Gin\u{0020}is\u{0020}\"the\u{0020}perfect\u{0020}underachiever\"!\u{0020}The\u{0020}perfect\u{0020}underachiever\u{0020}who\u{0020}makes\u{0020}everyone\u{0020}have\u{0020}no\u{0020}expectations\u{0020}of\u{0020}her.\u{0020}However,\u{0020}Gin\u{0020}still\u{0020}became\u{0020}a\u{0020}driver.\nIf\u{0020}there\u{0020}is\u{0020}still\u{0020}someone\u{0020}in\u{0020}the\u{0020}world\u{0020}who\u{0020}has\u{0020}expectations\u{0020}for\u{0020}her,\u{0020}it\u{0020}must\u{0020}be\u{0020}Alice\u{0020}and\u{0020}Tina.", "icon_jing_zs1", "0", 3, 1, "1_{lv}*100", "Gin", "1_110021_10", 10, "1_100", "320010,320011,320012", "0", "0", "0", "0", "0", "正义的不义之举", "启用这件装备进行一次战斗所需要的尼姆比斯能可以维持一个正常小队出击3次有余，其杀伤力也与消耗成正比。\n强大的火力，仿佛来自地狱的咆哮，席卷的烈焰必将一切事物焚烧殆尽。", "金库啦"},
[320011] = {320011, "Consecutive\u{0020}Last\u{0020}Place", "Gin\u{0020}Creteia\u{0020}still\u{0020}has\u{0020}to\u{0020}leave\u{0020}school\u{0020}and\u{0020}home\u{0020}and\u{0020}go\u{0020}to\u{0020}the\u{0020}battlefield\u{0020}of\u{0020}drivers.\u{0020}It\u{0020}all\u{0020}thanks\u{0020}to\u{0020}her\u{0020}excellent\u{0020}sister,\u{0020}Alice\u{0020}Creteia,\u{0020}that\u{0020}she\u{0020}can\u{0020}still\u{0020}do\u{0020}so.\u{0020}Unable\u{0020}to\u{0020}stand\u{0020}Gin's\u{0020}laziness,\u{0020}Alice\u{0020}arranged\u{0020}Gin\u{0020}into\u{0020}her\u{0020}own\u{0020}team.\u{0020}While\u{0020}providing\u{0020}protection,\u{0020}she\u{0020}hopes\u{0020}to\u{0020}temper\u{0020}Gin.\nThe\u{0020}reason\u{0020}why\u{0020}Gin\u{0020}can\u{0020}live\u{0020}such\u{0020}a\u{0020}comfortable\u{0020}life\u{0020}is\u{0020}entirely\u{0020}because\u{0020}of\u{0020}her\u{0020}sister.", "icon_jing_zs2", "0", 3, 2, "3_{lv}*100", "Gin", "1_110021_10", 10, "3_100", "320010,320011,320012", "0", "0", "0", "0", "0", "无所不能之财", "艾吉斯为金库啦定制的足甲。\n听闻是金库啦直接上门指定了中意的科学官来制作。", "金库啦"},
[320012] = {320012, "What\u{0020}Should\u{0020}the\u{0020}Future\u{0020}Be\u{0020}Like", "If\u{0020}one\u{0020}day,\u{0020}Alice\u{0020}falls,\u{0020}perhaps\u{0020}Gin\u{0020}will\u{0020}truly\u{0020}start\u{0020}to\u{0020}face\u{0020}up\u{0020}to\u{0020}her\u{0020}own\u{0020}life,\u{0020}face\u{0020}up\u{0020}to\u{0020}her\u{0020}muddling\u{0020}through\u{0020}every\u{0020}day,\u{0020}face\u{0020}up\u{0020}to\u{0020}her\u{0020}past,\u{0020}present,\u{0020}and\u{0020}even\u{0020}future.\u{0020}Then\u{0020}she\u{0020}will\u{0020}find\u{0020}that\u{0020}in\u{0020}these\u{0020}moments,\u{0020}there\u{0020}are\u{0020}protections\u{0020}unfolded\u{0020}for\u{0020}her\u{0020}by\u{0020}Alice...\u{0020}But\u{0020}such\u{0020}a\u{0020}future\u{0020}is\u{0020}impossible.\nJust\u{0020}as\u{0020}Gin\u{0020}trusts\u{0020}Alice\u{0020}so\u{0020}much,\u{0020}the\u{0020}flawless\u{0020}Alice\u{0020}will\u{0020}not\u{0020}fall.", "icon_jing_zs3", "0", 3, 3, "3_{lv}*100", "Gin", "1_110021_10", 10, "3_100", "320010,320011,320012", "0", "0", "0", "0", "0", "情感乃无价之物", "艾吉斯设计并制造的动力装置，其内部整合了小型尼姆比斯反应堆，能够为使用者提供大量动力。\n我会用有价之物来守护无价之物。", "金库啦"},
[320020] = {320020, "Ashe", "This\u{0020}weapon\u{0020}is\u{0020}a\u{0020}piece\u{0020}of\u{0020}equipment\u{0020}custom-ordered\u{0020}by\u{0020}Shiranui\u{0020}from\u{0020}the\u{0020}military.\u{0020}It\u{0020}consumed\u{0020}three\u{0020}times\u{0020}more\u{0020}alloys\u{0020}and\u{0020}Nimbus\u{0020}crystals\u{0020}than\u{0020}mass-produced\u{0020}equipment.\u{0020}Therefore,\u{0020}it\u{0020}is\u{0020}extremely\u{0020}excellent\u{0020}in\u{0020}range\u{0020}and\u{0020}durability,\u{0020}but\u{0020}it\u{0020}has\u{0020}extremely\u{0020}high\u{0020}requirements\u{0020}on\u{0020}the\u{0020}pulling\u{0020}force\u{0020}of\u{0020}the\u{0020}user.\nRumor\u{0020}has\u{0020}it\u{0020}that\u{0020}when\u{0020}there\u{0020}is\u{0020}no\u{0020}one\u{0020}around,\u{0020}she\u{0020}will\u{0020}call\u{0020}her\u{0020}weapon\u{0020}in\u{0020}an\u{0020}affectionate\u{0020}tone.\u{0020}Sure,\u{0020}everyone\u{0020}names\u{0020}their\u{0020}own\u{0020}weapons,\u{0020}it\u{0020}is\u{0020}still\u{0020}weird\u{0020}to\u{0020}treat\u{0020}weapons\u{0020}as\u{0020}pets...", "icon_buzhihuo_zs1", "0", 2, 1, "3_{lv}*100", "Shiranui", "1_110021_5", 10, "3_100", "320020,320021,320022", "0", "0", "0", "0", "0", "阿射", "该武器是由不知火主动向军方订制的装备，据说耗费了比传统量产型装备多三倍的合金和尼姆比斯晶体，因此在射程、耐久度上极优，但对使用者的拉力要求极高。\n据传四下无人时，她会以亲昵的口吻称呼自己的武器。虽然大家或多或少都有给自己武器取名的习惯，但是把武器当宠物的还是很少见的……呃，应该算少见的？", "不知火"},
[320021] = {320021, "Mie", "The\u{0020}arrow\u{0020}box\u{0020}custom-ordered\u{0020}by\u{0020}Shiranui\u{0020}directly\u{0020}from\u{0020}the\u{0020}military.\u{0020}The\u{0020}arrowheads\u{0020}contained\u{0020}in\u{0020}it\u{0020}are\u{0020}all\u{0020}coated\u{0020}with\u{0020}a\u{0020}coating\u{0020}that\u{0020}can\u{0020}generate\u{0020}thermal\u{0020}energy\u{0020}through\u{0020}friction.\u{0020}The\u{0020}arrow\u{0020}chamber\u{0020}is\u{0020}filled\u{0020}with\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}flammable\u{0020}and\u{0020}explosive\u{0020}materials.\u{0020}After\u{0020}hitting\u{0020}the\u{0020}target,\u{0020}it\u{0020}will\u{0020}produce\u{0020}a\u{0020}violent\u{0020}explosion\u{0020}and\u{0020}flames.\nThree\u{0020}arrows\u{0020}are\u{0020}enough\u{0020}to\u{0020}determine\u{0020}the\u{0020}trend\u{0020}of\u{0020}a\u{0020}battle.", "icon_buzhihuo_zs2", "0", 2, 2, "1_{lv}*100", "Shiranui", "1_110021_5", 10, "1_100", "320020,320021,320022", "0", "0", "0", "0", "0", "三枝", "由不知火向军方直接订制的箭箱，里面装载的箭头上均涂抹了可与空间摩擦直接产生热能的涂料，箭腔内装满了大量的易燃易爆物，在撞击到目标后，会产生剧烈的爆炸和高温的火焰。\n要决定一场战斗的走势，只需要三支箭就够了。", "不知火"},
[320022] = {320022, "Gun\u{0020}Pavilion", "The\u{0020}special\u{0020}armor\u{0020}for\u{0020}the\u{0020}Fuurinkazan\u{0020}team\u{0020}made\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}This\u{0020}armor\u{0020}has\u{0020}extremely\u{0020}high\u{0020}protection\u{0020}and\u{0020}is\u{0020}extremely\u{0020}light\u{0020}in\u{0020}weight.\nShiranui\u{0020}plays\u{0020}the\u{0020}role\u{0020}of\u{0020}\"long\u{0020}mother\"\u{0020}in\u{0020}the\u{0020}team...\u{0020}What\u{0020}is\u{0020}\"long\u{0020}mother\"?\u{0020}I'm\u{0020}not\u{0020}very\u{0020}aware\u{0020}of\u{0020}that\u{0020}either,\u{0020}but\u{0020}I\u{0020}do\u{0020}know\u{0020}that\u{0020}there\u{0020}is\u{0020}a\u{0020}similar\u{0020}existence\u{0020}in\u{0020}another\u{0020}team.\u{0020}Could\u{0020}this\u{0020}position\u{0020}be\u{0020}some\u{0020}kind\u{0020}of\u{0020}historical\u{0020}reserved\u{0020}combination?", "icon_buzhihuo_zs3", "0", 2, 3, "1_{lv}*100", "Shiranui", "1_110021_5", 10, "1_100", "320020,320021,320022", "0", "0", "0", "0", "0", "铳阁", "由九州总部制作的风林火山小队专用装甲，该装甲拥有极高的防护且但重量极轻。\n不知火在队伍中担任着的“长妈妈”的位置……你问什么是“长妈妈”？我也不是很清楚，但是我知道有另外一个小队也有类似的存在，这个职位该不会是什么历史保留组合吧？", "不知火"},
[320030] = {320030, "Single-Line\u{0020}Suppression", "The\u{0020}first-generation\u{0020}heavy\u{0020}firepower\u{0020}equipment\u{0020}produced\u{0020}by\u{0020}\"Siren\",\u{0020}the\u{0020}largest\u{0020}arms\u{0020}manufacturer\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}The\u{0020}initial\u{0020}velocity\u{0020}provided\u{0020}by\u{0020}this\u{0020}armament\u{0020}is\u{0020}five\u{0020}times\u{0020}that\u{0020}of\u{0020}similar\u{0020}armaments.\u{0020}Therefore,\u{0020}it\u{0020}has\u{0020}extreme\u{0020}armor-piercing\u{0020}ability.\nThis\u{0020}weapon\u{0020}alone\u{0020}can\u{0020}suppress\u{0020}a\u{0020}whole\u{0020}line\u{0020}of\u{0020}enemy.", "icon_yefugenniya_zs1", "0", 4, 1, "1_{lv}*100", "Efgenia", "1_110021_20", 10, "1_100", "320030,320031,320032", "0", "0", "0", "0", "0", "单线制压", "由卡佳地区最大的军火制造商—“塞伦”制作的第一代重火力装备，该武装提供的初速度是同类武装的5倍，因此穿甲能力极强。\n仅仅动用这件武器，就能对一条线路上的敌军进行单方面的压制。", "叶芙根尼娅"},
[320031] = {320031, "Half\u{0020}City", "The\u{0020}first-generation\u{0020}heavy\u{0020}firepower\u{0020}equipment\u{0020}produced\u{0020}by\u{0020}\"Siren\",\u{0020}the\u{0020}largest\u{0020}arms\u{0020}manufacturer\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}This\u{0020}armament\u{0020}has\u{0020}an\u{0020}auxiliary\u{0020}locking\u{0020}system\u{0020}and\u{0020}each\u{0020}missile\u{0020}has\u{0020}an\u{0020}automatic\u{0020}tracking\u{0020}system.\u{0020}The\u{0020}missile\u{0020}is\u{0020}filled\u{0020}with\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}high-temperature\u{0020}fuel.\nEfgenia\u{0020}with\u{0020}full-on\u{0020}firepower\u{0020}can\u{0020}be\u{0020}equivalent\u{0020}to\u{0020}the\u{0020}firepower\u{0020}of\u{0020}half\u{0020}a\u{0020}city,\u{0020}but\u{0020}it\u{0020}will\u{0020}also\u{0020}destroy\u{0020}half\u{0020}a\u{0020}city.", "icon_yefugenniya_zs2", "0", 4, 2, "3_{lv}*100", "Efgenia", "1_110021_20", 10, "3_100", "320030,320031,320032", "0", "0", "0", "0", "0", "半城", "由卡佳地区最大的军火制造商—“塞伦”制作的第一代重火力装备，该武装拥有辅助锁定系统且每颗导弹均拥有自动追踪系统，导弹内装有大量高温燃料。\n火力全开的叶芙根尼娅能抵得上半座城区的火力，但同时，也会摧毁半座城区。", "叶芙根尼娅"},
[320032] = {320032, "Dragon\u{0020}Fang", "The\u{0020}mechanical\u{0020}exoskeleton\u{0020}made\u{0020}by\u{0020}\"Siren\",\u{0020}the\u{0020}largest\u{0020}arms\u{0020}manufacturer\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region,\u{0020}to\u{0020}reduce\u{0020}the\u{0020}aiming\u{0020}deviation\u{0020}caused\u{0020}by\u{0020}the\u{0020}recoil\u{0020}for\u{0020}the\u{0020}user.\u{0020}Each\u{0020}mechanical\u{0020}foot\u{0020}is\u{0020}equipped\u{0020}with\u{0020}two\u{0020}turbine\u{0020}nozzles\u{0020}and\u{0020}four\u{0020}steel\u{0020}needles\u{0020}for\u{0020}supporting.\u{0020}It\u{0020}provides\u{0020}not\u{0020}only\u{0020}mobility\u{0020}for\u{0020}drivers\u{0020}wearing\u{0020}heavy\u{0020}armor\u{0020}but\u{0020}has\u{0020}a\u{0020}shock\u{0020}absorption\u{0020}system.\nIn\u{0020}the\u{0020}design\u{0020}of\u{0020}Dragon\u{0020}Fang,\u{0020}Efgenia\u{0020}proposed\u{0020}the\u{0020}function\u{0020}of\u{0020}\"immobility\".\u{0020}Once\u{0020}this\u{0020}function\u{0020}is\u{0020}activated,\u{0020}it\u{0020}means\u{0020}that\u{0020}Efgenia\u{0020}does\u{0020}not\u{0020}intend\u{0020}to\u{0020}retreat\u{0020}anymore.\u{0020}She\u{0020}will\u{0020}die\u{0020}on\u{0020}this\u{0020}battlefield.\u{0020}This\u{0020}is\u{0020}the\u{0020}ending\u{0020}she\u{0020}has\u{0020}chosen\u{0020}for\u{0020}herself.", "icon_yefugenniya_zs3", "0", 4, 3, "3_{lv}*100", "Efgenia", "1_110021_20", 10, "3_100", "320030,320031,320032", "0", "0", "0", "0", "0", "龙牙", "由卡佳地区最大的军火制造商—“塞伦”为减少使用者因后坐力而造成打击偏差而制作的机械外骨骼，该装备每只机械足均装有2个涡轮喷口、4根稳定用的钢针，不仅能为穿着重型装甲的驾驶员提供移动能力还兼备了减震系统。\n在龙牙的设计中，叶芙根尼娅提出希望可以有“不动”的功能，一旦动用这个能力，就意味着叶芙根尼娅不打算再继续撤退了，她将死在这处战场，这是她为自己选定的结局。", "叶芙根尼娅"},
[320040] = {320040, "Bow\u{0020}That\u{0020}Breaks\u{0020}the\u{0020}Dark\u{0020}Curtain", "The\u{0020}divine\u{0020}bow\u{0020}once\u{0020}enshrined\u{0020}in\u{0020}the\u{0020}Shingyou\u{0020}Shrine.\u{0020}After\u{0020}slaying\u{0020}sin\u{0020}and\u{0020}absorbing\u{0020}the\u{0020}Transformation\u{0020}Core,\u{0020}it\u{0020}has\u{0020}obtained\u{0020}the\u{0020}ability\u{0020}to\u{0020}instantly\u{0020}block\u{0020}the\u{0020}actions\u{0020}of\u{0020}a\u{0020}large\u{0020}area\u{0020}of\u{0020}enemies.\u{0020}Its\u{0020}shape\u{0020}will\u{0020}change\u{0020}with\u{0020}the\u{0020}user.\nWhen\u{0020}I\u{0020}am\u{0020}qualified\u{0020}to\u{0020}pick\u{0020}up\u{0020}the\u{0020}divine\u{0020}bow,\u{0020}the\u{0020}darkness\u{0020}around\u{0020}me\u{0020}dissipates.\u{0020}I\u{0020}can\u{0020}finally\u{0020}walk\u{0020}out\u{0020}of\u{0020}the\u{0020}shrine\u{0020}and\u{0020}become\u{0020}a\u{0020}shrine\u{0020}maiden.", "icon_huayu_zs1", "0", 2, 1, "3_{lv}*100", "Hanakotoba", "1_110021_5", 10, "3_100", "320040,320041,320042", "0", "0", "0", "0", "0", "破却暗幕之弓", "曾经供奉在心经神社的神弓，在斩杀原罪并吸收了幻化核心后，获得了能够瞬间封锁大面积的敌人行动的能力，形状会随着使用者的改变而改变。\n当我有资格拿起神弓时，身边的黑暗消散了，我终于能走出神社，成为一名巫女。", "花语"},
[320041] = {320041, "Bow\u{0020}Guard", "The\u{0020}hand\u{0020}armor\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}It\u{0020}provides\u{0020}not\u{0020}only\u{0020}good\u{0020}protection\u{0020}but\u{0020}also\u{0020}improves\u{0020}the\u{0020}physical\u{0020}strength\u{0020}of\u{0020}the\u{0020}user.\nIf\u{0020}I\u{0020}pull\u{0020}the\u{0020}bow\u{0020}without\u{0020}protection,\u{0020}my\u{0020}fingers\u{0020}and\u{0020}even\u{0020}my\u{0020}entire\u{0020}arm\u{0020}will\u{0020}be\u{0020}seriously\u{0020}injured.\u{0020}But\u{0020}with\u{0020}the\u{0020}arm\u{0020}guard,\u{0020}I\u{0020}can\u{0020}fight\u{0020}for\u{0020}longer.", "icon_huayu_zs2", "0", 2, 2, "1_{lv}*100", "Hanakotoba", "1_110021_5", 10, "1_100", "320040,320041,320042", "0", "0", "0", "0", "0", "弓护", "艾吉斯设计并制造的手部装甲，不光可以提供不错的防护还能提升使用者的身体机能。\n直接拨动神弓的话，我的手指，乃至整个手臂会受到重伤，但是有了护臂我就可以长时间地战斗了。", "花语"},
[320042] = {320042, "Divine\u{0020}Shrine\u{0020}Maiden", "The\u{0020}speed-type\u{0020}thruster\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}It\u{0020}is\u{0020}equipped\u{0020}with\u{0020}a\u{0020}device\u{0020}that\u{0020}can\u{0020}consume\u{0020}the\u{0020}energy\u{0020}of\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}to\u{0020}provide\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}kinetic\u{0020}energy\u{0020}for\u{0020}the\u{0020}body.\nI\u{0020}can't\u{0020}stand\u{0020}still\u{0020}on\u{0020}the\u{0020}battlefield.\u{0020}I\u{0020}am\u{0020}the\u{0020}shrine\u{0020}maiden\u{0020}of\u{0020}God\u{0020}and\u{0020}I\u{0020}will\u{0020}bring\u{0020}the\u{0020}final\u{0020}gospel\u{0020}to\u{0020}this\u{0020}tragic\u{0020}world.", "icon_huayu_zs3", "0", 2, 3, "1_{lv}*100", "Hanakotoba", "1_110021_5", 10, "1_100", "320040,320041,320042", "0", "0", "0", "0", "0", "神之巫女", "艾吉斯设计并制造的速度型推进器，拥有可以消耗幻化核心的能量在短期内为机体提升大量动能的装备。\n在战场上可不能停滞不前，我是神之巫女，要为这悲惨的世界带来最后的福音。", "花语"},
[320050] = {320050, "Dawn\u{0020}of\u{0020}Revenge", "This\u{0020}equipment\u{0020}is\u{0020}the\u{0020}equipment\u{0020}with\u{0020}the\u{0020}highest\u{0020}individual\u{0020}firepower\u{0020}equipped\u{0020}for\u{0020}soldiers\u{0020}by\u{0020}the\u{0020}arms\u{0020}company\u{0020}\"Siren\".\u{0020}It\u{0020}has\u{0020}a\u{0020}magazine\u{0020}capacity\u{0020}of\u{0020}140\u{0020}rounds\u{0020}and\u{0020}is\u{0020}double-barreled.\n\"I'm\u{0020}not\u{0020}a\u{0020}fan\u{0020}of\u{0020}sin.\u{0020}They\u{0020}all\u{0020}have\u{0020}to\u{0020}die...\u{0020}Revenge?\u{0020}Maybe.\"", "icon_yiliya_zs1", "0", 4, 1, "1_{lv}*100", "Iliya", "1_110021_20", 10, "1_100", "320050,320051,320052", "0", "0", "0", "0", "0", "救☆济☆执☆行", "此装备是军火公司“塞伦”为战士配备的单兵火力最高的装备，拥有140发的载弹量且为双管火力。\n“我不喜欢原罪，得请他们通通死掉才行……复仇？也许吧。”", "伊莉雅"},
[320051] = {320051, "Phantom\u{0020}Steel", "The\u{0020}mechanical\u{0020}prosthetic\u{0020}limb\u{0020}developed\u{0020}by\u{0020}the\u{0020}arms\u{0020}company\u{0020}\"Siren\"\u{0020}for\u{0020}soldiers\u{0020}with\u{0020}limb\u{0020}injuries.\u{0020}In\u{0020}addition\u{0020}to\u{0020}the\u{0020}functions\u{0020}of\u{0020}a\u{0020}human\u{0020}limp,\u{0020}it\u{0020}can\u{0020}also\u{0020}be\u{0020}equipped\u{0020}with\u{0020}some\u{0020}weapons\u{0020}according\u{0020}to\u{0020}needs.\u{0020}This\u{0020}can\u{0020}be\u{0020}an\u{0020}ace\u{0020}up\u{0020}every\u{0020}soldier's\u{0020}sleeve.\nThis\u{0020}is\u{0020}the\u{0020}price\u{0020}I\u{0020}pay\u{0020}for\u{0020}exchanging\u{0020}for\u{0020}strength\u{0020}and\u{0020}the\u{0020}only\u{0020}hope\u{0020}I\u{0020}can\u{0020}grasp.", "icon_yiliya_zs2", "0", 4, 2, "1_{lv}*100", "Iliya", "1_110021_20", 10, "1_100", "320050,320051,320052", "0", "0", "0", "0", "0", "复仇的曙光", "由军火公司“塞伦”为肢体受伤的士兵研制的机械义肢，该义肢除了具备人体常规的机能外，根据个人需要还可以装载少量的武器，这可以成为每个战士的杀手锏。\n这是我换取力量的代价，也是我唯一能抓住的希望。", "伊莉雅"},
[320052] = {320052, "Relief\u{0020}Food", "The\u{0020}structure\u{0020}of\u{0020}this\u{0020}ammunition\u{0020}chain\u{0020}box\u{0020}is\u{0020}an\u{0020}arc\u{0020}structure.\u{0020}It\u{0020}can\u{0020}load\u{0020}the\u{0020}most\u{0020}ammunition\u{0020}in\u{0020}the\u{0020}smallest\u{0020}space,\u{0020}and\u{0020}the\u{0020}weight\u{0020}of\u{0020}the\u{0020}entire\u{0020}equipment\u{0020}is\u{0020}relatively\u{0020}low,\u{0020}but\u{0020}there\u{0020}is\u{0020}a\u{0020}certain\u{0020}risk\u{0020}of\u{0020}jamming,\u{0020}especially\u{0020}when\u{0020}used\u{0020}in\u{0020}harsh\u{0020}environments.\n\"These\u{0020}are\u{0020}small\u{0020}snacks\u{0020}to\u{0020}be\u{0020}fed\u{0020}to\u{0020}sin.\"", "icon_yiliya_zs3", "0", 4, 3, "1_{lv}*100", "Iliya", "1_110021_20", 10, "1_100", "320050,320051,320052", "0", "0", "0", "0", "0", "救济粮", "该弹链箱的结构为弧形结构，可以在用最小的空间装载最多的弹药，且整个装备的负重较低，但有一定概率的卡弹风险，尤其在自然环境恶劣的情况下使用。\n“这些是要拿去喂原罪的小零食。”", "伊莉雅"},
[320070] = {320070, "Lofty\u{0020}Ambition\u{0020}and\u{0020}Far-reaching\u{0020}Steps", "The\u{0020}exoskeleton\u{0020}developed\u{0020}by\u{0020}the\u{0020}special\u{0020}research\u{0020}institute\u{0020}of\u{0020}the\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}Heavy\u{0020}type\u{0020}drivers.\u{0020}This\u{0020}armor\u{0020}can\u{0020}convert\u{0020}the\u{0020}energy\u{0020}provided\u{0020}by\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}into\u{0020}high-temperature\u{0020}laser\u{0020}and\u{0020}spray\u{0020}it\u{0020}out,\u{0020}with\u{0020}the\u{0020}ability\u{0020}to\u{0020}melt\u{0020}everything.\nA\u{0020}rare\u{0020}exoskeleton\u{0020}equipment.\u{0020}The\u{0020}difficulty\u{0020}of\u{0020}use\u{0020}is\u{0020}very\u{0020}high.\u{0020}If\u{0020}it\u{0020}doesn't\u{0020}feel\u{0020}natural\u{0020}to\u{0020}use,\u{0020}it\u{0020}is\u{0020}not\u{0020}recommended\u{0020}to\u{0020}be\u{0020}put\u{0020}into\u{0020}the\u{0020}combat.", "icon_huameng_zs1", "0", 2, 1, "3_{lv}*100", "Huameng", "1_110021_5", 10, "3_100", "320070,320071,320072", "0", "0", "0", "0", "0", "高掌远跖萱花臂", "由九州总部特研科为火力型驾驶员研发的外骨骼，该装甲可以将幻化核心提供的能量转化为高温激光喷射出去，拥有融化一切的能力。\n少见的外骨骼装备，使用难度很高，如果不能把它运用得如臂指使，不建议投入真正的战场。", "华梦"},
[320071] = {320071, "Blooming\u{0020}for\u{0020}the\u{0020}Gods", "A\u{0020}communication\u{0020}device\u{0020}developed\u{0020}by\u{0020}the\u{0020}special\u{0020}research\u{0020}institute\u{0020}of\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}Based\u{0020}on\u{0020}the\u{0020}first\u{0020}generation,\u{0020}an\u{0020}anti-interference\u{0020}system\u{0020}is\u{0020}integrated.\nAs\u{0020}a\u{0020}[martial\u{0020}idiot],\u{0020}Huameng\u{0020}is\u{0020}not\u{0020}pure\u{0020}enough...\u{0020}Because\u{0020}at\u{0020}least\u{0020}she\u{0020}can\u{0020}still\u{0020}communicate\u{0020}with\u{0020}her\u{0020}teammates\u{0020}and\u{0020}follow\u{0020}orders.", "icon_huameng_zs2", "0", 2, 2, "3_{lv}*100", "Huameng", "1_110021_5", 10, "3_100", "320070,320071,320072", "0", "0", "0", "0", "0", "开而为两祂心通", "由九州总部特研科研制的一种通信装置，在一代的基础上增加了防干扰系统。\n身为【武痴】的华恋，不够纯粹……因为她至少还能与队友沟通，听从安排。", "华梦"},
[320072] = {320072, "Phoenix\u{0020}Passing\u{0020}Flowers", "The\u{0020}exoskeleton\u{0020}developed\u{0020}by\u{0020}the\u{0020}special\u{0020}research\u{0020}institute\u{0020}of\u{0020}the\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}drivers.\u{0020}This\u{0020}armor\u{0020}is\u{0020}made\u{0020}of\u{0020}high-density\u{0020}titanium\u{0020}alloy\u{0020}and\u{0020}provides\u{0020}users\u{0020}with\u{0020}sufficient\u{0020}protection.\nHuameng's\u{0020}affirmation.jpg", "icon_huameng_zs3", "0", 2, 3, "1_{lv}*100", "Huameng", "1_110021_5", 10, "1_100", "320070,320071,320072", "0", "0", "0", "0", "0", "凤凰穿花奇巧足", "由九州总部特研科为驾驶员研发的外骨骼，该装甲采用高密度的钛合金打造而成，可以为使用者提供足够的防护能力。\n华梦的肯定.jpg", "华梦"},
[320080] = {320080, "Something\u{0020}That\u{0020}Brings\u{0020}Strength", "This\u{0020}liquid\u{0020}is\u{0020}mainly\u{0020}a\u{0020}kind\u{0020}of\u{0020}fuel\u{0020}processed\u{0020}from\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}as\u{0020}the\u{0020}material.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}its\u{0020}efficiency\u{0020}is\u{0020}higher\u{0020}than\u{0020}that\u{0020}of\u{0020}solids.\nMomoka\u{0020}has\u{0020}always\u{0020}believed\u{0020}that\u{0020}this\u{0020}is\u{0020}a\u{0020}technology\u{0020}that\u{0020}can\u{0020}change\u{0020}the\u{0020}world.", "icon_bailimomo_zs1", "0", 3, 1, "1_{lv}*100", "Bairi\u{0020}Momo", "1_110021_10", 10, "1_100", "320080,320081,320082", "0", "0", "0", "0", "0", "带来力量的东西", "该液体主要是以幻化核心为材料通过加工而成的一种燃料，据说使用效率比起固体更高。\n默默一直坚信这个是足以改变世界的技术。", "百里默默"},
[320081] = {320081, "The\u{0020}Cutest\u{0020}in\u{0020}the\u{0020}World", "This\u{0020}thing\u{0020}is\u{0020}woven\u{0020}by\u{0020}Momo\u{0020}using\u{0020}mysterious\u{0020}materials.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}first,\u{0020}wearing\u{0020}it\u{0020}on\u{0020}the\u{0020}head\u{0020}makes\u{0020}people\u{0020}feel\u{0020}very\u{0020}refreshing.\u{0020}But\u{0020}colleagues\u{0020}at\u{0020}AEGIS\u{0020}always\u{0020}feel\u{0020}that\u{0020}this\u{0020}hairband\u{0020}is\u{0020}like\u{0020}women's\u{0020}clothing.\nSecond,\u{0020}it\u{0020}can\u{0020}detect\u{0020}the\u{0020}cuteness\u{0020}of\u{0020}everything\u{0020}around\u{0020}and\u{0020}convert\u{0020}it\u{0020}into\u{0020}specific\u{0020}values.", "icon_bailimomo_zs2", "0", 3, 2, "1_{lv}*100", "Bairi\u{0020}Momo", "1_110021_10", 10, "1_100", "320080,320081,320082", "0", "0", "0", "0", "0", "天下第一可爱", "这个东西是默默使用神秘的材料编制而成，据说其一，带在头上让人感觉非常清爽，但是艾吉斯的同事总觉得这个发箍像是女性的衣物。\n据说其二，能侦测身边一切事物的可爱力，并转化为具体的数值。", "百里默默"},
[320082] = {320082, "Cuteness\u{0020}Suppressor", "Because\u{0020}Momo's\u{0020}power\u{0020}is\u{0020}too\u{0020}strong,\u{0020}the\u{0020}function\u{0020}of\u{0020}this\u{0020}equipment\u{0020}is\u{0020}to\u{0020}limit\u{0020}Momo's\u{0020}synchronous\u{0020}data\u{0020}with\u{0020}the\u{0020}mech\u{0020}to\u{0020}prevent\u{0020}uncontrollable\u{0020}problems.\nIt\u{0020}is\u{0020}said\u{0020}that\u{0020}first,\u{0020}once\u{0020}turned\u{0020}off,\u{0020}teammates\u{0020}will\u{0020}not\u{0020}be\u{0020}able\u{0020}to\u{0020}bear\u{0020}the\u{0020}cuteness\u{0020}of\u{0020}Bairi\u{0020}Momo\u{0020}and\u{0020}interfere\u{0020}with\u{0020}everyone's\u{0020}combat.", "icon_bailimomo_zs3", "0", 3, 3, "1_{lv}*100", "Bairi\u{0020}Momo", "1_110021_10", 10, "1_100", "320080,320081,320082", "0", "0", "0", "0", "0", "可爱力抑制器", "由于默默的力量实在过于强大，该装备的作用是限制默默与机甲的同频数据，以防止出现难以控制的灾难。\n据说其一，一旦解除封印，队友就会受不了百里默默的可爱，干扰大家的作战。", "百里默默"},
[320090] = {320090, "Snow\u{0020}Vortex\u{0020}Fairy", "The\u{0020}light\u{0020}laser\u{0020}cannon\u{0020}developed\u{0020}by\u{0020}\"Siren\",\u{0020}the\u{0020}largest\u{0020}arms\u{0020}manufacturer\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region,\u{0020}according\u{0020}to\u{0020}the\u{0020}commission\u{0020}of\u{0020}the\u{0020}air\u{0020}squadron.\u{0020}It\u{0020}stays\u{0020}unaffected\u{0020}even\u{0020}at\u{0020}a\u{0020}high\u{0020}temperature\u{0020}of\u{0020}3,000\u{0020}degrees\u{0020}celsius.\u{0020}Only\u{0020}a\u{0020}small\u{0020}amount\u{0020}of\u{0020}nuclear\u{0020}energy\u{0020}is\u{0020}needed\u{0020}to\u{0020}launch.\nThere\u{0020}are\u{0020}snow\u{0020}fairies\u{0020}appearing\u{0020}on\u{0020}snowy\u{0020}days.\u{0020}People\u{0020}who\u{0020}have\u{0020}met\u{0020}snow\u{0020}fairies\u{0020}will\u{0020}turn\u{0020}into\u{0020}popsicles.", "icon_maliya_zs1", "0", 3, 1, "3_{lv}*100", "Maria", "1_110021_10", 10, "3_100", "320090,320091,320092", "0", "0", "0", "0", "0", "雪涡妖精", "由卡佳地区最大的军火制造商—“塞伦”根据空勤团委托研制的轻型镭射光炮，据说在3000度的高温下均不会受到影响，发射能量只需要少量的核能即可，非常经济。\n大雪天有雪妖精出没，遇见过雪妖精的人都会变成冰棍。", "玛利亚"},
[320091] = {320091, "Commemorative\u{0020}Cap", "The\u{0020}military\u{0020}cap\u{0020}uniformly\u{0020}produced\u{0020}by\u{0020}the\u{0020}military\u{0020}supply\u{0020}department\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}the\u{0020}material\u{0020}is\u{0020}mixed\u{0020}with\u{0020}irritating\u{0020}spices.\u{0020}Drivers\u{0020}wearing\u{0020}it\u{0020}feel\u{0020}very\u{0020}energetic.\u{0020}There\u{0020}seems\u{0020}to\u{0020}be\u{0020}nothing\u{0020}special\u{0020}besides\u{0020}that.\nA\u{0020}hat.\u{0020}A\u{0020}hat\u{0020}represents\u{0020}a\u{0020}kind\u{0020}of\u{0020}belief\u{0020}and\u{0020}spirit.\u{0020}I\u{0020}can't\u{0020}tell\u{0020}exactly\u{0020}what\u{0020}it\u{0020}is.", "icon_maliya_zs2", "0", 3, 2, "1_{lv}*100", "Maria", "1_110021_10", 10, "1_100", "320090,320091,320092", "0", "0", "0", "0", "0", "有纪念意义的帽", "由卡佳地区军需处统一制作的军帽，据说材料混有刺激性香料，佩戴过的驾驶员都觉得很有精神，除此之外好像没什么特别的。\n帽子，帽子代表着一种信念，精神。具体是什么我也说不上来。", "玛利亚"},
[320092] = {320092, "Non-slip\u{0020}Shoes\u{0020}·\u{0020}High\u{0020}Heels?", "The\u{0020}mechanical\u{0020}high\u{0020}heels\u{0020}uniformly\u{0020}produced\u{0020}by\u{0020}the\u{0020}military\u{0020}supply\u{0020}department\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}Mainly\u{0020}developed\u{0020}for\u{0020}drivers\u{0020}who\u{0020}fight\u{0020}in\u{0020}polar\u{0020}regions.\u{0020}In\u{0020}addition\u{0020}to\u{0020}the\u{0020}cold-proof\u{0020}function,\u{0020}they\u{0020}also\u{0020}have\u{0020}an\u{0020}anti-slip\u{0020}function.\nNothing\u{0020}obvious\u{0020}about\u{0020}the\u{0020}cold-proof\u{0020}function\u{0020}and\u{0020}anti-slip\u{0020}function.\u{0020}But\u{0020}quite\u{0020}uncomfortable\u{0020}to\u{0020}wear.", "icon_maliya_zs3", "0", 3, 3, "1_{lv}*100", "Maria", "1_110021_10", 10, "1_100", "320090,320091,320092", "0", "0", "0", "0", "0", "防滑鞋·高跟？", "由卡佳地区军需处统一制作的机械高跟鞋，主要针对常年在极地作战的驾驶员研制的，除了有御寒作用外，还拥有防滑功能。\n看不出有御寒作用和防滑作用，还穿着特别难受的鞋子。", "玛利亚"},
[320100] = {320100, "Hidden\u{0020}Fire\u{0020}Remains\u{0020}Burning", "The\u{0020}giant\u{0020}incendiary\u{0020}cannon\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters.\u{0020}It\u{0020}is\u{0020}made\u{0020}of\u{0020}high-strength\u{0020}metal\u{0020}and\u{0020}is\u{0020}specially\u{0020}designed\u{0020}for\u{0020}troops\u{0020}performing\u{0020}covert\u{0020}operations.\u{0020}The\u{0020}design\u{0020}was\u{0020}intent\u{0020}to\u{0020}ensure\u{0020}annihilation\u{0020}power\u{0020}on\u{0020}the\u{0020}basis\u{0020}of\u{0020}supporting\u{0020}covert\u{0020}operations.\u{0020}Features\u{0020}special\u{0020}incendiary\u{0020}bombs.\u{0020}The\u{0020}high\u{0020}temperature\u{0020}can\u{0020}melt\u{0020}almost\u{0020}all\u{0020}materials.\n\"In\u{0020}three\u{0020}minutes,\u{0020}I\u{0020}want\u{0020}to\u{0020}know\u{0020}all\u{0020}the\u{0020}information\u{0020}about\u{0020}the\u{0020}driver\u{0020}Meika.\"", "icon_minghuo_zs1", "0", 2, 1, "3_{lv}*100", "Meika", "1_110021_5", 10, "3_100", "320100,320101,320102", "0", "0", "0", "0", "0", "隐火存燎", "由艾吉斯总部设计并制造的巨型燃烧炮，采用高强度金属制作，专为执行隐秘行动的部队所设计。设计初衷便是在支持隐秘行动的基础上保证歼灭力，装填特质燃烧弹，产生的高温能将几乎所有材质熔化。\n“三分钟，我要知道驾驶员冥火的所有资料。”", "冥火"},
[320101] = {320101, "Unknown\u{0020}to\u{0020}Anyone", "The\u{0020}special\u{0020}metal\u{0020}leg\u{0020}armor\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters.\u{0020}Compared\u{0020}with\u{0020}its\u{0020}defensive\u{0020}performance,\u{0020}it\u{0020}focuses\u{0020}more\u{0020}on\u{0020}modification\u{0020}potential.\u{0020}In\u{0020}order\u{0020}to\u{0020}meet\u{0020}the\u{0020}needs\u{0020}of\u{0020}customization\u{0020}of\u{0020}drivers,\u{0020}interfaces\u{0020}are\u{0020}configured\u{0020}on\u{0020}the\u{0020}armor\u{0020}to\u{0020}configure\u{0020}external\u{0020}equipment.\nOnly\u{0020}people\u{0020}from\u{0020}Ninja\u{0020}Group\u{0020}can\u{0020}recognize\u{0020}a\u{0020}fellow's\u{0020}disguises...\u{0020}Now\u{0020}there\u{0020}is\u{0020}also\u{0020}a\u{0020}strange\u{0020}navigator.", "icon_minghuo_zs2", "0", 2, 2, "3_{lv}*100", "Meika", "1_110021_5", 10, "3_100", "320100,320101,320102", "0", "0", "0", "0", "0", "无人知晓", "由艾吉斯总部设计并制造的特制金属腿甲，相较于防御性能，更着重于改造潜力，为满足驾驶员个性定制的需求在装甲上配置了接口用以配置外部装备。\n只有忍心社的人才能互相辨认出自己人的伪装……现在还多了一位奇怪的领航。", "冥火"},
[320102] = {320102, "Another\u{0020}Me", "The\u{0020}mental\u{0020}stability\u{0020}device\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters.\u{0020}It\u{0020}is\u{0020}composed\u{0020}of\u{0020}induction\u{0020}crystals.\u{0020}The\u{0020}main\u{0020}function\u{0020}is\u{0020}to\u{0020}stabilize\u{0020}the\u{0020}spirit\u{0020}of\u{0020}the\u{0020}wearer\u{0020}and\u{0020}prevent\u{0020}the\u{0020}wearer\u{0020}from\u{0020}going\u{0020}berserk\u{0020}due\u{0020}to\u{0020}mental\u{0020}breakdown.\nCan\u{0020}someone\u{0020}accept\u{0020}us\u{0020}who\u{0020}have\u{0020}two\u{0020}souls\u{0020}in\u{0020}one\u{0020}body?", "icon_minghuo_zs3", "0", 2, 3, "3_{lv}*100", "Meika", "1_110021_5", 10, "3_100", "320100,320101,320102", "0", "0", "0", "0", "0", "另一个我", "由艾吉斯总部设计并制造的精神稳定装置，由感应水晶构成，最大作用是稳定装备者的精神，防止装备者因精神崩坏引起暴走。\n有人能接纳一体双魂的我们吗？", "冥火"},
[320110] = {320110, "Returning\u{0020}from\u{0020}the\u{0020}Sea\u{0020}of\u{0020}Karma", "The\u{0020}whale-shaped\u{0020}autonomous\u{0020}mech\u{0020}made\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Naval\u{0020}Weapon\u{0020}Research\u{0020}Department.\u{0020}A\u{0020}large\u{0020}amount\u{0020}of\u{0020}Nimbus\u{0020}energy\u{0020}is\u{0020}loaded\u{0020}in\u{0020}its\u{0020}huge\u{0020}body.\u{0020}It\u{0020}can\u{0020}be\u{0020}launched\u{0020}by\u{0020}energy\u{0020}storage\u{0020}through\u{0020}the\u{0020}muzzle,\u{0020}or\u{0020}ejected\u{0020}from\u{0020}the\u{0020}tail\u{0020}when\u{0020}necessary\u{0020}to\u{0020}achieve\u{0020}a\u{0020}high-mobility\u{0020}effect.\nSamghrma\u{0020}herself\u{0020}prefers\u{0020}to\u{0020}call\u{0020}it\u{0020}\"Xiaobai\",\u{0020}which\u{0020}seems\u{0020}to\u{0020}originate\u{0020}from\u{0020}a\u{0020}sperm\u{0020}whale\u{0020}she\u{0020}once\u{0020}rescued.", "icon_jialanjian_zs1", "0", 4, 1, "1_{lv}*100", "Samghrma", "1_110021_20", 10, "1_100", "320110,320111,320112", "0", "0", "0", "0", "0", "0", "0", "0"},
[320111] = {320111, "Calm\u{0020}Heart\u{0020}like\u{0020}Still\u{0020}Water", "The\u{0020}underwater\u{0020}specialized\u{0020}combat\u{0020}suit\u{0020}made\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Naval\u{0020}Weapon\u{0020}Research\u{0020}Department.\u{0020}It\u{0020}is\u{0020}made\u{0020}by\u{0020}combining\u{0020}cutting-edge\u{0020}nanotech\u{0020}with\u{0020}new\u{0020}materials.\u{0020}The\u{0020}friction\u{0020}between\u{0020}the\u{0020}surface\u{0020}and\u{0020}the\u{0020}water\u{0020}body\u{0020}is\u{0020}almost\u{0020}zero.\u{0020}Even\u{0020}at\u{0020}full\u{0020}speed,\u{0020}it\u{0020}will\u{0020}not\u{0020}disturb\u{0020}the\u{0020}water\u{0020}flow.\n\"Like\u{0020}a\u{0020}mirror\u{0020}reflecting\u{0020}still\u{0020}water,\u{0020}one\u{0020}can\u{0020}purify\u{0020}the\u{0020}heart.\"", "icon_jialanjian_zs2", "0", 4, 2, "3_{lv}*100", "Samghrma", "1_110021_20", 10, "3_100", "320110,320111,320112", "0", "0", "0", "0", "0", "0", "0", "0"},
[320112] = {320112, "Contemplating\u{0020}the\u{0020}Dharma\u{0020}Rain", "The\u{0020}communication\u{0020}antenna\u{0020}made\u{0020}by\u{0020}the\u{0020}Kyushu\u{0020}Naval\u{0020}Weapon\u{0020}Research\u{0020}Department.\u{0020}It\u{0020}can\u{0020}receive\u{0020}full-spectrum\u{0020}bands\u{0020}at\u{0020}all\u{0020}times.\u{0020}No\u{0020}matter\u{0020}whether\u{0020}it\u{0020}comes\u{0020}from\u{0020}the\u{0020}deep\u{0020}sea\u{0020}or\u{0020}outer\u{0020}space,\u{0020}no\u{0020}matter\u{0020}how\u{0020}weak\u{0020}the\u{0020}signal\u{0020}is,\u{0020}this\u{0020}equipment\u{0020}can\u{0020}identify\u{0020}them\u{0020}all.\n\"The\u{0020}heavenly\u{0020}sound\u{0020}is\u{0020}like\u{0020}rain,\u{0020}falling\u{0020}back\u{0020}into\u{0020}the\u{0020}vast\u{0020}ocean.\"", "icon_jialanjian_zs3", "0", 4, 3, "1_{lv}*100", "Samghrma", "1_110021_20", 10, "1_100", "320110,320111,320112", "0", "0", "0", "0", "0", "0", "0", "0"},
[320120] = {320120, "Ready\u{0020}for\u{0020}Hunting", "This\u{0020}equipment\u{0020}is\u{0020}an\u{0020}armament\u{0020}designed\u{0020}by\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}for\u{0020}large-scale\u{0020}strikes\u{0020}against\u{0020}aggregated\u{0020}sin.\u{0020}Obtain\u{0020}energy\u{0020}from\u{0020}the\u{0020}Transformation\u{0020}Core.\u{0020}Embedded\u{0020}with\u{0020}a\u{0020}cooling\u{0020}system.\u{0020}Supports\u{0020}various\u{0020}ammunitions\u{0020}according\u{0020}to\u{0020}the\u{0020}battle\u{0020}situation.\n\"Listen\u{0020}to\u{0020}me.\u{0020}If\u{0020}you\u{0020}are\u{0020}targeted,\u{0020}you'd\u{0020}better\u{0020}pray\u{0020}that\u{0020}you\u{0020}have\u{0020}never\u{0020}made\u{0020}any\u{0020}mistakes.\"", "icon_zhuliya_zs1", "0", 2, 1, "3_{lv}*100", "Julia", "1_110021_5", 10, "3_100", "320120,320121,320122", "0", "0", "0", "0", "0", "猎食就绪", "该装备是由多瑙支部为聚集着的原罪进行大规模打击而设计的武装。从幻化核心获取能源，内部配置冷却系统，支持各类弹药装填，发射弹药种类可以根据战局进行选择。\n“听我说，假如你被盯上，你最好祈祷自己从未犯下什么错误。”", "茱莉亚"},
[320121] = {320121, "Sadist", "This\u{0020}equipment\u{0020}is\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}and\u{0020}is\u{0020}equipped\u{0020}to\u{0020}very\u{0020}few\u{0020}special\u{0020}drivers.\u{0020}Minimize\u{0020}the\u{0020}armor\u{0020}coverage\u{0020}in\u{0020}exchange\u{0020}for\u{0020}mobility.\u{0020}Also,\u{0020}it\u{0020}reflects\u{0020}the\u{0020}mental\u{0020}state\u{0020}of\u{0020}the\u{0020}driver\u{0020}to\u{0020}the\u{0020}whole\u{0020}body\u{0020}equipment.\u{0020}The\u{0020}driver\u{0020}being\u{0020}excited\u{0020}can\u{0020}greatly\u{0020}improve\u{0020}the\u{0020}performance\u{0020}of\u{0020}the\u{0020}mech.\nGive\u{0020}me\u{0020}a\u{0020}handle.\u{0020}From\u{0020}now\u{0020}on,\u{0020}life\u{0020}will\u{0020}bid\u{0020}farewell\u{0020}to\u{0020}you\u{0020}and\u{0020}say\u{0020}goodbye\u{0020}to\u{0020}the\u{0020}light.", "icon_zhuliya_zs2", "0", 2, 2, "3_{lv}*100", "Julia", "1_110021_5", 10, "3_100", "320120,320121,320122", "0", "0", "0", "0", "0", "施虐狂", "该装备是由多瑙支部制造，配置于极少数特殊的驾驶员。尽可能减少装甲覆盖面以换取机动性，同时能够将驾驶员的精神状态反映至全身装备。在驾驶员处于兴奋状态时能够大幅度提升机甲性能。\n给我一个把柄，从此以后，人的生活将与你诀别，与光明说再见吧。", "茱莉亚"},
[320122] = {320122, "Blooming\u{0020}Nature", "This\u{0020}equipment\u{0020}is\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}Danube\u{0020}Branch.\u{0020}It\u{0020}is\u{0020}designed\u{0020}with\u{0020}light\u{0020}metal.\u{0020}While\u{0020}ensuring\u{0020}communication\u{0020}functions,\u{0020}it\u{0020}searches\u{0020}and\u{0020}locates\u{0020}the\u{0020}positions\u{0020}of\u{0020}teammates.\u{0020}And\u{0020}it\u{0020}is\u{0020}equipped\u{0020}with\u{0020}a\u{0020}data\u{0020}analyser\u{0020}to\u{0020}assist\u{0020}the\u{0020}driver\u{0020}in\u{0020}processing\u{0020}information\u{0020}collected.\n\"This\u{0020}is\u{0020}my\u{0020}backyard.\u{0020}I\u{0020}am\u{0020}very\u{0020}sure.\u{0020}Fortunately,\u{0020}I\u{0020}became\u{0020}a\u{0020}driver.\u{0020}Being\u{0020}a\u{0020}driver\u{0020}is\u{0020}really\u{0020}fun.\"", "icon_zhuliya_zs3", "0", 2, 3, "1_{lv}*100", "Julia", "1_110021_5", 10, "1_100", "320120,320121,320122", "0", "0", "0", "0", "0", "盛放的天性", "该装备是由多瑙支部制造，采用轻金属设计，确保通信机能的同时能够进行周边队友的位置搜索及定位。并且附带数据分析机能，辅助驾驶员处理同时采集到的大量信息。\n这里简直就是我的后花园，我很确信。还好我成为了驾驶员，驾驶员果然有趣。", "茱莉亚"},
[320130] = {320130, "Heroes\u{0020}Who\u{0020}Die\u{0020}for\u{0020}a\u{0020}Cause", "The\u{0020}standard\u{0020}armament\u{0020}of\u{0020}the\u{0020}academy\u{0020}affiliated\u{0020}to\u{0020}the\u{0020}Sahara\u{0020}Branch.\u{0020}Made\u{0020}in\u{0020}Sahara.\u{0020}Although\u{0020}it\u{0020}is\u{0020}the\u{0020}standard\u{0020}armament\u{0020}equipped\u{0020}by\u{0020}the\u{0020}academy,\u{0020}its\u{0020}performance\u{0020}is\u{0020}sufficient\u{0020}to\u{0020}support\u{0020}most\u{0020}battle\u{0020}situations.\u{0020}It\u{0020}can\u{0020}also\u{0020}make\u{0020}a\u{0020}certain\u{0020}degree\u{0020}of\u{0020}response\u{0020}when\u{0020}facing\u{0020}a\u{0020}large-scale\u{0020}attack\u{0020}by\u{0020}sin.\n\"Devote\u{0020}one's\u{0020}life\u{0020}to\u{0020}achieve\u{0020}an\u{0020}ideal?\u{0020}I\u{0020}don't\u{0020}think\u{0020}there\u{0020}is\u{0020}any\u{0020}problem\u{0020}with\u{0020}this.\u{0020}But...\u{0020}If\u{0020}only\u{0020}they\u{0020}could\u{0020}all\u{0020}survive.\"", "icon_kalian_zs1", "0", 3, 1, "1_{lv}*100", "Karen", "1_110021_10", 10, "1_100", "320130,320131,320132", "0", "0", "0", "0", "0", "赴死的英雄", "萨哈拉支部所属学院的制式武装。萨哈拉本土制造，虽是学院配备的制式武装，但其性能足以支撑大部分战局。在面对大规模的原罪袭击时也能够做出一定程度的应对。\n“为了达成理想而献出生命？我并不觉得这有什么问题，但是……假如她们都能活下来，该多好啊。”", "卡莲"},
[320131] = {320131, "Med\u{0020}School\u{0020}Can't\u{0020}Save\u{0020}Anyone", "The\u{0020}standard\u{0020}leg\u{0020}armor\u{0020}of\u{0020}the\u{0020}academy\u{0020}affiliated\u{0020}to\u{0020}the\u{0020}Sahara\u{0020}Branch.\u{0020}Made\u{0020}of\u{0020}lighter\u{0020}materials.\u{0020}Suitable\u{0020}for\u{0020}units\u{0020}with\u{0020}high\u{0020}mobility.\u{0020}The\u{0020}main\u{0020}feature\u{0020}is\u{0020}that\u{0020}it\u{0020}provides\u{0020}a\u{0020}configuration\u{0020}slot\u{0020}for\u{0020}portable\u{0020}grenades\u{0020}on\u{0020}the\u{0020}side,\u{0020}which\u{0020}expands\u{0020}the\u{0020}strike\u{0020}area\u{0020}of\u{0020}the\u{0020}wearer\u{0020}while\u{0020}providing\u{0020}defense.\n\"Just\u{0020}being\u{0020}a\u{0020}doctor\u{0020}or\u{0020}a\u{0020}driver\u{0020}is\u{0020}not\u{0020}enough.\u{0020}I\u{0020}deeply\u{0020}realize\u{0020}this.\"", "icon_kalian_zs2", "0", 3, 2, "3_{lv}*100", "Karen", "1_110021_10", 10, "3_100", "320130,320131,320132", "0", "0", "0", "0", "0", "学医谁都救不了", "萨哈拉支部所属学院的制式腿甲。采用较轻材质制造，适合机动性较强的单位配置。最大的特点是在侧部提供了便携式手榴弹的配置槽，能够在提供防御能力的同时扩大装备者的打击面。\n“仅仅只是作为一个医生或者驾驶员，是不够的，我深刻地意识到了这一点。”", "卡莲"},
[320132] = {320132, "Vow\u{0020}of\u{0020}White\u{0020}Water\u{0020}Lily", "The\u{0020}standard\u{0020}commander-type\u{0020}communication\u{0020}equipment\u{0020}of\u{0020}the\u{0020}academy\u{0020}affiliated\u{0020}to\u{0020}the\u{0020}Sahara\u{0020}Branch.\u{0020}As\u{0020}a\u{0020}communication\u{0020}equipment\u{0020}that\u{0020}everyone\u{0020}in\u{0020}the\u{0020}academy\u{0020}will\u{0020}be\u{0020}equipped\u{0020}with,\u{0020}in\u{0020}addition\u{0020}to\u{0020}the\u{0020}basic\u{0020}communication\u{0020}and\u{0020}positioning\u{0020}functions,\u{0020}the\u{0020}commander-type\u{0020}also\u{0020}has\u{0020}the\u{0020}function\u{0020}of\u{0020}collecting\u{0020}battlefield\u{0020}peripheral\u{0020}information.\u{0020}Therefore,\u{0020}it\u{0020}has\u{0020}higher\u{0020}requirements\u{0020}on\u{0020}the\u{0020}data\u{0020}analysis\u{0020}ability\u{0020}of\u{0020}the\u{0020}wearer.\n\"The\u{0020}indomitable\u{0020}will\u{0020}not\u{0020}only\u{0020}belongs\u{0020}to\u{0020}me\u{0020}but\u{0020}also\u{0020}to\u{0020}others.\u{0020}I\u{0020}will\u{0020}survive.\u{0020}Everyone\u{0020}will\u{0020}survive.\"", "icon_kalian_zs3", "0", 3, 3, "1_{lv}*100", "Karen", "1_110021_10", 10, "1_100", "320130,320131,320132", "0", "0", "0", "0", "0", "白睡莲的誓言", "萨哈拉支部所属学院的制式指挥官型通信设备。作为学院中每人都会配备的通信设备，指挥官型在持有基本的通信定位功能外，还附加了收集战场周边情报的功能，因此对于装备者的数据分析能力要求较高。\n“不灭的意志不仅仅属于我，还属于其他人，我会活下去，大家都会活下去。”", "卡莲"},
[320140] = {320140, "Initial\u{0020}Model\u{0020}of\u{0020}Canine\u{0020}Mecha", "The\u{0020}fusion\u{0020}product\u{0020}of\u{0020}Midyr's\u{0020}technology\u{0020}and\u{0020}AEGIS\u{0020}machinery.\u{0020}The\u{0020}control\u{0020}AI\u{0020}uses\u{0020}personality\u{0020}chip\u{0020}technology.\u{0020}But\u{0020}the\u{0020}owner\u{0020}has\u{0020}the\u{0020}highest\u{0020}control,\u{0020}that\u{0020}is,\u{0020}the\u{0020}driver.\u{0020}It\u{0020}can\u{0020}effectively\u{0020}prevent\u{0020}berserk\u{0020}situations.\nWhen\u{0020}there\u{0020}is\u{0020}no\u{0020}battle,\u{0020}it\u{0020}can\u{0020}shrink\u{0020}and\u{0020}become\u{0020}a\u{0020}pet-like\u{0020}existence\u{0020}like\u{0020}a\u{0020}driver.", "icon_xifalisi_zs1", "0", 2, 1, "1_{lv}*100", "Cephalis", "1_110021_5", 10, "1_100", "320140,320141,320142", "0", "0", "0", "0", "0", "0", "0", "0"},
[320141] = {320141, "Environmental\u{0020}Sensing\u{0020}Gloves", "The\u{0020}glove\u{0020}equipment\u{0020}manufactured\u{0020}by\u{0020}Midyr's\u{0020}technology.\u{0020}A\u{0020}small\u{0020}imitation\u{0020}Midyr\u{0020}amplification\u{0020}crystal\u{0020}is\u{0020}built\u{0020}in.\u{0020}Through\u{0020}mental\u{0020}power,\u{0020}it\u{0020}can\u{0020}detect\u{0020}things\u{0020}within\u{0020}a\u{0020}range\u{0020}of\u{0020}1\u{0020}kilometer.\u{0020}But\u{0020}it\u{0020}has\u{0020}extremely\u{0020}high\u{0020}requirements\u{0020}on\u{0020}mental\u{0020}power.\u{0020}At\u{0020}present,\u{0020}only\u{0020}a\u{0020}few\u{0020}Midyr\u{0020}drivers\u{0020}can\u{0020}use\u{0020}it.\n\"The\u{0020}feel\u{0020}from\u{0020}hands\u{0020}are\u{0020}more\u{0020}real\u{0020}and\u{0020}more\u{0020}cruel.\"", "icon_xifalisi_zs2", "0", 2, 2, "3_{lv}*100", "Cephalis", "1_110021_5", 10, "3_100", "320140,320141,320142", "0", "0", "0", "0", "0", "0", "0", "0"},
[320142] = {320142, "Thought\u{0020}Transmitter", "The\u{0020}thought\u{0020}transmitter\u{0020}manufactured\u{0020}by\u{0020}Midyr's\u{0020}technology.\u{0020}An\u{0020}imitation\u{0020}Midyr\u{0020}amplification\u{0020}crystal\u{0020}is\u{0020}built\u{0020}in.\u{0020}It\u{0020}can\u{0020}transmit\u{0020}the\u{0020}user's\u{0020}thoughts\u{0020}to\u{0020}the\u{0020}equipment.\u{0020}At\u{0020}present,\u{0020}it\u{0020}is\u{0020}only\u{0020}used\u{0020}to\u{0020}control\u{0020}the\u{0020}\"partner\u{0020}combat\u{0020}mechanism\"\u{0020}to\u{0020}issue\u{0020}commands\u{0020}during\u{0020}battles.\n\"My\u{0020}secrets\u{0020}cannot\u{0020}be\u{0020}known\u{0020}by\u{0020}others.\"", "icon_xifalisi_zs3", "0", 2, 3, "1_{lv}*100", "Cephalis", "1_110021_5", 10, "1_100", "320140,320141,320142", "0", "0", "0", "0", "0", "0", "0", "0"},
[320150] = {320150, "Flower\u{0020}of\u{0020}the\u{0020}Danube", "The\u{0020}weapon\u{0020}specially\u{0020}made\u{0020}by\u{0020}the\u{0020}research\u{0020}laboratory\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}branch\u{0020}for\u{0020}the\u{0020}Danube\u{0020}First\u{0020}Guards\u{0020}Squad.\u{0020}It\u{0020}has\u{0020}a\u{0020}unique\u{0020}umbrella-shaped\u{0020}appearance\u{0020}which\u{0020}in\u{0020}fact\u{0020}is\u{0020}the\u{0020}center\u{0020}of\u{0020}fire\u{0020}control.\u{0020}Through\u{0020}this\u{0020}umbrella,\u{0020}the\u{0020}firepower\u{0020}of\u{0020}other\u{0020}equipment\u{0020}can\u{0020}be\u{0020}effectively\u{0020}integrated.\u{0020}Of\u{0020}course,\u{0020}since\u{0020}the\u{0020}umbrella\u{0020}handle\u{0020}is\u{0020}made\u{0020}of\u{0020}titanium\u{0020}alloy,\u{0020}it\u{0020}also\u{0020}has\u{0020}great\u{0020}abilities\u{0020}in\u{0020}close\u{0020}combat.\n\"The\u{0020}princess\u{0020}of\u{0020}Danube,\u{0020}the\u{0020}flower\u{0020}of\u{0020}Danube...\u{0020}are\u{0020}all\u{0020}just\u{0020}meaningless\u{0020}titles.\"", "icon_weisipaer_zs1", "0", 3, 1, "1_{lv}*100", "Vesper", "1_110021_10", 10, "1_100", "320150,320151,320152", "0", "0", "0", "0", "0", "多瑙之花", "由艾吉斯支部—多瑙支部研究室专为多瑙第一亲卫班打造的武器。拥有独特的伞状外形，实则是火力控制的中枢，通过该伞可以有效整合全身配备的火力。当然由于伞柄使用钛合金打造，在近身战斗方面的效果也不错。\n多瑙的公主，多瑙之花......都是些虚无的头衔而已。", "薇丝帕尔"},
[320151] = {320151, "Combat\u{0020}Suit\u{0020}-\u{0020}Maid\u{0020}Type", "The\u{0020}combat\u{0020}uniform\u{0020}specially\u{0020}made\u{0020}by\u{0020}the\u{0020}research\u{0020}laboratory\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}of\u{0020}AEGIS\u{0020}for\u{0020}the\u{0020}First\u{0020}Guards\u{0020}Squad.\u{0020}Don't\u{0020}think\u{0020}it's\u{0020}just\u{0020}soft\u{0020}cloth.\u{0020}In\u{0020}fact,\u{0020}a\u{0020}lot\u{0020}of\u{0020}flexible\u{0020}metals\u{0020}are\u{0020}woven\u{0020}in\u{0020}it.\u{0020}While\u{0020}ensuring\u{0020}comfort,\u{0020}it\u{0020}also\u{0020}provides\u{0020}good\u{0020}shock\u{0020}resistance.\nWith\u{0020}both\u{0020}comfort\u{0020}and\u{0020}protection.\u{0020}Although\u{0020}I\u{0020}don't\u{0020}know\u{0020}whose\u{0020}vulgar\u{0020}taste\u{0020}it\u{0020}is,\u{0020}this\u{0020}maid\u{0020}outfit\u{0020}is\u{0020}in\u{0020}line\u{0020}with\u{0020}noble\u{0020}standards.", "icon_weisipaer_zs2", "0", 3, 2, "3_{lv}*100", "Vesper", "1_110021_10", 10, "3_100", "320150,320151,320152", "0", "0", "0", "0", "0", "战斗服·女仆型", "由艾吉斯支部—多瑙支部研究室专为多瑙第一亲卫班打造的战斗服。别看好像只是柔软的布料，其实里面掺杂了很多柔性金属，在保证舒适的同时也提供了不俗的抗打击能力。\n兼备舒适和防护，虽不知是谁的恶趣味，这件女仆装倒也符合贵族的标准。", "薇丝帕尔"},
[320152] = {320152, "Pioneer", "The\u{0020}power\u{0020}device\u{0020}specially\u{0020}made\u{0020}by\u{0020}the\u{0020}research\u{0020}laboratory\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}of\u{0020}AEGIS\u{0020}for\u{0020}the\u{0020}First\u{0020}Guards\u{0020}Squad.\u{0020}It\u{0020}pays\u{0020}more\u{0020}attention\u{0020}to\u{0020}stability\u{0020}than\u{0020}speed.\u{0020}With\u{0020}the\u{0020}internal\u{0020}gravity\u{0020}module,\u{0020}the\u{0020}driver\u{0020}can\u{0020}freely\u{0020}switch\u{0020}between\u{0020}being\u{0020}swift\u{0020}and\u{0020}stable.\u{0020}It\u{0020}is\u{0020}very\u{0020}suitable\u{0020}for\u{0020}Heavy\u{0020}type\u{0020}drivers.\nIn\u{0020}the\u{0020}past,\u{0020}nobles\u{0020}have\u{0020}always\u{0020}been\u{0020}representatives\u{0020}of\u{0020}pioneers.\u{0020}I\u{0020}don't\u{0020}know\u{0020}when\u{0020}nobles\u{0020}have\u{0020}become\u{0020}symbols\u{0020}of\u{0020}conservatism.", "icon_weisipaer_zs3", "0", 3, 3, "1_{lv}*100", "Vesper", "1_110021_10", 10, "1_100", "320150,320151,320152", "0", "0", "0", "0", "0", "先驱者", "由艾吉斯支部—多瑙支部研究室专为多瑙第一亲卫班打造的动力装置。比起速度更加注重稳定，凭借内部的重力模块可以让驾驶员在身轻如燕和不动如山两种状态间自由切换，非常适合火力型驾驶员使用。\n在过去，贵族一直是先驱的代表，不知何时贵族成为了守旧的象征。", "薇丝帕尔"},
[320160] = {320160, "Light\u{0020}of\u{0020}the\u{0020}Star\u{0020}Cluster", "The\u{0020}equipment\u{0020}developed\u{0020}by\u{0020}the\u{0020}R&D\u{0020}department\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}the\u{0020}Hanging\u{0020}Emperor.\u{0020}The\u{0020}appearance\u{0020}refers\u{0020}to\u{0020}the\u{0020}lighting\u{0020}system\u{0020}on\u{0020}the\u{0020}stage.\u{0020}Although\u{0020}it\u{0020}seems\u{0020}to\u{0020}be\u{0020}just\u{0020}a\u{0020}stage\u{0020}light,\u{0020}it\u{0020}is\u{0020}actually\u{0020}a\u{0020}camera\u{0020}with\u{0020}ultra-high\u{0020}pixels.\u{0020}By\u{0020}suspending\u{0020}it\u{0020}at\u{0020}a\u{0020}high\u{0020}place\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}through\u{0020}an\u{0020}anti-gravity\u{0020}device,\u{0020}it\u{0020}can\u{0020}capture\u{0020}the\u{0020}slightest\u{0020}movement\u{0020}of\u{0020}the\u{0020}enemy.\nThe\u{0020}light\u{0020}from\u{0020}the\u{0020}stars\u{0020}illuminates\u{0020}the\u{0020}entire\u{0020}stage.", "icon_saladisuoni_zs1", "0", 2, 1, "3_{lv}*100", "Salati", "1_110021_5", 10, "3_100", "320160,320161,320162", "0", "0", "0", "0", "0", "星群之光", "由艾吉斯九州总部研发部为绞皇大队开发的装备，外形参考了舞台上的灯光系统。虽然看上去只是一个舞台灯但是其实是个拥有超高像素的摄像头，通过反重力装置悬浮在战场高处可以敏锐捕捉到敌人的风吹草动。\n来自星星的光芒照亮整个舞台。", "萨拉蒂"},
[320161] = {320161, "Ear\u{0020}of\u{0020}Cerberus", "The\u{0020}communicator\u{0020}developed\u{0020}by\u{0020}the\u{0020}R&D\u{0020}department\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}the\u{0020}Hanging\u{0020}Emperor.\u{0020}It\u{0020}is\u{0020}also\u{0020}a\u{0020}headset\u{0020}with\u{0020}extremely\u{0020}strong\u{0020}noise\u{0020}canceling.\u{0020}After\u{0020}wearing\u{0020}it,\u{0020}all\u{0020}external\u{0020}sounds\u{0020}can\u{0020}be\u{0020}isolated,\u{0020}and\u{0020}only\u{0020}the\u{0020}sound\u{0020}from\u{0020}the\u{0020}internal\u{0020}device\u{0020}can\u{0020}be\u{0020}heard.\u{0020}This\u{0020}can\u{0020}ensure\u{0020}that\u{0020}the\u{0020}user\u{0020}is\u{0020}not\u{0020}disturbed.\u{0020}But\u{0020}it\u{0020}is\u{0020}also\u{0020}impossible\u{0020}to\u{0020}detect\u{0020}approaching\u{0020}dangers\u{0020}in\u{0020}time.\u{0020}So\u{0020}it\u{0020}needs\u{0020}to\u{0020}be\u{0020}used\u{0020}in\u{0020}an\u{0020}absolutely\u{0020}safe\u{0020}situation,\u{0020}such\u{0020}as\u{0020}by\u{0020}the\u{0020}side\u{0020}of\u{0020}reliable\u{0020}teammates.\nThe\u{0020}reason\u{0020}why\u{0020}I\u{0020}am\u{0020}immersed\u{0020}in\u{0020}the\u{0020}world\u{0020}of\u{0020}music\u{0020}is\u{0020}that\u{0020}the\u{0020}reality\u{0020}is\u{0020}too\u{0020}boring.", "icon_saladisuoni_zs2", "0", 2, 2, "3_{lv}*100", "Salati", "1_110021_5", 10, "3_100", "320160,320161,320162", "0", "0", "0", "0", "0", "刻耳柏洛斯之耳", "由艾吉斯九州总部研发部为绞皇大队开发的通讯器，同时也是个拥有极强隔音效果的耳机，戴上之后可以将外界的一切声音都隔绝，只能听见内部播音设备传来的声音。这样可以保证使用者不受外界的干扰，当然也就不能及时发现靠近的危险，所以需要在绝对安全的情况下使用，比如在可靠的队友身边。\n之所以沉浸在音乐的世界里，还不是因为现实太无聊了。", "萨拉蒂"},
[320162] = {320162, "Control\u{0020}of\u{0020}the\u{0020}Abyss", "The\u{0020}firepower\u{0020}weapon\u{0020}developed\u{0020}by\u{0020}the\u{0020}R&D\u{0020}department\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}the\u{0020}Hanging\u{0020}Emperor.\u{0020}It\u{0020}attacks\u{0020}the\u{0020}target\u{0020}by\u{0020}emitting\u{0020}powerful\u{0020}sound\u{0020}waves\u{0020}through\u{0020}high-frequency\u{0020}vibration.\u{0020}To\u{0020}make\u{0020}it\u{0020}easy\u{0020}to\u{0020}use,\u{0020}its\u{0020}control\u{0020}console\u{0020}is\u{0020}in\u{0020}the\u{0020}shape\u{0020}of\u{0020}a\u{0020}DJ\u{0020}mixer.\u{0020}The\u{0020}user\u{0020}can\u{0020}also\u{0020}load\u{0020}their\u{0020}favorite\u{0020}music\u{0020}into\u{0020}the\u{0020}library\u{0020}as\u{0020}background\u{0020}music\u{0020}during\u{0020}attacks.\nFortunately,\u{0020}all\u{0020}the\u{0020}residents\u{0020}around\u{0020}have\u{0020}been\u{0020}evacuated.\u{0020}Otherwise,\u{0020}they\u{0020}will\u{0020}be\u{0020}sued\u{0020}for\u{0020}disturbing\u{0020}the\u{0020}people.", "icon_saladisuoni_zs3", "0", 2, 3, "1_{lv}*100", "Salati", "1_110021_5", 10, "1_100", "320160,320161,320162", "0", "0", "0", "0", "0", "深渊掌控", "由艾吉斯九州总部研发部为绞皇大队开发的火力武器，通过高频振动来发射威力巨大的音波，对目标进行攻击。为了方便使用特意将其控制台做成打碟机的操作方式，使用者还可以将自己喜欢的音乐加载入乐库作为攻击时的伴奏。\n还好周围的居民已经全部撤离，不然就要被告扰民了。", "萨拉蒂"},
[320170] = {320170, "Suzu's\u{0020}Summer", "Suzu's\u{0020}swimming\u{0020}ring.\u{0020}A\u{0020}swimming\u{0020}ring\u{0020}purchased\u{0020}before\u{0020}Suzu\u{0020}learned\u{0020}to\u{0020}swim.\u{0020}Even\u{0020}though\u{0020}she\u{0020}has\u{0020}learned\u{0020}to\u{0020}swim\u{0020}now,\u{0020}Suzu\u{0020}will\u{0020}still\u{0020}bring\u{0020}it\u{0020}with\u{0020}her\u{0020}every\u{0020}summer.\u{0020}By\u{0020}the\u{0020}way,\u{0020}Caihua\u{0020}paid\u{0020}for\u{0020}it.\nA\u{0020}treasure\u{0020}that\u{0020}gives\u{0020}Suzu\u{0020}a\u{0020}sense\u{0020}of\u{0020}security.", "icon_yongzhuangling_zs1", "0", 4, 1, "1_{lv}*100", "Suzu", "1_110021_20", 10, "1_100", "320170,320171,320172", "0", "0", "0", "0", "0", "0", "0", "0"},
[320171] = {320171, "Fox\u{0020}Maru\u{0020}(Swimsuit)", "The\u{0020}Fox\u{0020}Maru\u{0020}that\u{0020}only\u{0020}appears\u{0020}in\u{0020}summer.\u{0020}A\u{0020}gift\u{0020}brought\u{0020}to\u{0020}Suzu\u{0020}by\u{0020}the\u{0020}members\u{0020}of\u{0020}Tian\u{0020}Hua\u{0020}Pavilion\u{0020}who\u{0020}spoil\u{0020}Suzu.\u{0020}A\u{0020}new\u{0020}model\u{0020}redesigned\u{0020}by\u{0020}scientists.\u{0020}Don't\u{0020}underestimate\u{0020}it.\u{0020}Although\u{0020}it\u{0020}has\u{0020}the\u{0020}appearance\u{0020}of\u{0020}a\u{0020}toy,\u{0020}don't\u{0020}underestimate\u{0020}its\u{0020}\"little\u{0020}surprise\".\nWho\u{0020}added\u{0020}the\u{0020}attack\u{0020}module\u{0020}to\u{0020}this\u{0020}Fox\u{0020}Maru?!", "icon_yongzhuangling_zs2", "0", 4, 2, "1_{lv}*100", "Suzu", "1_110021_20", 10, "1_100", "320170,320171,320172", "0", "0", "0", "0", "0", "0", "0", "0"},
[320172] = {320172, "The\u{0020}Place\u{0020}Where\u{0020}the\u{0020}Sun\u{0020}Stays", "The\u{0020}special\u{0020}sunglasses\u{0020}commissioned\u{0020}by\u{0020}Suzu\u{0020}to\u{0020}be\u{0020}made\u{0020}by\u{0020}scientists\u{0020}because\u{0020}she\u{0020}wants\u{0020}to\u{0020}look\u{0020}directly\u{0020}at\u{0020}the\u{0020}sun.\u{0020}Later,\u{0020}she\u{0020}found\u{0020}that\u{0020}even\u{0020}wearing\u{0020}sunglasses\u{0020}to\u{0020}look\u{0020}at\u{0020}the\u{0020}sun\u{0020}still\u{0020}makes\u{0020}her\u{0020}dizzy.\u{0020}So\u{0020}she\u{0020}gave\u{0020}up.\u{0020}Now\u{0020}it\u{0020}stays\u{0020}by\u{0020}Suzu's\u{0020}side\u{0020}as\u{0020}an\u{0020}ordinary\u{0020}sunglasses.\nThere\u{0020}are\u{0020}words\u{0020}written\u{0020}on\u{0020}the\u{0020}temple\u{0020}of\u{0020}the\u{0020}sunglasses.\u{0020}The\u{0020}general\u{0020}meaning\u{0020}is\u{0020}\"Do\u{0020}not\u{0020}look\u{0020}directly.\"", "icon_yongzhuangling_zs3", "0", 4, 3, "1_{lv}*100", "Suzu", "1_110021_20", 10, "1_100", "320170,320171,320172", "0", "0", "0", "0", "0", "0", "0", "0"},
[320180] = {320180, "Stellar\u{0020}Arc\u{0020}Bridge", "Shisha's\u{0020}AVG.\u{0020}Designed\u{0020}by\u{0020}herself,\u{0020}reportedly\u{0020}inspired\u{0020}by\u{0020}a\u{0020}spaceship\u{0020}from\u{0020}a\u{0020}sci-fi\u{0020}movie.\u{0020}Though\u{0020}named\u{0020}Bridge,\u{0020}it\u{0020}can\u{0020}release\u{0020}energy\u{0020}beams.\nHow\u{0020}could\u{0020}the\u{0020}design\u{0020}of\u{0020}a\u{0020}space\u{0020}arc\u{0020}bridge\u{0020}be\u{0020}adapted\u{0020}for\u{0020}ground\u{0020}use?\u{0020}Shisha\u{0020}pondered.", "icon_xixia_zs1", "0", 4, 1, "1_{lv}*100", "Shisha", "1_110021_20", 10, "1_100", "320180,320181,320182", "0", "0", "0", "0", "0", "0", "0", "0"},
