[320230] = {320230, "Gravitational\u{0020}Tidal\u{0020}Effect", "The\u{0020}reconnaissance\u{0020}and\u{0020}communication\u{0020}device\u{0020}jointly\u{0020}developed\u{0020}by\u{0020}teachers\u{0020}and\u{0020}students\u{0020}of\u{0020}the\u{0020}engineering\u{0020}department\u{0020}of\u{0020}the\u{0020}Sahara\u{0020}Academy.\u{0020}It\u{0020}can\u{0020}maintain\u{0020}signal\u{0020}stability\u{0020}in\u{0020}most\u{0020}environments\u{0020}so\u{0020}as\u{0020}to\u{0020}receive\u{0020}messages\u{0020}from\u{0020}the\u{0020}frontline\u{0020}at\u{0020}any\u{0020}time\u{0020}and\u{0020}prepare\u{0020}for\u{0020}long-range\u{0020}strikes.\nThe\u{0020}rise\u{0020}and\u{0020}fall\u{0020}of\u{0020}seawater\u{0020}is\u{0020}not\u{0020}related\u{0020}to\u{0020}the\u{0020}ups\u{0020}and\u{0020}downs\u{0020}of\u{0020}fish\u{0020}and\u{0020}shrimp,\u{0020}but\u{0020}is\u{0020}controlled\u{0020}by\u{0020}the\u{0020}gravity\u{0020}of\u{0020}the\u{0020}stars.", "icon_sitila_zs1", "0", 3, 1, "1_{lv}*100", "Stella", "1_110021_10", 10, "1_100", "320230,320231,320232", "0", "0", "0", "0", "0", "多瑙之花", "由艾吉斯支部—多瑙支部研究室专为多瑙第一亲卫班打造的武器。拥有独特的伞状外形，实则是火力控制的中枢，通过该伞可以有效整合全身配备的火力。当然由于伞柄使用钛合金打造，在近身战斗方面的效果也不错。\n多瑙的公主，多瑙之花......都是些虚无的头衔而已。", "薇丝帕尔"},
[320231] = {320231, "Colors\u{0020}of\u{0020}the\u{0020}Stars", "The\u{0020}protective\u{0020}device\u{0020}jointly\u{0020}developed\u{0020}by\u{0020}teachers\u{0020}and\u{0020}students\u{0020}of\u{0020}the\u{0020}engineering\u{0020}department\u{0020}of\u{0020}the\u{0020}Sahara\u{0020}Academy.\u{0020}The\u{0020}original\u{0020}design\u{0020}scheme\u{0020}was\u{0020}to\u{0020}achieve\u{0020}the\u{0020}effect\u{0020}of\u{0020}optical\u{0020}camouflage\u{0020}through\u{0020}special\u{0020}coatings.\u{0020}But\u{0020}considering\u{0020}Stella's\u{0020}actual\u{0020}strategic\u{0020}position,\u{0020}the\u{0020}design\u{0020}was\u{0020}finally\u{0020}abandoned\u{0020}and\u{0020}the\u{0020}focus\u{0020}was\u{0020}on\u{0020}the\u{0020}thermal\u{0020}insulation\u{0020}function.\nThe\u{0020}brilliance\u{0020}of\u{0020}the\u{0020}stars\u{0020}is\u{0020}eternal\u{0020}nothingness.", "icon_sitila_zs2", "0", 3, 2, "3_{lv}*100", "Stella", "1_110021_10", 10, "3_100", "320230,320231,320232", "0", "0", "0", "0", "0", "战斗服·女仆型", "由艾吉斯支部—多瑙支部研究室专为多瑙第一亲卫班打造的战斗服。别看好像只是柔软的布料，其实里面掺杂了很多柔性金属，在保证舒适的同时也提供了不俗的抗打击能力。\n兼备舒适和防护，虽不知是谁的恶趣味，这件女仆装倒也符合贵族的标准。", "薇丝帕尔"},
[320232] = {320232, "Beyond\u{0020}the\u{0020}Field\u{0020}of\u{0020}Vision", "The\u{0020}sniper\u{0020}rifle\u{0020}jointly\u{0020}developed\u{0020}by\u{0020}teachers\u{0020}and\u{0020}students\u{0020}of\u{0020}the\u{0020}engineering\u{0020}department\u{0020}of\u{0020}the\u{0020}Sahara\u{0020}Academy.\u{0020}The\u{0020}design\u{0020}of\u{0020}the\u{0020}sniper\u{0020}scope\u{0020}completely\u{0020}follows\u{0020}Stella's\u{0020}opinion.\u{0020}Imitating\u{0020}the\u{0020}structure\u{0020}of\u{0020}an\u{0020}astronomical\u{0020}telescope,\u{0020}it\u{0020}can\u{0020}see\u{0020}targets\u{0020}far\u{0020}beyond\u{0020}the\u{0020}visual\u{0020}distance\u{0020}limit\u{0020}of\u{0020}a\u{0020}conventional\u{0020}sniper\u{0020}scope.\u{0020}The\u{0020}small\u{0020}sight\u{0020}additionally\u{0020}installed\u{0020}on\u{0020}the\u{0020}sniper\u{0020}scope\u{0020}provides\u{0020}a\u{0020}more\u{0020}comfortable\u{0020}field\u{0020}of\u{0020}view\u{0020}in\u{0020}close\u{0020}combat.\nRather\u{0020}than\u{0020}using\u{0020}her\u{0020}to\u{0020}fight\u{0020}the\u{0020}enemy,\u{0020}I\u{0020}hope\u{0020}to\u{0020}use\u{0020}her\u{0020}to\u{0020}look\u{0020}up\u{0020}at\u{0020}the\u{0020}stars.", "icon_sitila_zs3", "0", 3, 3, "1_{lv}*100", "Stella", "1_110021_10", 10, "1_100", "320230,320231,320232", "0", "0", "0", "0", "0", "先驱者", "由艾吉斯支部—多瑙支部研究室专为多瑙第一亲卫班打造的动力装置。比起速度更加注重稳定，凭借内部的重力模块可以让驾驶员在身轻如燕和不动如山两种状态间自由切换，非常适合火力型驾驶员使用。\n在过去，贵族一直是先驱的代表，不知何时贵族成为了守旧的象征。", "薇丝帕尔"},
