[320292] = {320292, "A\u{0020}Cat's\u{0020}Melancholy", "It\u{0020}simply\u{0020}rolls\u{0020}over,\u{0020}exposing\u{0020}its\u{0020}fluffy\u{0020}belly,\u{0020}its\u{0020}four\u{0020}paws\u{0020}lightly\u{0020}kicking\u{0020}in\u{0020}the\u{0020}air\u{0020}as\u{0020}a\u{0020}satisfied\u{0020}purr\u{0020}rumbles\u{0020}in\u{0020}its\u{0020}throat.\nThe\u{0020}wind\u{0020}lifts\u{0020}your\u{0020}hair,\u{0020}and\u{0020}also\u{0020}stirs\u{0020}the\u{0020}cat's\u{0020}soft\u{0020}fur.\u{0020}You\u{0020}cannot\u{0020}help\u{0020}reaching\u{0020}out\u{0020}and\u{0020}gently\u{0020}stroking\u{0020}its\u{0020}head.\u{0020}It\u{0020}narrows\u{0020}its\u{0020}eyes\u{0020}slightly\u{0020}and\u{0020}gives\u{0020}your\u{0020}finger\u{0020}a\u{0020}symbolic\u{0020}tap\u{0020}with\u{0020}its\u{0020}paw,\u{0020}so\u{0020}light\u{0020}it\u{0020}feels\u{0020}like\u{0020}a\u{0020}feather\u{0020}brushing\u{0020}past.\u{0020}You\u{0020}cannot\u{0020}help\u{0020}thinking\u{0020}that\u{0020}perhaps,\u{0020}in\u{0020}this\u{0020}quiet\u{0020}alley,\u{0020}in\u{0020}this\u{0020}brief\u{0020}moment,\u{0020}the\u{0020}two\u{0020}of\u{0020}you\u{0020}are\u{0020}each\u{0020}other's\u{0020}place\u{0020}to\u{0020}return\u{0020}to.", "icon_dafululu_zs3", "0", 4, 3, "1_{lv}*100", "Re:\u{0020}Fleur", "1_110021_20", 10, "1_100", "320290,320291,320292", "0", "0", "0", "0", "0", "0", "0", "0"},
