[320372] = {320372, "Infinite\u{0020}Glove\u{0020}2.0", "Kyla's\u{0020}transformation\u{0020}device\u{0020}and\u{0020}a\u{0020}weapon\u{0020}she\u{0020}can\u{0020}also\u{0020}use\u{0020}normally.\u{0020}According\u{0020}to\u{0020}the\u{0020}user\u{0020}herself,\u{0020}its\u{0020}maximum\u{0020}output\u{0020}in\u{0020}normal\u{0020}mode\u{0020}even\u{0020}has\u{0020}a\u{0020}chance\u{0020}of\u{0020}taking\u{0020}down\u{0020}a\u{0020}bear\u{0020}(by\u{0020}Heroine\u{0020}Universe\u{0020}standards).\nIt\u{0020}has\u{0020}actually\u{0020}gone\u{0020}through\u{0020}countless\u{0020}iterations\u{0020}already,\u{0020}but\u{0020}Kyla\u{0020}can't\u{0020}tell\u{0020}the\u{0020}difference,\u{0020}so\u{0020}she\u{0020}simply\u{0020}considers\u{0020}it\u{0020}version\u{0020}2.0.", "icon_hlyongzhuang_zs3", "0", 4, 3, "1_{lv}*100", "Kyla\u{0020}(Swimsuit)", "1_110021_20", 10, "1_100", "320370,320371,320372", "0", "0", "0", "0", "0", "0", "0", "0"},
[320380] = {320380, "Seagem\u{0020}Blade", "The\u{0020}latest\u{0020}standard-issue\u{0020}weapon\u{0020}from\u{0020}Catpaw\u{0020}Gear\u{0020}Workshop.\u{0020}Lightweight\u{0020}and\u{0020}sharp,\u{0020}it\u{0020}can\u{0020}handle\u{0020}most\u{0020}combat\u{0020}environments\u{0020}and\u{0020}comes\u{0020}with\u{0020}a\u{0020}built-in\u{0020}storage\u{0020}space\u{0020}that\u{0020}can\u{0020}be\u{0020}accessed\u{0020}at\u{0020}any\u{0020}time.\nIn\u{0020}theory,\u{0020}it\u{0020}can\u{0020}apparently\u{0020}be\u{0020}controlled\u{0020}by\u{0020}thought\u{0020}alone,\u{0020}but\u{0020}\"that\u{0020}just\u{0020}isn't\u{0020}befitting\u{0020}of\u{0020}a\u{0020}vacationing\u{0020}celebrity.\"", "icon_lsldyongzhuang_zs1", "0", 4, 1, "1_{lv}*100", "Rosalind\u{0020}(Swimsuit)", "1_110021_20", 10, "1_100", "320380,320381,320382", "0", "0", "0", "0", "0", "0", "0", "0"},
[320381] = {320381, "Personal\u{0020}Assistants\u{0020}α\u{0020}&\u{0020}β", "Two\u{0020}innocent\u{0020}drones\u{0020}forcibly\u{0020}put\u{0020}to\u{0020}work\u{0020}because\u{0020}\"a\u{0020}true\u{0020}celebrity\u{0020}needs\u{0020}reliable\u{0020}attendants,\"\u{0020}both\u{0020}manufactured\u{0020}by\u{0020}Catpaw\u{0020}Gear\u{0020}Workshop.\u{0020}They\u{0020}originally\u{0020}lived\u{0020}carefree\u{0020}lives.\nThey\u{0020}are\u{0020}paid\u{0020}by\u{0020}the\u{0020}hour\u{0020}and\u{0020}are\u{0020}currently\u{0020}saving\u{0020}up\u{0020}to\u{0020}have\u{0020}Molly\u{0020}give\u{0020}them\u{0020}a\u{0020}full\u{0020}maintenance\u{0020}overhaul.", "icon_lsldyongzhuang_zs2", "0", 4, 2, "1_{lv}*100", "Rosalind\u{0020}(Swimsuit)", "1_110021_20", 10, "1_100", "320380,320381,320382", "0", "0", "0", "0", "0", "0", "0", "0"},
[320382] = {320382, "Celebrity\u{0020}Etiquette", "A\u{0020}seaside\u{0020}vacation-themed\u{0020}outfit\u{0020}released\u{0020}by\u{0020}\"Coral\u{0020}Seaside\"\u{0020}last\u{0020}year.\u{0020}Its\u{0020}advertisement\u{0020}claims\u{0020}that\u{0020}it\u{0020}provides\u{0020}enough\u{0020}protection\u{0020}to\u{0020}handle\u{0020}all\u{0020}kinds\u{0020}of\u{0020}bizarre\u{0020}phenomena\u{0020}in\u{0020}the\u{0020}\"Heroine\u{0020}Universe.\"\nWhether\u{0020}that's\u{0020}actually\u{0020}true\u{0020}is\u{0020}another\u{0020}matter,\u{0020}but\u{0020}at\u{0020}the\u{0020}very\u{0020}least,\u{0020}it\u{0020}does\u{0020}an\u{0020}excellent\u{0020}job\u{0020}of\u{0020}blocking\u{0020}the\u{0020}sun\u{0020}and\u{0020}preventing\u{0020}sunburn.", "icon_lsldyongzhuang_zs3", "0", 4, 3, "3_{lv}*100", "Rosalind\u{0020}(Swimsuit)", "1_110021_20", 10, "3_100", "320380,320381,320382", "0", "0", "0", "0", "0", "0", "0", "0"},
[330000] = {330000, "Kapu", "The\u{0020}prototype\u{0020}of\u{0020}the\u{0020}intelligent\u{0020}robot\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}Odora\u{0020}herself.\u{0020}Equipping\u{0020}the\u{0020}synchronization\u{0020}system,\u{0020}it\u{0020}stably\u{0020}transmits\u{0020}the\u{0020}user's\u{0020}mental\u{0020}power\u{0020}in\u{0020}battle.\nPerhaps\u{0020}in\u{0020}the\u{0020}near\u{0020}future,\u{0020}Dr.\u{0020}Stephanie\u{0020}will\u{0020}be\u{0020}able\u{0020}to\u{0020}let\u{0020}loose\u{0020}some\u{0020}of\u{0020}her\u{0020}burdens.", "icon_oubeila_zs1", "0", 2, 1, "3_{lv}*100", "Odora", "1_110021_5", 10, "3_100", "330000,330001,330002", "0", "0", "0", "0", "0", "卡普", "欧朵啦自己设计并制造的智能型机器人原型，在搭载了同调系统后能够在战斗中稳定传输使用者的精神力量。\n也许在不久的将来，史蒂芬妮博士就能卸下身上的部分重担了吧。", "欧朵啦"},
[330001] = {330001, "Shield\u{0020}of\u{0020}the\u{0020}Throne", "The\u{0020}large\u{0020}solid\u{0020}shield\u{0020}designed\u{0020}by\u{0020}Odora\u{0020}herself.\u{0020}By\u{0020}sacrificing\u{0020}mobility,\u{0020}it\u{0020}greatly\u{0020}improves\u{0020}defense.\u{0020}Generally\u{0020}speaking,\u{0020}all\u{0020}support\u{0020}characters\u{0020}can\u{0020}use\u{0020}it.\u{0020}Now\u{0020}is\u{0020}ready\u{0020}to\u{0020}be\u{0020}equipped\u{0020}to\u{0020}drivers\u{0020}with\u{0020}low\u{0020}compatability\u{0020}rates.\nIn\u{0020}this\u{0020}way,\u{0020}Odora\u{0020}has\u{0020}an\u{0020}additional\u{0020}merit.\u{0020}When\u{0020}will\u{0020}this\u{0020}merit\u{0020}play\u{0020}a\u{0020}decisive\u{0020}role?\u{0020}I\u{0020}hope\u{0020}there\u{0020}will\u{0020}never\u{0020}be\u{0020}such\u{0020}a\u{0020}time.", "icon_oubeila_zs2", "0", 2, 2, "8_{lv}*200", "Odora", "1_110021_5", 10, "8_200", "330000,330001,330002", "0", "0", "0", "0", "0", "御座之盾", "欧朵啦自己设计的大型实体盾牌，以牺牲机动力的方式极大的提升了防御力，通常来说，支援角色都可以使用，现已准备普及给适格率不高的驾驶员。\n如此一来，欧朵啦的身上就多了一份功绩，这份功绩在什么时候会发挥出决定性的作用？希望永远没有这一天。", "欧朵啦"},
[330002] = {330002, "Sky\u{0020}Throne", "The\u{0020}prototype\u{0020}test\u{0020}machine\u{0020}of\u{0020}the\u{0020}aerospace\u{0020}warship.\u{0020}Equipped\u{0020}with\u{0020}a\u{0020}miniature\u{0020}second-generation\u{0020}Nimbus\u{0020}reactor.\u{0020}It\u{0020}can\u{0020}provide\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}energy\u{0020}on\u{0020}the\u{0020}battlefield.\nA\u{0020}petite\u{0020}girl\u{0020}sits\u{0020}on\u{0020}the\u{0020}throne.\u{0020}It\u{0020}is\u{0020}her\u{0020}will\u{0020}that\u{0020}dominates\u{0020}the\u{0020}aerospace\u{0020}warship.\u{0020}In\u{0020}her\u{0020}domain,\u{0020}there\u{0020}is\u{0020}only\u{0020}one\u{0020}opponent.", "icon_oubeila_zs3", "0", 2, 3, "8_{lv}*200", "Odora", "1_110021_5", 10, "8_200", "330000,330001,330002", "0", "0", "0", "0", "0", "空天王座", "空天战舰的原型试验机，搭载有微型二代尼姆比斯反应堆，能够在战场上提供大量能源。\n王座上坐着一位娇小的少女，是她的意志主宰着空天战舰，在她的领域，敌手只有一位——", "欧朵啦"},
[330010] = {330010, "Dawn\u{0020}is\u{0020}Newborn", "The\u{0020}synchronization\u{0020}device\u{0020}designed\u{0020}by\u{0020}AEGIS.\u{0020}It\u{0020}stably\u{0020}transmits\u{0020}the\u{0020}user's\u{0020}mental\u{0020}power\u{0020}in\u{0020}battle.\nLike\u{0020}a\u{0020}ray\u{0020}of\u{0020}just\u{0020}right\u{0020}dawn,\u{0020}emitting\u{0020}milky\u{0020}white\u{0020}light\u{0020}and\u{0020}sprinkling\u{0020}it\u{0020}on\u{0020}everyone\u{0020}who\u{0020}gets\u{0020}along\u{0020}with\u{0020}her.\u{0020}You\u{0020}may\u{0020}not\u{0020}notice\u{0020}the\u{0020}temperature\u{0020}of\u{0020}this\u{0020}ray\u{0020}of\u{0020}light,\u{0020}but\u{0020}when\u{0020}you\u{0020}walk\u{0020}into\u{0020}the\u{0020}shade,\u{0020}you\u{0020}feel\u{0020}a\u{0020}little\u{0020}cold.", "icon_fulanka_zs1", "0", 2, 1, "3_{lv}*100", "Franca", "1_110021_5", 10, "3_100", "330010,330011,330012", "0", "0", "0", "0", "0", "晨曦初生", "艾吉斯设计的同调装置，能够在战斗中稳定传输使用者的精神力量。\n如一缕恰好的晨曦，散发着乳白色的光挥洒在每一位与她相处的人身上，你可能没有察觉这缕光的温度，却在走入阴处时感到有一丝寒冷。", "弗兰卡"},
[330011] = {330011, "When\u{0020}the\u{0020}Sun\u{0020}Hangs", "The\u{0020}force\u{0020}field\u{0020}deflection\u{0020}device\u{0020}designed\u{0020}by\u{0020}AEGIS.\u{0020}It\u{0020}can\u{0020}distort\u{0020}the\u{0020}enemy's\u{0020}attack.\nEven\u{0020}if\u{0020}she\u{0020}is\u{0020}inconspicuous,\u{0020}she\u{0020}can\u{0020}still\u{0020}bloom.\u{0020}She\u{0020}is\u{0020}always\u{0020}strong\u{0020}and\u{0020}gentle.", "icon_fulanka_zs2", "0", 2, 2, "8_{lv}*200", "Franca", "1_110021_5", 10, "8_200", "330010,330011,330012", "0", "0", "0", "0", "0", "日悬之时", "艾吉斯设计的力场偏移装置，可以扭曲敌人的进攻。\n即使是不起眼的她，也依然能绽放，她总是坚强而温柔。", "弗兰卡"},
[330012] = {330012, "White\u{0020}Star", "The\u{0020}power\u{0020}device\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}Features\u{0020}a\u{0020}small\u{0020}Nimbus\u{0020}reactor\u{0020}and\u{0020}can\u{0020}provide\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}power\u{0020}to\u{0020}the\u{0020}user.\nThe\u{0020}white\u{0020}star\u{0020}emits\u{0020}a\u{0020}faint\u{0020}light.", "icon_fulanka_zs3", "0", 2, 3, "8_{lv}*200", "Franca", "1_110021_5", 10, "8_200", "330010,330011,330012", "0", "0", "0", "0", "0", "白色的星星", "艾吉斯设计并制造的动力装置，其内部整合了小型尼姆比斯反应堆，能够为使用者提供大量动力。\n白色星星散发着微弱的光。", "弗兰卡"},
[330020] = {330020, "Alice's\u{0020}Nine-Section\u{0020}Whip", "The\u{0020}military\u{0020}equipment\u{0020}for\u{0020}instructors\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}Cretia\u{0020}family.\u{0020}Using\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}energy\u{0020}conversion\u{0020}technology,\u{0020}the\u{0020}energy\u{0020}stored\u{0020}in\u{0020}the\u{0020}whip\u{0020}can\u{0020}be\u{0020}injected\u{0020}into\u{0020}the\u{0020}mechs\u{0020}of\u{0020}teammates\u{0020}to\u{0020}improve\u{0020}combat\u{0020}effectiveness.\nMiss\u{0020}Alice,\u{0020}she\u{0020}is\u{0020}our\u{0020}only\u{0020}heir.\u{0020}Please\u{0020}hold\u{0020}your\u{0020}head\u{0020}up\u{0020}more\u{0020}proudly.\u{0020}I\u{0020}will\u{0020}watch\u{0020}over\u{0020}you.", "icon_dina_zs1", "0", 2, 1, "3_{lv}*100", "Tina", "1_110021_5", 10, "3_100", "330020,330021,330022", "0", "0", "0", "0", "0", "爱丽丝用·九节鞭", "克雷蒂亚家设计并制造的教官军用装备，使用幻化核心能量转化技术，可以将教鞭中储存的能量注入到队友的机甲中，以此来提高作战效能。\n爱丽丝大小姐，她是我们唯一的继承人，请更骄傲地抬起头吧，我会注视着您。", "蒂娜"},
[330021] = {330021, "Gin's\u{0020}High-Level\u{0020}Receiver", "The\u{0020}military\u{0020}equipment\u{0020}for\u{0020}instructors\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}Cretia\u{0020}family.\u{0020}Using\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}to\u{0020}increase\u{0020}the\u{0020}signal\u{0020}frequency.\u{0020}This\u{0020}equipment\u{0020}has\u{0020}anti-electromagnetic\u{0020}interference\u{0020}and\u{0020}strong\u{0020}communication\u{0020}capabilities.\nMiss\u{0020}Gin,\u{0020}the\u{0020}Cretia\u{0020}family\u{0020}does\u{0020}not\u{0020}have\u{0020}special\u{0020}requirements\u{0020}for\u{0020}you.\u{0020}Please\u{0020}live\u{0020}as\u{0020}the\u{0020}person\u{0020}you\u{0020}want\u{0020}to\u{0020}be\u{0020}at\u{0020}your\u{0020}own\u{0020}will.", "icon_dina_zs2", "0", 2, 2, "3_{lv}*100", "Tina", "1_110021_5", 10, "3_100", "330020,330021,330022", "0", "0", "0", "0", "0", "静用·高位接收器", "克雷蒂亚家设计并制造的教官军用装备，使用幻化核心来提升信号的频率，该装备拥有防电磁干扰和强大的通讯能力。\n静大小姐，克雷蒂亚家并不会对您有特别的要求，请好好地、按照自己意愿地，活成想要成为的人吧。", "蒂娜"},
[330022] = {330022, "The\u{0020}Unique\u{0020}Two", "The\u{0020}military\u{0020}equipment\u{0020}for\u{0020}instructors\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}the\u{0020}Cretia\u{0020}family.\u{0020}Made\u{0020}of\u{0020}a\u{0020}sufficient\u{0020}amount\u{0020}of\u{0020}alloy\u{0020}and\u{0020}embedded\u{0020}with\u{0020}a\u{0020}small\u{0020}number\u{0020}of\u{0020}Transformation\u{0020}Core\u{0020}chips.\u{0020}It\u{0020}is\u{0020}very\u{0020}sturdy\u{0020}and\u{0020}durable.\nYou\u{0020}two\u{0020}are\u{0020}both\u{0020}excellent\u{0020}people.", "icon_dina_zs3", "0", 2, 3, "8_{lv}*200", "Tina", "1_110021_5", 10, "8_200", "330020,330021,330022", "0", "0", "0", "0", "0", "独一无二的两人", "克雷蒂亚家设计并制造的教官军用装备，采用足量的合金，并镶嵌了少量的幻化核心晶片，非常结实耐用。\n你们两人都是很优秀的人呢。", "蒂娜"},
[330030] = {330030, "Ejector", "This\u{0020}equipment\u{0020}is\u{0020}a\u{0020}diagnostic\u{0020}and\u{0020}treatment\u{0020}tool\u{0020}developed\u{0020}for\u{0020}medical\u{0020}soldiers.\u{0020}Its\u{0020}appearance\u{0020}is\u{0020}similar\u{0020}to\u{0020}a\u{0020}military\u{0020}rifle.\u{0020}It\u{0020}uses\u{0020}burning\u{0020}Nimbus\u{0020}energy\u{0020}as\u{0020}kinetic\u{0020}energy\u{0020}to\u{0020}spray\u{0020}the\u{0020}liquid\u{0020}onto\u{0020}allies\u{0020}to\u{0020}achieve\u{0020}the\u{0020}purpose\u{0020}of\u{0020}diagnosis\u{0020}and\u{0020}treatment.\nCrim\u{0020}wanted\u{0020}to\u{0020}change\u{0020}the\u{0020}liquid\u{0020}in\u{0020}the\u{0020}gun\u{0020}barrel\u{0020}to\u{0020}pink,\u{0020}but\u{0020}was\u{0020}seriously\u{0020}stopped\u{0020}by\u{0020}everyone.", "icon_kelimu_zs1", "0", 2, 1, "3_{lv}*100", "Crim", "1_110021_5", 10, "3_100", "330030,330031,330032", "0", "0", "0", "0", "0", "喷射者", "该装备是为医疗兵种研制的一种诊疗工具，外观酷似军用步枪，以燃烧尼姆比斯能为动能，将枪管内的液体快速喷洒到友军身上，以此达到诊疗的目的。\n克里姆想把枪管内的液体换成粉红色，被大家严肃、快速地制止了。", "克里姆"},
[330031] = {330031, "Zhukov", "The\u{0020}first\u{0020}autonomous\u{0020}robot\u{0020}produced\u{0020}by\u{0020}the\u{0020}\"Siren\"\u{0020}company.\u{0020}Although\u{0020}its\u{0020}aesthetic\u{0020}design\u{0020}does\u{0020}not\u{0020}conform\u{0020}to\u{0020}the\u{0020}public's\u{0020}taste,\u{0020}it\u{0020}still\u{0020}has\u{0020}basic\u{0020}functions\u{0020}such\u{0020}as\u{0020}aerial\u{0020}photography\u{0020}and\u{0020}ammunition\u{0020}carrying.\u{0020}In\u{0020}addition,\u{0020}the\u{0020}main\u{0020}fuel\u{0020}of\u{0020}this\u{0020}robot\u{0020}is\u{0020}natural\u{0020}gas,\u{0020}so\u{0020}the\u{0020}cost\u{0020}is\u{0020}extremely\u{0020}low.\nFrom\u{0020}this\u{0020}equipment,\u{0020}we\u{0020}can\u{0020}see\u{0020}the\u{0020}poverty\u{0020}of\u{0020}[Ember].\u{0020}But\u{0020}this\u{0020}poverty\u{0020}is\u{0020}also\u{0020}the\u{0020}power\u{0020}to\u{0020}break\u{0020}through\u{0020}scientific\u{0020}research\u{0020}barriers.\u{0020}Replacing\u{0020}Nimbus\u{0020}energy\u{0020}with\u{0020}natural\u{0020}gas\u{0020}is\u{0020}something\u{0020}that\u{0020}people\u{0020}from\u{0020}AEGIS\u{0020}have\u{0020}never\u{0020}thought\u{0020}of.", "icon_kelimu_zs2", "0", 2, 2, "3_{lv}*100", "Crim", "1_110021_5", 10, "3_100", "330030,330031,330032", "0", "0", "0", "0", "0", "朱可夫", "“塞伦”公司生产的第一款自律机器人，虽然造型的审美上不是很符合大众的口味，但基本的功能还是具备的，比如航拍、弹药携带，另外该机器人的主要燃料为天然气，因此成本极低。\n从这件装备可以看出【灰烬】的贫穷，但同时这份贫穷也是突破科研关卡的力量，用天然气来取代了尼姆比斯能，这是艾吉斯的人从未设想的。", "克里姆"},
[330032] = {330032, "A\u{0020}Dream\u{0020}of\u{0020}Satiety", "Made\u{0020}by\u{0020}smelting\u{0020}high-density\u{0020}alloys,\u{0020}it\u{0020}has\u{0020}extremely\u{0020}thick\u{0020}armor,\u{0020}but\u{0020}it\u{0020}has\u{0020}certain\u{0020}requirements\u{0020}on\u{0020}the\u{0020}user's\u{0020}physique.\nCrim\u{0020}just\u{0020}wants\u{0020}everyone\u{0020}to\u{0020}have\u{0020}enough\u{0020}food...\u{0020}Indeed,\u{0020}this\u{0020}is\u{0020}childish\u{0020}and\u{0020}impossible\u{0020}to\u{0020}achieve.\u{0020}But\u{0020}when\u{0020}everyone\u{0020}sees\u{0020}Crim\u{0020}working\u{0020}hard\u{0020}for\u{0020}this\u{0020}goal,\u{0020}they\u{0020}unconsciously\u{0020}stand\u{0020}by\u{0020}her\u{0020}side.\u{0020}This\u{0020}is\u{0020}probably\u{0020}Crim's\u{0020}charm.", "icon_kelimu_zs3", "0", 2, 3, "8_{lv}*200", "Crim", "1_110021_5", 10, "8_200", "330030,330031,330032", "0", "0", "0", "0", "0", "饱腹的美梦", "由高密度的合金熔炼而成，拥有极厚的装甲，但对使用者的体格有一定要求。\n克里姆只是想让所有人都吃饱饭……诚然这是孩子气的话，是不可能实现的，但当大家看到为这个目标而努力的克里姆，就不自觉地站到了她的身边，这大概就是克里姆的魅力吧。", "克里姆"},
[330040] = {330040, "Celestial\u{0020}Purple\u{0020}Gold\u{0020}Gourd", "The\u{0020}new\u{0020}medical\u{0020}container\u{0020}developed\u{0020}by\u{0020}the\u{0020}special\u{0020}research\u{0020}institute\u{0020}of\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}It\u{0020}is\u{0020}embedded\u{0020}with\u{0020}a\u{0020}large\u{0020}number\u{0020}of\u{0020}high-frequency\u{0020}liquid\u{0020}medical\u{0020}robots,\u{0020}which\u{0020}can\u{0020}not\u{0020}only\u{0020}repair\u{0020}the\u{0020}body\u{0020}but\u{0020}also\u{0020}repair\u{0020}the\u{0020}armor.\nBut\u{0020}my\u{0020}gourd\u{0020}is\u{0020}green...", "icon_caihua_zs1", "0", 2, 1, "3_{lv}*100", "Caihua", "1_110021_5", 10, "3_100", "330040,330041,330042", "0", "0", "0", "0", "0", "凤鸣天紫金葫芦", "由九州总部特研科研制的新型医疗容器，内置装有大量的高频液态医疗机器人，不仅可以修复肉体还能对装甲进行修善。\n可是我的葫芦是绿色的……", "彩华"},
[330041] = {330041, "Demon-Binding\u{0020}Jade", "The\u{0020}exoskeleton\u{0020}developed\u{0020}by\u{0020}the\u{0020}special\u{0020}research\u{0020}institute\u{0020}of\u{0020}the\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}support\u{0020}type\u{0020}drivers.\u{0020}Although\u{0020}this\u{0020}armor\u{0020}cannot\u{0020}provide\u{0020}much\u{0020}protection,\u{0020}it\u{0020}is\u{0020}equipped\u{0020}with\u{0020}electric\u{0020}shock\u{0020}devices\u{0020}on\u{0020}the\u{0020}index\u{0020}finger\u{0020}and\u{0020}middle\u{0020}finger,\u{0020}which\u{0020}can\u{0020}provide\u{0020}electrotherapy\u{0020}to\u{0020}allies.\nIt\u{0020}can\u{0020}not\u{0020}only\u{0020}improve\u{0020}the\u{0020}medical\u{0020}effect\u{0020}but\u{0020}also\u{0020}be\u{0020}used\u{0020}as\u{0020}boxing\u{0020}gloves.\u{0020}This\u{0020}doctor\u{0020}has\u{0020}super\u{0020}physical\u{0020}skills...", "icon_caihua_zs2", "0", 2, 2, "3_{lv}*100", "Caihua", "1_110021_5", 10, "3_100", "330040,330041,330042", "0", "0", "0", "0", "0", "玉如意缚妖二极", "由九州总部特研科为支援型驾驶员研发的外骨骼，该装甲虽然提供不了什么防护，但是食指和中指装有电击设备，可以对友军提供电疗。\n不仅能提高医疗效果，还能当做拳套使用，这个医生的体术超强的……", "彩华"},
[330042] = {330042, "Immortal\u{0020}Pennant\u{0020}Cloud\u{0020}Clothes", "The\u{0020}exoskeleton\u{0020}developed\u{0020}by\u{0020}the\u{0020}special\u{0020}research\u{0020}institute\u{0020}of\u{0020}the\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}support-type\u{0020}drivers.\u{0020}This\u{0020}armor\u{0020}can\u{0020}greatly\u{0020}improve\u{0020}the\u{0020}protection\u{0020}ability\u{0020}of\u{0020}the\u{0020}wearer.\nA\u{0020}weak\u{0020}doctor\u{0020}is\u{0020}not\u{0020}worthy\u{0020}of\u{0020}standing\u{0020}on\u{0020}the\u{0020}battlefield.\u{0020}There\u{0020}must\u{0020}be\u{0020}one\u{0020}outstanding\u{0020}in\u{0020}physical\u{0020}strength\u{0020}or\u{0020}spirit.\u{0020}Caihua\u{0020}takes\u{0020}both\u{0020}into\u{0020}account.\u{0020}This\u{0020}equipment\u{0020}is\u{0020}said\u{0020}to\u{0020}be\u{0020}customized\u{0020}by\u{0020}her\u{0020}to\u{0020}increase\u{0020}weight\u{0020}training.", "icon_caihua_zs3", "0", 2, 3, "8_{lv}*200", "Caihua", "1_110021_5", 10, "8_200", "330040,330041,330042", "0", "0", "0", "0", "0", "紫绶仙幡云护衣", "由九州总部特研科为支援型驾驶员研发的外骨骼，该装甲可以大幅度的替身穿戴者的防护能力。\n孱弱的医生不配站在战场，在体能与精神上总要有一项拔尖，而彩华两者兼顾，这件装备听说是她为了给自己增加负重训练而定制的。", "彩华"},
[330050] = {330050, "Duty", "The\u{0020}medical\u{0020}injector\u{0020}for\u{0020}drivers\u{0020}independently\u{0020}developed\u{0020}by\u{0020}the\u{0020}military\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}This\u{0020}injector\u{0020}is\u{0020}made\u{0020}of\u{0020}light\u{0020}metal\u{0020}and\u{0020}is\u{0020}convenient\u{0020}for\u{0020}high-speed\u{0020}and\u{0020}long-distance\u{0020}movement\u{0020}when\u{0020}carried.\u{0020}It\u{0020}is\u{0020}designed\u{0020}to\u{0020}provide\u{0020}timely\u{0020}support\u{0020}for\u{0020}teammates\u{0020}and\u{0020}has\u{0020}strong\u{0020}stability\u{0020}and\u{0020}can\u{0020}be\u{0020}applied\u{0020}in\u{0020}various\u{0020}combat\u{0020}environments.\nThis\u{0020}is\u{0020}my\u{0020}weapon,\u{0020}and\u{0020}my\u{0020}battlefield\u{0020}is\u{0020}everywhere.", "icon_reniya_zs1", "0", 4, 1, "8_{lv}*200", "Genia", "1_110021_20", 10, "8_200", "330050,330051,330052", "0", "0", "0", "0", "0", "0", "0", "0"},
[330051] = {330051, "Caudal\u{0020}Communicator", "The\u{0020}tail-shaped\u{0020}communicator\u{0020}independently\u{0020}developed\u{0020}by\u{0020}the\u{0020}military\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}This\u{0020}communicator\u{0020}not\u{0020}only\u{0020}has\u{0020}basic\u{0020}communication\u{0020}functions\u{0020}but\u{0020}also\u{0020}has\u{0020}high-performance\u{0020}detection\u{0020}functions.\u{0020}On\u{0020}the\u{0020}battlefield,\u{0020}it\u{0020}can\u{0020}obtain\u{0020}the\u{0020}positions\u{0020}and\u{0020}injury\u{0020}status\u{0020}of\u{0020}both\u{0020}the\u{0020}enemy\u{0020}and\u{0020}ally\u{0020}at\u{0020}any\u{0020}time\u{0020}so\u{0020}that\u{0020}drivers\u{0020}can\u{0020}provide\u{0020}support.\nFaster\u{0020}support\u{0020}is\u{0020}snatching\u{0020}prey\u{0020}from\u{0020}the\u{0020}hands\u{0020}of\u{0020}the\u{0020}gods.", "icon_reniya_zs2", "0", 4, 2, "3_{lv}*100", "Genia", "1_110021_20", 10, "3_100", "330050,330051,330052", "0", "0", "0", "0", "0", "0", "0", "0"},
[330052] = {330052, "Protracted\u{0020}Battle\u{0020}with\u{0020}Death", "The\u{0020}medical\u{0020}box\u{0020}independently\u{0020}developed\u{0020}by\u{0020}the\u{0020}military\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}In\u{0020}order\u{0020}to\u{0020}be\u{0020}lightweight,\u{0020}it\u{0020}is\u{0020}made\u{0020}of\u{0020}light\u{0020}metal.\u{0020}It\u{0020}contains\u{0020}various\u{0020}medicine\u{0020}bottles\u{0020}and\u{0020}syringes\u{0020}of\u{0020}different\u{0020}calibers.\u{0020}While\u{0020}providing\u{0020}emergency\u{0020}treatment,\u{0020}it\u{0020}also\u{0020}considers\u{0020}the\u{0020}battlefield\u{0020}situation\u{0020}and\u{0020}is\u{0020}equipped\u{0020}with\u{0020}various\u{0020}drugs\u{0020}that\u{0020}enhance\u{0020}core\u{0020}activation.\nLong-term\u{0020}combat\u{0020}medical\u{0020}care\u{0020}is\u{0020}my\u{0020}specialty.\u{0020}No\u{0020}one\u{0020}can\u{0020}beat\u{0020}me\u{0020}in\u{0020}my\u{0020}field,\u{0020}not\u{0020}even\u{0020}gods.", "icon_reniya_zs3", "0", 4, 3, "8_{lv}*200", "Genia", "1_110021_20", 10, "8_200", "330050,330051,330052", "0", "0", "0", "0", "0", "0", "0", "0"},
[330060] = {330060, "Kagura\u{0020}Suzu", "Kagura\u{0020}Suzu\u{0020}once\u{0020}enshrined\u{0020}in\u{0020}the\u{0020}Shingyou\u{0020}Shrine.\u{0020}After\u{0020}purifying\u{0020}sin\u{0020}and\u{0020}absorbing\u{0020}the\u{0020}Transformation\u{0020}Core,\u{0020}it\u{0020}has\u{0020}obtained\u{0020}powerful\u{0020}ability\u{0020}to\u{0020}greatly\u{0020}increase\u{0020}the\u{0020}activity\u{0020}of\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}of\u{0020}drivers.\nJust\u{0020}having\u{0020}believers\u{0020}cannot\u{0020}run\u{0020}a\u{0020}shrine.\u{0020}Let\u{0020}me\u{0020}do\u{0020}it!", "icon_yingcao_zs1", "0", 2, 1, "3_{lv}*100", "Hotarugusa", "1_110021_5", 10, "3_100", "330060,330061,330062", "0", "0", "0", "0", "0", "神乐铃", "曾经供奉在心经神社的神乐铃，在净化原罪并吸收了幻化核心后，拥有了强大的力量，获得了能够大范围提升我方驾驶员幻化核心活性度的能力。\n光有信徒可无法支撑起一个神社的运营，就让大姐姐我来吧！", "莹草"},
[330061] = {330061, "Adviser\u{0020}of\u{0020}Shingyou\u{0020}House", "The\u{0020}leg\u{0020}alloy\u{0020}armor\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}Although\u{0020}it\u{0020}has\u{0020}a\u{0020}large\u{0020}coverage\u{0020}area,\u{0020}to\u{0020}ensure\u{0020}the\u{0020}mobility\u{0020}of\u{0020}the\u{0020}wearer,\u{0020}lighter\u{0020}materials\u{0020}are\u{0020}used.\nFor\u{0020}me,\u{0020}supporting\u{0020}these\u{0020}two\u{0020}people\u{0020}is\u{0020}not\u{0020}bad\u{0020}at\u{0020}all~", "icon_yingcao_zs2", "0", 2, 2, "8_{lv}*200", "Hotarugusa", "1_110021_5", 10, "8_200", "330060,330061,330062", "0", "0", "0", "0", "0", "心经屋的幕僚", "艾吉斯设计并制造的腿部合金装甲，覆盖面虽大，但为了保证穿戴者的机动力采用了较轻的材质。\n对于大姐姐我来说，支撑着这样的两个人也不赖呢~", "莹草"},
[330062] = {330062, "Impure\u{0020}Shrine\u{0020}Maiden", "The\u{0020}power\u{0020}device\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}by\u{0020}AEGIS.\u{0020}It\u{0020}generates\u{0020}huge\u{0020}propulsion\u{0020}force\u{0020}through\u{0020}the\u{0020}energy\u{0020}of\u{0020}the\u{0020}Transformation\u{0020}Core.\u{0020}Due\u{0020}to\u{0020}its\u{0020}large\u{0020}energy\u{0020}consumption,\u{0020}it\u{0020}is\u{0020}often\u{0020}equipped\u{0020}for\u{0020}support-type\u{0020}drivers.\nIs\u{0020}there\u{0020}still\u{0020}a\u{0020}pure\u{0020}shrine\u{0020}maiden\u{0020}in\u{0020}this\u{0020}era?!\u{0020}Um...\u{0020}Maybe\u{0020}the\u{0020}captain\u{0020}is\u{0020}one...", "icon_yingcao_zs3", "0", 2, 3, "8_{lv}*200", "Hotarugusa", "1_110021_5", 10, "8_200", "330060,330061,330062", "0", "0", "0", "0", "0", "不纯粹的巫女", "艾吉斯设计并制造的动力装置，通过幻化核心的能量产生巨大推进力，由于能量消耗较大因此常配备于支援型驾驶员。\n这个年代还有纯粹的巫女吗？！唔……也许队长算一个吧……", "莹草"},
[330070] = {330070, "Mechanical\u{0020}Angel\u{0020}·\u{0020}Automaton", "A\u{0020}support\u{0020}automaton\u{0020}for\u{0020}T,\u{0020}produced\u{0020}by\u{0020}Maya\u{0020}Branch\u{0020}using\u{0020}rare\u{0020}alloys.\u{0020}When\u{0020}linked\u{0020}to\u{0020}T,\u{0020}it\u{0020}draws\u{0020}power\u{0020}from\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}to\u{0020}operate\u{0020}and\u{0020}channels\u{0020}that\u{0020}energy\u{0020}to\u{0020}provide\u{0020}combat\u{0020}support.\nHumans...\u{0020}created\u{0020}me,\u{0020}yet\u{0020}they\u{0020}fear\u{0020}me.\u{0020}Why\u{0020}is\u{0020}that...?", "icon_txing_zs1", "0", 4, 1, "8_{lv}*200", "Type\u{0020}T", "1_110021_20", 10, "8_200", "330070,330071,330072", "0", "0", "0", "0", "0", "0", "0", "0"},
