[330080] = {330080, "Holy\u{0020}Spear", "The\u{0020}long-spear-shaped\u{0020}armament\u{0020}specially\u{0020}configured\u{0020}for\u{0020}dragon\u{0020}knights\u{0020}by\u{0020}the\u{0020}research\u{0020}laboratory\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}of\u{0020}AEGIS.\u{0020}Accompanying\u{0020}its\u{0020}huge\u{0020}size\u{0020}is\u{0020}its\u{0020}astonishing\u{0020}impact\u{0020}force,\u{0020}which\u{0020}can\u{0020}easily\u{0020}penetrate\u{0020}the\u{0020}armor\u{0020}of\u{0020}sin.\u{0020}The\u{0020}flag\u{0020}on\u{0020}the\u{0020}flank\u{0020}of\u{0020}the\u{0020}long\u{0020}spear\u{0020}is\u{0020}more\u{0020}a\u{0020}symbol\u{0020}of\u{0020}belief\u{0020}than\u{0020}practical\u{0020}use\u{0020}in\u{0020}combat.\nShining\u{0020}as\u{0020}a\u{0020}beacon\u{0020}to\u{0020}guide\u{0020}allies.", "icon_yishabeila_zs1", "0", 4, 1, "8_{lv}*200", "Isabella", "1_110021_20", 10, "8_200", "330080,330081,330082", "0", "0", "0", "0", "0", "0", "0", "0"},
[330081] = {330081, "Destined\u{0020}Horn\u{0020}Crown", "The\u{0020}communication\u{0020}device\u{0020}specially\u{0020}configured\u{0020}for\u{0020}dragon\u{0020}knights\u{0020}by\u{0020}the\u{0020}research\u{0020}laboratory\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}of\u{0020}AEGIS.\u{0020}Since\u{0020}dragon\u{0020}knights\u{0020}have\u{0020}the\u{0020}risk\u{0020}of\u{0020}going\u{0020}berserk,\u{0020}while\u{0020}having\u{0020}normal\u{0020}communication\u{0020}functions,\u{0020}it\u{0020}also\u{0020}plays\u{0020}a\u{0020}role\u{0020}in\u{0020}stabilizing\u{0020}the\u{0020}driver's\u{0020}brain\u{0020}waves.\nNever\u{0020}miss\u{0020}a\u{0020}word\u{0020}of\u{0020}destiny.", "icon_yishabeila_zs2", "0", 4, 2, "8_{lv}*200", "Isabella", "1_110021_20", 10, "8_200", "330080,330081,330082", "0", "0", "0", "0", "0", "0", "0", "0"},
[330082] = {330082, "Star\u{0020}Tail", "The\u{0020}power\u{0020}balance\u{0020}device\u{0020}specially\u{0020}configured\u{0020}for\u{0020}dragon\u{0020}knights\u{0020}by\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}of\u{0020}AEGIS.\u{0020}Since\u{0020}the\u{0020}dragon\u{0020}knight\u{0020}armor\u{0020}will\u{0020}increase\u{0020}energy\u{0020}consumption\u{0020}when\u{0020}maintaining\u{0020}a\u{0020}high\u{0020}output,\u{0020}which\u{0020}will\u{0020}lead\u{0020}to\u{0020}an\u{0020}increased\u{0020}demand\u{0020}for\u{0020}Nimbus.\u{0020}A\u{0020}power\u{0020}stabilization\u{0020}device\u{0020}is\u{0020}needed\u{0020}to\u{0020}prevent\u{0020}berserk.\nIf\u{0020}the\u{0020}tail\u{0020}is\u{0020}cut\u{0020}off\u{0020}in\u{0020}battle,\u{0020}it\u{0020}can\u{0020}also\u{0020}be\u{0020}turned\u{0020}into\u{0020}a\u{0020}new\u{0020}weapon.", "icon_yishabeila_zs3", "0", 4, 3, "8_{lv}*200", "Isabella", "1_110021_20", 10, "8_200", "330080,330081,330082", "0", "0", "0", "0", "0", "0", "0", "0"},
[330090] = {330090, "Diffusion\u{0020}Support\u{0020}Device", "The\u{0020}support\u{0020}device\u{0020}manufactured\u{0020}by\u{0020}Midyr's\u{0020}technology.\u{0020}It\u{0020}has\u{0020}a\u{0020}highly\u{0020}integrated\u{0020}imitation\u{0020}of\u{0020}Midyr\u{0020}amplification\u{0020}crystal\u{0020}built\u{0020}in.\u{0020}It\u{0020}can\u{0020}expand\u{0020}the\u{0020}support\u{0020}range\u{0020}of\u{0020}the\u{0020}user.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}it\u{0020}can\u{0020}even\u{0020}reach\u{0020}beyond\u{0020}the\u{0020}visual.\u{0020}But\u{0020}it\u{0020}has\u{0020}extremely\u{0020}high\u{0020}requirements\u{0020}on\u{0020}the\u{0020}mental\u{0020}power\u{0020}of\u{0020}the\u{0020}user.\u{0020}At\u{0020}present,\u{0020}only\u{0020}people\u{0020}from\u{0020}Midyr\u{0020}can\u{0020}use\u{0020}it.\n\"Even\u{0020}if\u{0020}you\u{0020}go\u{0020}to\u{0020}heaven\u{0020}after\u{0020}death,\u{0020}it\u{0020}is\u{0020}not\u{0020}as\u{0020}happy\u{0020}as\u{0020}being\u{0020}alive.\"", "icon_aiyiwadi_zs1", "0", 4, 1, "3_{lv}*100", "Aevati", "1_110021_20", 10, "3_100", "330090,330091,330092", "0", "0", "0", "0", "0", "扩散型支援装置", "米狄尔族科技制造的支援装置，内置高度集成的米狄尔增幅水晶仿制品，可以扩大使用者的支援范围，据说甚至能达到视野外。但是对使用者的精神力要求极高，目前只有米狄尔族的人勉强可以使用。\n“就算死后会上天堂，也不如活着感到幸福。”", "艾伊瓦蒂"},
[330091] = {330091, "Sensing\u{0020}Circuit", "The\u{0020}combat\u{0020}uniform\u{0020}manufactured\u{0020}by\u{0020}Midyr's\u{0020}technology.\u{0020}Through\u{0020}the\u{0020}energy\u{0020}circuit\u{0020}buried\u{0020}under\u{0020}the\u{0020}clothes,\u{0020}it\u{0020}accelerates\u{0020}the\u{0020}conduction\u{0020}of\u{0020}mental\u{0020}power.\u{0020}Of\u{0020}which\u{0020}the\u{0020}price\u{0020}is\u{0020}sacrificing\u{0020}defense\u{0020}ability.\u{0020}It\u{0020}is\u{0020}almost\u{0020}no\u{0020}stronger\u{0020}than\u{0020}being\u{0020}naked.\u{0020}But\u{0020}the\u{0020}style\u{0020}of\u{0020}clothes\u{0020}is\u{0020}said\u{0020}to\u{0020}be\u{0020}very\u{0020}popular\u{0020}among\u{0020}Midyr\u{0020}people.\n\"The\u{0020}journey\u{0020}will\u{0020}eventually\u{0020}end,\u{0020}but\u{0020}it\u{0020}should\u{0020}not\u{0020}be\u{0020}here.\"", "icon_aiyiwadi_zs2", "0", 4, 2, "8_{lv}*200", "Aevati", "1_110021_20", 10, "8_200", "330090,330091,330092", "0", "0", "0", "0", "0", "感应回路", "米狄尔族科技制造的战斗服，通过埋藏在衣服下的能量回路来加快精神力的传导。当然这样的代价就是牺牲了防御能力，几乎不比没穿衣服强多少。但是衣服的风格据说很受米狄尔族喜欢。\n“旅行终有终点，但不应该在这里。\u{0020}”", "艾伊瓦蒂"},
[330092] = {330092, "Support\u{0020}Floating\u{0020}Ring", "The\u{0020}floating\u{0020}ring\u{0020}manufactured\u{0020}by\u{0020}Midyr's\u{0020}technology.\u{0020}In\u{0020}addition\u{0020}to\u{0020}using\u{0020}special\u{0020}alloys\u{0020}in\u{0020}the\u{0020}manufacturing\u{0020}process,\u{0020}some\u{0020}fragments\u{0020}of\u{0020}amplification\u{0020}crystals\u{0020}are\u{0020}also\u{0020}added\u{0020}to\u{0020}enhance\u{0020}the\u{0020}amplification\u{0020}of\u{0020}the\u{0020}user's\u{0020}mental\u{0020}power.\u{0020}Of\u{0020}course,\u{0020}the\u{0020}standard\u{0020}battlefield\u{0020}information\u{0020}collection\u{0020}and\u{0020}communication\u{0020}functions\u{0020}are\u{0020}retained.\n\"Those\u{0020}buzzing\u{0020}noises\u{0020}in\u{0020}my\u{0020}mind\u{0020}may\u{0020}be\u{0020}the\u{0020}echoes\u{0020}of\u{0020}those\u{0020}civilizations.\"", "icon_aiyiwadi_zs3", "0", 4, 3, "8_{lv}*200", "Aevati", "1_110021_20", 10, "8_200", "330090,330091,330092", "0", "0", "0", "0", "0", "支援型浮游环", "米狄尔族科技制造的浮游环，制造过程中除了使用了特制合金，还加入了一些增幅水晶的碎末以此来加强了对使用者精神力的增幅。当然标准的战场信息收集和通讯功能也有保留。\n“那些在我脑海中滋滋作响的杂音，或许是那些文明的回响。”", "艾伊瓦蒂"},
[330100] = {330100, "Small\u{0020}Medical\u{0020}Gun", "The\u{0020}medical\u{0020}firearm\u{0020}designed\u{0020}by\u{0020}Mizo\u{0020}herself\u{0020}and\u{0020}commissioned\u{0020}to\u{0020}the\u{0020}Maya\u{0020}branch\u{0020}to\u{0020}make.\u{0020}It\u{0020}uses\u{0020}detachable\u{0020}liquid\u{0020}bullets\u{0020}as\u{0020}energy\u{0020}and\u{0020}shoots\u{0020}processed\u{0020}Nimbus\u{0020}at\u{0020}allies\u{0020}to\u{0020}achieve\u{0020}long-distance\u{0020}treatment.\n\"Don't\u{0020}worry,\u{0020}one\u{0020}shot\u{0020}won't\u{0020}kill\u{0020}you.\"", "icon_qu_zs1", "0", 3, 1, "8_{lv}*200", "Mizo", "1_110021_10", 10, "8_200", "330100,330101,330102", "0", "0", "0", "0", "0", "0", "0", "0"},
