[330102] = {330102, "Breathable\u{0020}and\u{0020}Warm\u{0020}Boots", "The\u{0020}boots\u{0020}designed\u{0020}by\u{0020}Mizo\u{0020}herself\u{0020}and\u{0020}commissioned\u{0020}to\u{0020}the\u{0020}Maya\u{0020}branch\u{0020}to\u{0020}make.\u{0020}The\u{0020}main\u{0020}function\u{0020}is\u{0020}to\u{0020}ensure\u{0020}the\u{0020}dryness\u{0020}and\u{0020}comfort\u{0020}of\u{0020}the\u{0020}legs.\n\"Comfortable...\u{0020}really\u{0020}comfortable.\"", "icon_qu_zs3", "0", 3, 3, "3_{lv}*100", "Mizo", "1_110021_10", 10, "3_100", "330100,330101,330102", "0", "0", "0", "0", "0", "0", "0", "0"},
[330110] = {330110, "Cup\u{0020}of\u{0020}Pure\u{0020}Grace", "Meria's\u{0020}AVG.\u{0020}Modeled\u{0020}after\u{0020}the\u{0020}Holy\u{0020}Church's\u{0020}relic,\u{0020}the\u{0020}golden\u{0020}chalice,\u{0020}which\u{0020}provides\u{0020}an\u{0020}inexhaustible\u{0020}source\u{0020}of\u{0020}whatever\u{0020}liquid\u{0020}placed\u{0020}within,\u{0020}according\u{0020}to\u{0020}scripture.\u{0020}The\u{0020}legend\u{0020}inspires\u{0020}her\u{0020}AVG's\u{0020}design,\u{0020}which\u{0020}leads\u{0020}to\u{0020}its\u{0020}unparalleled\u{0020}efficiency\u{0020}in\u{0020}harnessing\u{0020}liquid\u{0020}Nimbus\u{0020}energy.\nMeria\u{0020}once\u{0020}attempted\u{0020}to\u{0020}use\u{0020}the\u{0020}golden\u{0020}chalice\u{0020}to\u{0020}produce\u{0020}liquid\u{0020}gold.\u{0020}The\u{0020}outcome,\u{0020}as\u{0020}one\u{0020}might\u{0020}expect,\u{0020}was\u{0020}not\u{0020}as\u{0020}she\u{0020}had\u{0020}hoped.", "icon_meiliya_zs1", "0", 4, 1, "8_{lv}*200", "Meria", "1_110021_20", 10, "8_200", "330110,330111,330112", "0", "0", "0", "0", "0", "0", "0", "0"},
[330111] = {330111, "Holy\u{0020}Azure\u{0020}Robe", "Meria's\u{0020}AVG.\u{0020}Derived\u{0020}from\u{0020}the\u{0020}ceremonial\u{0020}attire\u{0020}she\u{0020}wears\u{0020}as\u{0020}the\u{0020}Saintess.\u{0020}The\u{0020}dominant\u{0020}use\u{0020}of\u{0020}white\u{0020}represents\u{0020}snow-draped\u{0020}mountains,\u{0020}while\u{0020}the\u{0020}blue\u{0020}holy\u{0020}spring\u{0020}running\u{0020}down,\u{0020}serves\u{0020}as\u{0020}a\u{0020}symbol\u{0020}of\u{0020}human\u{0020}ideals\u{0020}and\u{0020}virtues.\nMeria\u{0020}herself\u{0020}admits\u{0020}that\u{0020}wearing\u{0020}this\u{0020}outfit\u{0020}lifts\u{0020}her\u{0020}spirits\u{0020}slightly.", "icon_meiliya_zs2", "0", 4, 2, "3_{lv}*100", "Meria", "1_110021_20", 10, "3_100", "330110,330111,330112", "0", "0", "0", "0", "0", "0", "0", "0"},
